10: Write-Host '  ----------------------------------------------------'
11: 
12: if (Get-Process -Name 'Revit' -ErrorAction SilentlyContinue) {
13:     Write-Host ''
14:     Write-Host '  Revit is running. Close ALL Revit sessions, then run Install again.' -ForegroundColor Yellow
15:     Write-Host '  (Revit locks the add-in file while it is open.)'
16:     exit 1
17: }
18: 
19: # Files downloaded from the internet / Teams / e-mail are "blocked" by Windows and Revit refuses to load them.
20: Get-ChildItem -Path $here -Recurse -File | Unblock-File -ErrorAction SilentlyContinue
21: 
22: function Find-Revit([string]$v) {
23:     $candidates = @()
24:     foreach ($root in @($env:ProgramFiles, ${env:ProgramW6432})) {
25:         if ($root) { $candidates += (Join-Path $root "Autodesk\Revit $v") }
26:     }
27:     foreach ($key in @("HKLM:\SOFTWARE\Autodesk\Revit\$v\REVIT-05:0409", "HKLM:\SOFTWARE\Autodesk\Revit\Autodesk Revit $v")) {
28:         try { $p = (Get-ItemProperty -Path $key -ErrorAction Stop).InstallationLocation; if ($p) { $candidates += $p } } catch { }
29:     }
30:     foreach ($c in $candidates | Select-Object -Unique) {
31:         if ($c -and (Test-Path (Join-Path $c 'RevitAPI.dll'))) { return $c }
32:     }
33:     return $null
34: }
35: 
36: $done = @(); $skipped = @()
37: foreach ($v in @('2023', '2024', '2025', '2026', '2027')) {
38:     $src = Join-Path $files $v
39:     if (-not (Test-Path $src)) { continue }
40:     $dir = Find-Revit $v
41:     if (-not $dir) { $skipped += "Revit $v - not installed on this PC"; continue }
42: 
43:     $api = (Get-Item (Join-Path $dir 'RevitAPI.dll')).VersionInfo
44:     $apiText = "$($api.FileMajorPart).$($api.FileMinorPart)"
45:     if ($v -eq '2026' -and ($api.FileMajorPart -lt 26 -or ($api.FileMajorPart -eq 26 -and $api.FileMinorPart -lt 5))) {
46:         $skipped += "Revit 2026 - this PC has update $apiText; BIM Tools needs Revit 2026.5 or later (.NET 10). Update Revit 2026, then run Install again."
47:         continue
48:     }
49: 
50:     if ($v -eq '2025' -and ($api.FileMajorPart -lt 25 -or ($api.FileMajorPart -eq 25 -and $api.FileMinorPart -lt 5))) {
51:         $skipped += "Revit 2025 - this PC has update $apiText; BIM Tools needs Revit 2025.5 or later (.NET 10). Update Revit 2025, then run Install again."
52:         continue
53:     }
54: 
55:     $dest = Join-Path $addins $v
56:     New-Item -ItemType Directory -Force -Path (Join-Path $dest 'BIMToolsPrototype') | Out-Null
57:     Copy-Item -Force (Join-Path $src 'BIMToolsPrototype.addin') $dest
58:     Copy-Item -Force (Join-Path $src 'BIMToolsPrototype\BIMToolsPrototype.dll') (Join-Path $dest 'BIMToolsPrototype')
59:     Get-ChildItem -Path (Join-Path $dest 'BIMToolsPrototype') -Recurse -File | Unblock-File -ErrorAction SilentlyContinue
60:     Unblock-File -Path (Join-Path $dest 'BIMToolsPrototype.addin') -ErrorAction SilentlyContinue
61:     $done += "Revit $v ($apiText) -> $dest"
62: }
63: 
64: Write-Host ''
65: if ($done.Count -gt 0) {
66:     Write-Host '  Installed:' -ForegroundColor Green
67:     $done | ForEach-Object { Write-Host "    $_" }
68: }
69: if ($skipped.Count -gt 0) {
70:     Write-Host '  Skipped:' -ForegroundColor Yellow
71:     $skipped | ForEach-Object { Write-Host "    $_" }
72: }
73: Write-Host ''
74: if ($done.Count -gt 0) {
75:     Write-Host '  Start Revit. At the security prompt choose "Always Load".'
76:     Write-Host '  The tools are in the "BIM Tools Prototype" ribbon tab.'
77: } else {
78:     Write-Host '  Nothing was installed.' -ForegroundColor Yellow
79: }

