using System;
using System.IO;
using System.Text.Json;

namespace ORTools.Models
{
    /// <summary>
    /// Persistent per-user JSON settings manager stored in %AppData%\GOATBIM.
    /// Keeps user preferences intact across Revit sessions and add-in updates.
    /// </summary>
    public static class GoatSettingsManager
    {
        private static readonly string SettingsRoot = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
            "GOATBIM");

        private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
        {
            WriteIndented = true,
            PropertyNameCaseInsensitive = true
        };

        public static void Save<T>(string toolKey, T settings)
        {
            try
            {
                if (!Directory.Exists(SettingsRoot))
                {
                    Directory.CreateDirectory(SettingsRoot);
                }

                string filePath = Path.Combine(SettingsRoot, $"{SanitizeFileName(toolKey)}.json");
                string json = JsonSerializer.Serialize(settings, JsonOptions);
                File.WriteAllText(filePath, json);
            }
            catch
            {
                // Ignore IO errors silently so workflow is never blocked
            }
        }

        public static T Load<T>(string toolKey) where T : new()
        {
            try
            {
                string filePath = Path.Combine(SettingsRoot, $"{SanitizeFileName(toolKey)}.json");
                if (File.Exists(filePath))
                {
                    string json = File.ReadAllText(filePath);
                    T loaded = JsonSerializer.Deserialize<T>(json, JsonOptions);
                    if (loaded != null)
                        return loaded;
                }
            }
            catch
            {
            }

            return new T();
        }

        private static string SanitizeFileName(string name)
        {
            foreach (char c in Path.GetInvalidFileNameChars())
            {
                name = name.Replace(c, '_');
            }
            return name;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Xml.Linq;

namespace ORTools.Models
{
    public enum GoatCellStyle
    {
        NormalEditable = 0,
        HeaderNavy = 1,
        HeaderTeal = 2,
        ReadOnlyGrey = 3,
        HighlightYellow = 4,
        SummaryBold = 5
    }

    public class GoatExcelCell
    {
        public string Value { get; set; } = string.Empty;
        public string Formula { get; set; } = string.Empty;
        public bool IsNumeric { get; set; }
        public GoatCellStyle Style { get; set; } = GoatCellStyle.NormalEditable;

        public GoatExcelCell() { }

        public GoatExcelCell(string value, GoatCellStyle style = GoatCellStyle.NormalEditable, bool isNumeric = false, string formula = "")
        {
            Value = value ?? string.Empty;
            Style = style;
            IsNumeric = isNumeric;
            Formula = formula ?? string.Empty;
        }
    }

    public class GoatExcelSheet
    {
        public string Name { get; set; } = "Sheet1";
        public List<List<GoatExcelCell>> Rows { get; set; } = new List<List<GoatExcelCell>>();
        public List<double> ColumnWidths { get; set; } = new List<double>();
    }

    /// <summary>
    /// Self-contained OpenXML (.xlsx) multi-sheet reader and writer for GOAT BIM.
    /// Requires zero external NuGet packages and works even without Microsoft Excel installed.
    /// </summary>
    public static class GoatExcelEngine
    {
        public static void WriteXlsx(string filePath, IList<GoatExcelSheet> sheets)
        {
            if (sheets == null || sheets.Count == 0)
                throw new ArgumentException("At least one sheet is required.");

            if (File.Exists(filePath))
            {
                File.Delete(filePath);
            }

            using (FileStream fs = new FileStream(filePath, FileMode.CreateNew, FileAccess.ReadWrite))
            using (ZipArchive archive = new ZipArchive(fs, ZipArchiveMode.Create))
            {
                // 1. [Content_Types].xml
                WriteEntry(archive, "[Content_Types].xml", BuildContentTypesXml(sheets.Count));

                // 2. _rels/.rels
                WriteEntry(archive, "_rels/.rels", BuildRootRelsXml());

                // 3. xl/workbook.xml
                WriteEntry(archive, "xl/workbook.xml", BuildWorkbookXml(sheets));

                // 4. xl/_rels/workbook.xml.rels
                WriteEntry(archive, "xl/_rels/workbook.xml.rels", BuildWorkbookRelsXml(sheets.Count));

                // 5. xl/styles.xml
                WriteEntry(archive, "xl/styles.xml", BuildStylesXml());

                // 6. xl/worksheets/sheet{i}.xml
                for (int i = 0; i < sheets.Count; i++)
                {
                    WriteEntry(archive, $"xl/worksheets/sheet{i + 1}.xml", BuildWorksheetXml(sheets[i]));
                }
            }
        }

        public static Dictionary<string, List<List<string>>> ReadXlsx(string filePath)
        {
            var result = new Dictionary<string, List<List<string>>>(StringComparer.OrdinalIgnoreCase);
            if (!File.Exists(filePath))
                return result;

            using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            using (ZipArchive archive = new ZipArchive(fs, ZipArchiveMode.Read))
            {
                // Load shared strings if present
                List<string> sharedStrings = new List<string>();
                ZipArchiveEntry sstEntry = archive.GetEntry("xl/sharedStrings.xml");
                if (sstEntry != null)
                {
                    using (Stream s = sstEntry.Open())
                    {
                        XDocument sstDoc = XDocument.Load(s);
                        XNamespace ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
                        foreach (XElement si in sstDoc.Descendants(ns + "si"))
                        {
                            string text = string.Concat(si.Descendants(ns + "t").Select(t => t.Value));
                            sharedStrings.Add(text);
                        }
                    }
                }

                // Map sheet names to sheet paths
                var sheetMap = new List<(string Name, string Target)>();
                ZipArchiveEntry wbEntry = archive.GetEntry("xl/workbook.xml");
                ZipArchiveEntry relsEntry = archive.GetEntry("xl/_rels/workbook.xml.rels");
                if (wbEntry != null && relsEntry != null)
                {
                    XDocument wbDoc;
                    XDocument relsDoc;
                    using (Stream s = wbEntry.Open()) wbDoc = XDocument.Load(s);
                    using (Stream s = relsEntry.Open()) relsDoc = XDocument.Load(s);

                    XNamespace mainNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
                    XNamespace rNs = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
                    XNamespace pkgRelNs = "http://schemas.openxmlformats.org/package/2006/relationships";

                    var relDict = relsDoc.Descendants(pkgRelNs + "Relationship")
                        .ToDictionary(
                            x => x.Attribute("Id")?.Value ?? "",
                            x => x.Attribute("Target")?.Value ?? "");

                    foreach (XElement sh in wbDoc.Descendants(mainNs + "sheet"))
                    {
                        string name = sh.Attribute("name")?.Value ?? "Sheet";
                        string rId = sh.Attribute(rNs + "id")?.Value ?? "";
                        if (relDict.TryGetValue(rId, out string target))
                        {
                            if (!target.StartsWith("xl/"))
                                target = "xl/" + target.TrimStart('/');
                            sheetMap.Add((name, target));
                        }
                    }
                }

                foreach (var (name, target) in sheetMap)
                {
                    ZipArchiveEntry sheetEntry = archive.GetEntry(target);
                    if (sheetEntry == null) continue;

                    var rowsList = new List<List<string>>();
                    using (Stream s = sheetEntry.Open())
                    {
                        XDocument sheetDoc = XDocument.Load(s);
                        XNamespace ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";

                        foreach (XElement rowEl in sheetDoc.Descendants(ns + "row"))
                        {
                            var rowVals = new List<string>();
                            foreach (XElement cellEl in rowEl.Elements(ns + "c"))
                            {
                                string cellRef = cellEl.Attribute("r")?.Value ?? "";
                                int colIndex = GetColumnIndexFromCellReference(cellRef);
                                while (rowVals.Count < colIndex)
                                {
                                    rowVals.Add(string.Empty);
                                }

                                string tAttr = cellEl.Attribute("t")?.Value ?? "";
                                string val = string.Empty;
                                if (tAttr == "inlineStr")
                                {
                                    val = string.Concat(cellEl.Descendants(ns + "t").Select(x => x.Value));
                                }
                                else if (tAttr == "s")
                                {
                                    string idxStr = cellEl.Element(ns + "v")?.Value ?? "";
                                    if (int.TryParse(idxStr, out int sstIdx) && sstIdx >= 0 && sstIdx < sharedStrings.Count)
                                    {
                                        val = sharedStrings[sstIdx];
                                    }
                                }
                                else
                                {
                                    val = cellEl.Element(ns + "v")?.Value ?? string.Empty;
                                }

                                rowVals.Add(val);
                            }
                            rowsList.Add(rowVals);
                        }
                    }
                    result[name] = rowsList;
                }
            }

            return result;
        }

        private static void WriteEntry(ZipArchive archive, string entryPath, string xmlContent)
        {
            ZipArchiveEntry entry = archive.CreateEntry(entryPath, CompressionLevel.Fastest);
            using (Stream s = entry.Open())
            using (StreamWriter sw = new StreamWriter(s, new UTF8Encoding(false)))
            {
                sw.Write(xmlContent);
            }
        }

        private static string BuildContentTypesXml(int sheetCount)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine(@"<?xml version=""1.0"" encoding=""UTF-8"" standalone=""yes""?>");
            sb.AppendLine(@"<Types xmlns=""http://schemas.openxmlformats.org/package/2006/content-types"">");
            sb.AppendLine(@"  <Default Extension=""rels"" ContentType=""application/vnd.openxmlformats-package.relationships+xml""/>");
            sb.AppendLine(@"  <Default Extension=""xml"" ContentType=""application/xml""/>");
            sb.AppendLine(@"  <Override PartName=""/xl/workbook.xml"" ContentType=""application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml""/>");
            sb.AppendLine(@"  <Override PartName=""/xl/styles.xml"" ContentType=""application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml""/>");
            for (int i = 1; i <= sheetCount; i++)
            {
                sb.AppendLine($@"  <Override PartName=""/xl/worksheets/sheet{i}.xml"" ContentType=""application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml""/>");
            }
            sb.AppendLine(@"</Types>");
            return sb.ToString();
        }

        private static string BuildRootRelsXml()
        {
            return @"<?xml version=""1.0"" encoding=""UTF-8"" standalone=""yes""?>
<Relationships xmlns=""http://schemas.openxmlformats.org/package/2006/relationships"">
  <Relationship Id=""rId1"" Type=""http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"" Target=""xl/workbook.xml""/>
</Relationships>";
        }

        private static string BuildWorkbookXml(IList<GoatExcelSheet> sheets)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine(@"<?xml version=""1.0"" encoding=""UTF-8"" standalone=""yes""?>");
            sb.AppendLine(@"<workbook xmlns=""http://schemas.openxmlformats.org/spreadsheetml/2006/main"" xmlns:r=""http://schemas.openxmlformats.org/officeDocument/2006/relationships"">");
            sb.AppendLine(@"  <sheets>");
            for (int i = 0; i < sheets.Count; i++)
            {
                string safeName = EscapeXml(SanitizeSheetName(sheets[i].Name, i + 1));
                sb.AppendLine($@"    <sheet name=""{safeName}"" sheetId=""{i + 1}"" r:id=""rId{i + 1}""/>");
            }
            sb.AppendLine(@"  </sheets>");
            sb.AppendLine(@"</workbook>");
            return sb.ToString();
        }

        private static string BuildWorkbookRelsXml(int sheetCount)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine(@"<?xml version=""1.0"" encoding=""UTF-8"" standalone=""yes""?>");
            sb.AppendLine(@"<Relationships xmlns=""http://schemas.openxmlformats.org/package/2006/relationships"">");
            for (int i = 1; i <= sheetCount; i++)
            {
                sb.AppendLine($@"  <Relationship Id=""rId{i}"" Type=""http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet"" Target=""worksheets/sheet{i}.xml""/>");
            }
            sb.AppendLine($@"  <Relationship Id=""rId{sheetCount + 1}"" Type=""http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles"" Target=""styles.xml""/>");
            sb.AppendLine(@"</Relationships>");
            return sb.ToString();
        }

        private static string BuildStylesXml()
        {
            // Style indices:
            // 0 = Normal Editable (White bg, thin border)
            // 1 = Header Navy (#0F172A bg, White bold text)
            // 2 = Header Teal (#0284C7 bg, White bold text)
            // 3 = ReadOnly Grey (#F1F5F9 bg, #475569 text)
            // 4 = Highlight Yellow (#FEF3C7 bg, #92400E bold text)
            // 5 = Summary Bold (#ECFDF5 bg, #065F46 bold text)
            return @"<?xml version=""1.0"" encoding=""UTF-8"" standalone=""yes""?>
<styleSheet xmlns=""http://schemas.openxmlformats.org/spreadsheetml/2006/main"">
  <fonts count=""5"">
    <font><sz val=""10""/><color rgb=""FF1E293B""/><name val=""Segoe UI""/></font>
    <font><b/><sz val=""10.5""/><color rgb=""FFFFFFFF""/><name val=""Segoe UI""/></font>
    <font><sz val=""10""/><color rgb=""FF64748B""/><name val=""Segoe UI""/></font>
    <font><b/><sz val=""10""/><color rgb=""FF92400E""/><name val=""Segoe UI""/></font>
    <font><b/><sz val=""10""/><color rgb=""FF065F46""/><name val=""Segoe UI""/></font>
  </fonts>
  <fills count=""7"">
    <fill><patternFill patternType=""none""/></fill>
    <fill><patternFill patternType=""gray125""/></fill>
    <fill><patternFill patternType=""solid""><fgColor rgb=""FF0F172A""/></patternFill></fill>
    <fill><patternFill patternType=""solid""><fgColor rgb=""FF0284C7""/></patternFill></fill>
    <fill><patternFill patternType=""solid""><fgColor rgb=""FFF1F5F9""/></patternFill></fill>
    <fill><patternFill patternType=""solid""><fgColor rgb=""FFFEF3C7""/></patternFill></fill>
    <fill><patternFill patternType=""solid""><fgColor rgb=""FFECFDF5""/></patternFill></fill>
  </fills>
  <borders count=""2"">
    <border><left/><right/><top/><bottom/><diagonal/></border>
    <border>
      <left style=""thin""><color rgb=""FFCBD5E1""/></left>
      <right style=""thin""><color rgb=""FFCBD5E1""/></right>
      <top style=""thin""><color rgb=""FFCBD5E1""/></top>
      <bottom style=""thin""><color rgb=""FFCBD5E1""/></bottom>
      <diagonal/>
    </border>
  </borders>
  <cellStyleXfs count=""1"">
    <xf numFmtId=""0"" fontId=""0"" fillId=""0"" borderId=""0""/>
  </cellStyleXfs>
  <cellXfs count=""6"">
    <xf numFmtId=""0"" fontId=""0"" fillId=""0"" borderId=""1"" xfId=""0"" applyBorder=""1""/>
    <xf numFmtId=""0"" fontId=""1"" fillId=""2"" borderId=""1"" xfId=""0"" applyFont=""1"" applyFill=""1"" applyBorder=""1""/>
    <xf numFmtId=""0"" fontId=""1"" fillId=""3"" borderId=""1"" xfId=""0"" applyFont=""1"" applyFill=""1"" applyBorder=""1""/>
    <xf numFmtId=""0"" fontId=""2"" fillId=""4"" borderId=""1"" xfId=""0"" applyFont=""1"" applyFill=""1"" applyBorder=""1""/>
    <xf numFmtId=""0"" fontId=""3"" fillId=""5"" borderId=""1"" xfId=""0"" applyFont=""1"" applyFill=""1"" applyBorder=""1""/>
    <xf numFmtId=""0"" fontId=""4"" fillId=""6"" borderId=""1"" xfId=""0"" applyFont=""1"" applyFill=""1"" applyBorder=""1""/>
  </cellXfs>
</styleSheet>";
        }

        private static string BuildWorksheetXml(GoatExcelSheet sheet)
        {
            StringBuilder sb = new StringBuilder();
            sb.AppendLine(@"<?xml version=""1.0"" encoding=""UTF-8"" standalone=""yes""?>");
            sb.AppendLine(@"<worksheet xmlns=""http://schemas.openxmlformats.org/spreadsheetml/2006/main"">");

            if (sheet.ColumnWidths != null && sheet.ColumnWidths.Count > 0)
            {
                sb.AppendLine(@"  <cols>");
                for (int c = 0; c < sheet.ColumnWidths.Count; c++)
                {
                    double w = sheet.ColumnWidths[c] > 4 ? sheet.ColumnWidths[c] : 18;
                    sb.AppendLine($@"    <col min=""{c + 1}"" max=""{c + 1}"" width=""{w.ToString("0.##", CultureInfo.InvariantCulture)}"" customWidth=""1""/>");
                }
                sb.AppendLine(@"  </cols>");
            }

            sb.AppendLine(@"  <sheetData>");
            for (int r = 0; r < sheet.Rows.Count; r++)
            {
                int rowNum = r + 1;
                var row = sheet.Rows[r];
                sb.AppendLine($@"    <row r=""{rowNum}"">");
                for (int c = 0; c < row.Count; c++)
                {
                    var cell = row[c] ?? new GoatExcelCell();
                    string cellRef = GetColumnName(c) + rowNum.ToString(CultureInfo.InvariantCulture);
                    int styleIdx = (int)cell.Style;

                    if (!string.IsNullOrWhiteSpace(cell.Formula))
                    {
                        string cleanFormula = EscapeXml(cell.Formula.TrimStart('='));
                        string fallbackVal = EscapeXml(cell.Value ?? string.Empty);
                        sb.AppendLine($@"      <c r=""{cellRef}"" s=""{styleIdx}"" t=""str""><f>{cleanFormula}</f><v>{fallbackVal}</v></c>");
                    }
                    else if (cell.IsNumeric && double.TryParse(cell.Value, NumberStyles.Any, CultureInfo.InvariantCulture, out double numVal))
                    {
                        sb.AppendLine($@"      <c r=""{cellRef}"" s=""{styleIdx}""><v>{numVal.ToString(CultureInfo.InvariantCulture)}</v></c>");
                    }
                    else
                    {
                        string escapedText = EscapeXml(cell.Value ?? string.Empty);
                        sb.AppendLine($@"      <c r=""{cellRef}"" s=""{styleIdx}"" t=""inlineStr""><is><t xml:space=""preserve"">{escapedText}</t></is></c>");
                    }
                }
                sb.AppendLine(@"    </row>");
            }
            sb.AppendLine(@"  </sheetData>");
            sb.AppendLine(@"</worksheet>");
            return sb.ToString();
        }

        public static string GetColumnName(int zeroBasedColumnIndex)
        {
            int dividend = zeroBasedColumnIndex + 1;
            string columnName = string.Empty;
            while (dividend > 0)
            {
                int modulo = (dividend - 1) % 26;
                columnName = Convert.ToChar(65 + modulo) + columnName;
                dividend = (dividend - modulo) / 26;
            }
            return columnName;
        }

        private static int GetColumnIndexFromCellReference(string cellRef)
        {
            if (string.IsNullOrEmpty(cellRef)) return 0;
            int colIndex = 0;
            foreach (char ch in cellRef)
            {
                if (char.IsLetter(ch))
                {
                    colIndex = colIndex * 26 + (char.ToUpperInvariant(ch) - 'A' + 1);
                }
                else
                {
                    break;
                }
            }
            return Math.Max(0, colIndex - 1);
        }

        private static string SanitizeSheetName(string name, int index)
        {
            if (string.IsNullOrWhiteSpace(name)) return $"Sheet{index}";
            char[] invalid = { '\\', '/', '?', '*', ':', '[', ']' };
            foreach (char c in invalid)
            {
                name = name.Replace(c, '_');
            }
            return name.Length > 31 ? name.Substring(0, 31) : name;
        }

        private static string EscapeXml(string input)
        {
            if (string.IsNullOrEmpty(input)) return string.Empty;
            return input
                .Replace("&", "&amp;")
                .Replace("<", "&lt;")
                .Replace(">", "&gt;")
                .Replace("\"", "&quot;")
                .Replace("'", "&apos;");
        }
    }
}

using System;
using System.Globalization;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace ORTools.UI
{
    /// <summary>
    /// High-DPI Vector Icon &amp; Badge Renderer for GOAT BIM Ribbon buttons (32x32 &amp; 16x16) and Window Headers (48x48).
    /// Ensures cohesive Dark Navy (#0F172A) + Emerald (#10B981) + Sky (#38BDF8) identity across all 16 tools.
    /// </summary>
    public static class GoatIconFactory
    {
        private static readonly Brush NavyBg = Freeze(new SolidColorBrush(Color.FromRgb(15, 23, 42)));       // #0F172A
        private static readonly Brush NavyInner = Freeze(new SolidColorBrush(Color.FromRgb(30, 41, 59)));    // #1E293B
        private static readonly Brush BorderStroke = Freeze(new SolidColorBrush(Color.FromRgb(56, 189, 248))); // #38BDF8
        private static readonly Brush EmeraldBrush = Freeze(new SolidColorBrush(Color.FromRgb(16, 185, 129))); // #10B981
        private static readonly Brush SkyBrush = Freeze(new SolidColorBrush(Color.FromRgb(56, 189, 248)));     // #38BDF8
        private static readonly Brush AmberBrush = Freeze(new SolidColorBrush(Color.FromRgb(245, 158, 11)));   // #F59E0B
        private static readonly Brush WhiteBrush = Freeze(new SolidColorBrush(Colors.White));
        private static readonly Brush MutedBrush = Freeze(new SolidColorBrush(Color.FromRgb(148, 163, 184)));

        private static T Freeze<T>(T freezable) where T : Freezable
        {
            if (freezable.CanFreeze) freezable.Freeze();
            return freezable;
        }

        public static BitmapSource CreateRibbonIcon(string toolKey, int size)
        {
            DrawingVisual dv = new DrawingVisual();
            using (DrawingContext dc = dv.RenderOpen())
            {
                double s = size;
                double radius = Math.Max(3.0, s * 0.18);
                Pen borderPen = new Pen(BorderStroke, Math.Max(1.0, s * 0.045));

                // Background rounded badge
                dc.DrawRoundedRectangle(NavyBg, borderPen, new Rect(0.5, 0.5, s - 1, s - 1), radius, radius);

                // Normalize drawing to 32x32 coordinate space
                dc.PushTransform(new ScaleTransform(s / 32.0, s / 32.0));
                DrawToolGlyph32(dc, toolKey?.ToUpperInvariant() ?? "GOAT");
                dc.Pop();
            }

            RenderTargetBitmap rtb = new RenderTargetBitmap(size, size, 96, 96, PixelFormats.Pbgra32);
            rtb.Render(dv);
            rtb.Freeze();
            return rtb;
        }

        public static BitmapSource CreateHeaderBadge(string subtitle)
        {
            int size = 48;
            DrawingVisual dv = new DrawingVisual();
            using (DrawingContext dc = dv.RenderOpen())
            {
                Pen whiteBorder = new Pen(WhiteBrush, 1.5);
                dc.DrawRoundedRectangle(Brushes.Black, whiteBorder, new Rect(1, 1, size - 2, size - 2), 7, 7);

                Typeface tf = new Typeface(new FontFamily("Segoe UI"), FontStyles.Normal, FontWeights.ExtraBold, FontStretches.Normal);

                FormattedText topTxt = new FormattedText(
                    "GOAT",
                    CultureInfo.InvariantCulture,
                    FlowDirection.LeftToRight,
                    tf,
                    10.5,
                    WhiteBrush,
                    1.25);
                dc.DrawText(topTxt, new Point((size - topTxt.Width) / 2.0, 10));

                string sub = string.IsNullOrWhiteSpace(subtitle) ? "BIM" : subtitle.ToUpperInvariant();
                double subFontSize = sub.Length > 7 ? 7.0 : (sub.Length > 5 ? 8.0 : 9.5);
                FormattedText botTxt = new FormattedText(
                    sub,
                    CultureInfo.InvariantCulture,
                    FlowDirection.LeftToRight,
                    tf,
                    subFontSize,
                    EmeraldBrush,
                    1.25);
                dc.DrawText(botTxt, new Point((size - botTxt.Width) / 2.0, 25));
            }

            RenderTargetBitmap rtb = new RenderTargetBitmap(size, size, 96, 96, PixelFormats.Pbgra32);
            rtb.Render(dv);
            rtb.Freeze();
            return rtb;
        }

        private static void DrawToolGlyph32(DrawingContext dc, string key)
        {
            Pen whitePen = new Pen(WhiteBrush, 2.0) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round };
            Pen skyPen = new Pen(SkyBrush, 2.0) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round };
            Pen emeraldPen = new Pen(EmeraldBrush, 2.0) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round };
            Pen amberPen = new Pen(AmberBrush, 2.0) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round };

            switch (key)
            {
                case "LEVELS":
                    // Datum lines + elevation triangle markers
                    dc.DrawLine(whitePen, new Point(6, 10), new Point(22, 10));
                    dc.DrawLine(skyPen, new Point(6, 17), new Point(22, 17));
                    dc.DrawLine(emeraldPen, new Point(6, 24), new Point(22, 24));
                    dc.DrawEllipse(EmeraldBrush, null, new Point(25, 10), 2.5, 2.5);
                    dc.DrawEllipse(SkyBrush, null, new Point(25, 17), 2.5, 2.5);
                    dc.DrawEllipse(AmberBrush, null, new Point(25, 24), 2.5, 2.5);
                    break;

                case "GRIDS":
                    // Orthogonal + radial grid lines with bubbles
                    dc.DrawLine(skyPen, new Point(11, 8), new Point(11, 26));
                    dc.DrawLine(skyPen, new Point(21, 8), new Point(21, 26));
                    dc.DrawLine(whitePen, new Point(6, 13), new Point(26, 13));
                    dc.DrawLine(whitePen, new Point(6, 22), new Point(26, 22));
                    dc.DrawEllipse(EmeraldBrush, null, new Point(11, 6), 2.5, 2.5);
                    dc.DrawEllipse(EmeraldBrush, null, new Point(21, 6), 2.5, 2.5);
                    break;

                case "PARAMETER":
                    // Sliders / tuning controls
                    dc.DrawLine(whitePen, new Point(7, 10), new Point(25, 10));
                    dc.DrawLine(whitePen, new Point(7, 16), new Point(25, 16));
                    dc.DrawLine(whitePen, new Point(7, 22), new Point(25, 22));
                    dc.DrawEllipse(EmeraldBrush, null, new Point(12, 10), 3.0, 3.0);
                    dc.DrawEllipse(SkyBrush, null, new Point(20, 16), 3.0, 3.0);
                    dc.DrawEllipse(AmberBrush, null, new Point(14, 22), 3.0, 3.0);
                    break;

                case "SHEETLINK":
                    // Excel table + bidirectional sync arrows
                    dc.DrawRoundedRectangle(NavyInner, emeraldPen, new Rect(6, 7, 20, 18), 2, 2);
                    dc.DrawLine(emeraldPen, new Point(6, 13), new Point(26, 13));
                    dc.DrawLine(whitePen, new Point(14, 13), new Point(14, 25));
                    dc.DrawLine(skyPen, new Point(18, 17), new Point(23, 17));
                    dc.DrawLine(amberPen, new Point(18, 21), new Point(23, 21));
                    break;

                case "RENUMBER":
                    // 1 -> 2 -> 3 badge sequence
                    DrawBadgeText(dc, "1·2·3", 16, 11, 8.5, EmeraldBrush);
                    dc.DrawLine(skyPen, new Point(7, 22), new Point(25, 22));
                    dc.DrawLine(skyPen, new Point(21, 19), new Point(25, 22));
                    dc.DrawLine(skyPen, new Point(21, 25), new Point(25, 22));
                    break;

                case "BOQ":
                    // Bar chart + cost/quantity check
                    dc.DrawRectangle(SkyBrush, null, new Rect(7, 17, 4, 9));
                    dc.DrawRectangle(EmeraldBrush, null, new Rect(14, 12, 4, 14));
                    dc.DrawRectangle(AmberBrush, null, new Rect(21, 7, 4, 19));
                    break;

                case "FINISHES":
                    // Room outer core + inner finish wall + floor layer
                    dc.DrawRectangle(null, whitePen, new Rect(6, 6, 20, 20));
                    dc.DrawRectangle(null, skyPen, new Rect(9.5, 9.5, 13, 13));
                    dc.DrawLine(amberPen, new Point(9.5, 22.5), new Point(22.5, 22.5));
                    dc.DrawEllipse(EmeraldBrush, null, new Point(16, 16), 2.5, 2.5);
                    break;

                case "ARCH":
                    // Classical architectural arch + keystone
                    PathGeometry archGeo = new PathGeometry();
                    PathFigure pf = new PathFigure { StartPoint = new Point(8, 25), IsClosed = false };
                    pf.Segments.Add(new LineSegment(new Point(8, 15), true));
                    pf.Segments.Add(new ArcSegment(new Point(24, 15), new Size(8, 8), 0, false, SweepDirection.Clockwise, true));
                    pf.Segments.Add(new LineSegment(new Point(24, 25), true));
                    archGeo.Figures.Add(pf);
                    dc.DrawGeometry(null, skyPen, archGeo);
                    dc.DrawRectangle(AmberBrush, null, new Rect(14.5, 5.5, 3, 3.5));
                    break;

                case "CEILING":
                    // 60x60 ceiling grid + lighting fixture nodes
                    dc.DrawRectangle(null, whitePen, new Rect(6, 6, 20, 20));
                    dc.DrawLine( new Pen(MutedBrush, 1.0), new Point(16, 6), new Point(16, 26));
                    dc.DrawLine( new Pen(MutedBrush, 1.0), new Point(6, 16), new Point(26, 16));
                    dc.DrawEllipse(AmberBrush, null, new Point(11, 11), 2.2, 2.2);
                    dc.DrawEllipse(AmberBrush, null, new Point(21, 11), 2.2, 2.2);
                    dc.DrawEllipse(EmeraldBrush, null, new Point(11, 21), 2.2, 2.2);
                    dc.DrawEllipse(EmeraldBrush, null, new Point(21, 21), 2.2, 2.2);
                    break;

                case "D_VIEW":
                    // Door elevation + swing arc
                    dc.DrawRectangle(null, whitePen, new Rect(8, 6, 11, 20));
                    dc.DrawEllipse(AmberBrush, null, new Point(16.5, 16), 1.3, 1.3);
                    dc.DrawLine(emeraldPen, new Point(22, 8), new Point(26, 8));
                    dc.DrawLine(skyPen, new Point(22, 14), new Point(26, 14));
                    break;

                case "W_VIEW":
                    // 4-pane window icon
                    dc.DrawRectangle(null, skyPen, new Rect(7, 7, 18, 18));
                    dc.DrawLine(whitePen, new Point(16, 7), new Point(16, 25));
                    dc.DrawLine(whitePen, new Point(7, 16), new Point(25, 16));
                    break;

                case "ROOM":
                    // Room elevation target marker (N/S/E/W arrows)
                    dc.DrawEllipse(NavyInner, whitePen, new Point(16, 16), 6, 6);
                    dc.DrawLine(emeraldPen, new Point(16, 5), new Point(16, 10));
                    dc.DrawLine(emeraldPen, new Point(16, 22), new Point(16, 27));
                    dc.DrawLine(skyPen, new Point(5, 16), new Point(10, 16));
                    dc.DrawLine(skyPen, new Point(22, 16), new Point(27, 16));
                    break;

                case "DIM":
                    // Dimension line with witnesses and ticks
                    dc.DrawLine(whitePen, new Point(7, 9), new Point(7, 23));
                    dc.DrawLine(whitePen, new Point(25, 9), new Point(25, 23));
                    dc.DrawLine(emeraldPen, new Point(7, 16), new Point(25, 16));
                    dc.DrawLine(amberPen, new Point(5, 18), new Point(9, 14));
                    dc.DrawLine(amberPen, new Point(23, 18), new Point(27, 14));
                    break;

                case "ANNOTATE":
                    // Tag head + leader elbow
                    dc.DrawRoundedRectangle(NavyInner, skyPen, new Rect(9, 7, 16, 10), 2, 2);
                    dc.DrawLine(emeraldPen, new Point(13, 17), new Point(9, 24));
                    dc.DrawEllipse(AmberBrush, null, new Point(8, 25), 2.0, 2.0);
                    break;

                case "ALIGNER":
                    // Viewport grid alignment blocks
                    dc.DrawRectangle(SkyBrush, null, new Rect(7, 8, 8, 7));
                    dc.DrawRectangle(EmeraldBrush, null, new Rect(17, 8, 8, 7));
                    dc.DrawRectangle(EmeraldBrush, null, new Rect(7, 17, 8, 7));
                    dc.DrawRectangle(AmberBrush, null, new Rect(17, 17, 8, 7));
                    break;

                case "SHEETS":
                    // Sheet titleblock stack
                    dc.DrawRectangle(NavyInner, whitePen, new Rect(6, 8, 20, 16));
                    dc.DrawLine(emeraldPen, new Point(20, 8), new Point(20, 24));
                    dc.DrawLine(skyPen, new Point(9, 13), new Point(17, 13));
                    dc.DrawLine(skyPen, new Point(9, 18), new Point(17, 18));
                    break;

                case "ABOUT":
                default:
                    DrawBadgeText(dc, "GOAT", 16, 10, 7.5, WhiteBrush);
                    DrawBadgeText(dc, "BIM", 16, 19, 7.5, EmeraldBrush);
                    break;
            }
        }

        private static void DrawBadgeText(DrawingContext dc, string text, double centerX, double topY, double fontSize, Brush brush)
        {
            Typeface tf = new Typeface(new FontFamily("Segoe UI"), FontStyles.Normal, FontWeights.ExtraBold, FontStretches.Normal);
            FormattedText ft = new FormattedText(
                text,
                CultureInfo.InvariantCulture,
                FlowDirection.LeftToRight,
                tf,
                fontSize,
                brush,
                1.25);
            dc.DrawText(ft, new Point(centerX - ft.Width / 2.0, topY));
        }
    }
}

