        private void BtnExportExcel_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var selected = RoomList.Where(r => r.IsSelected).ToList();
                if (selected.Count == 0)
                {
                    MessageBox.Show("Please select at least one room to export.", "GOAT FINISHES", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                SaveFileDialog sfd = new SaveFileDialog
                {
                    Title = "Export GOAT FINISHES Room Schedule & QTO to Excel (.xlsx)",
                    Filter = "Excel Workbook (*.xlsx)|*.xlsx",
                    FileName = $"GOAT_RoomFinishes_QTO_{DateTime.Now:yyyyMMdd_HHmm}.xlsx"
                };

                if (sfd.ShowDialog() != true) return;

                GoatFinishesSettings cfg = CollectCurrentSettings();
                double wallHeightMeters = (cfg.WallTopAtCeiling ? (cfg.CeilingHeightMm + cfg.CeilingVoidOffsetMm) : 3000.0) / 1000.0;

                // Sheet 1: Room Finishes & QTO Schedule
                var sheet1 = new GoatExcelSheet
                {
                    Name = "Room Finishes QTO",
                    ColumnWidths = new List<double> { 14, 14, 24, 18, 14, 16, 26, 24, 24, 24, 18 }
                };

                sheet1.Rows.Add(new List<GoatExcelCell>
                {
                    new GoatExcelCell("ElementId", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Room Number", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Room Name", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Level", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Net Area (m²)", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Perimeter (m)", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Wall Finish Type", GoatCellStyle.HeaderTeal),
                    new GoatExcelCell("Skirting Finish Type", GoatCellStyle.HeaderTeal),
                    new GoatExcelCell("Floor Finish Type", GoatCellStyle.HeaderTeal),
                    new GoatExcelCell("Ceiling Finish Type", GoatCellStyle.HeaderTeal),
                    new GoatExcelCell("Est. Wall Area (m²)", GoatCellStyle.HeaderNavy)
                });

                double totalArea = 0;
                double totalPerimM = 0;
                double totalWallArea = 0;

                foreach (var r in selected)
                {
                    double perimM = Math.Round(r.PerimeterMm / 1000.0, 2);
                    double estWallSqm = Math.Round(perimM * wallHeightMeters, 2);
                    totalArea += r.AreaSqm;
                    totalPerimM += perimM;
                    totalWallArea += estWallSqm;

                    string wf = !string.IsNullOrWhiteSpace(r.WallFinishParam) ? r.WallFinishParam : cfg.SelectedWallTypeName;
                    string bf = !string.IsNullOrWhiteSpace(r.BaseFinishParam) ? r.BaseFinishParam : cfg.SelectedSkirtingTypeName;
                    string ff = !string.IsNullOrWhiteSpace(r.FloorFinishParam) ? r.FloorFinishParam : cfg.SelectedFloorTypeName;
                    string cf = !string.IsNullOrWhiteSpace(r.CeilingFinishParam) ? r.CeilingFinishParam : cfg.SelectedCeilingTypeName;

                    sheet1.Rows.Add(new List<GoatExcelCell>
                    {
                        new GoatExcelCell(r.RoomId.Value.ToString(), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(r.RoomNumber, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(r.RoomName, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(r.LevelName, GoatCellStyle.ReadOnlyGrey),
                        new GoatExcelCell(r.AreaSqm.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(perimM.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(wf, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(bf, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(ff, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(cf, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(estWallSqm.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true)
                    });
                }

                // Summary Row
                sheet1.Rows.Add(new List<GoatExcelCell>
                {
                    new GoatExcelCell("TOTAL", GoatCellStyle.SummaryBold),
                    new GoatExcelCell($"{selected.Count} Rooms", GoatCellStyle.SummaryBold),
                    new GoatExcelCell("", GoatCellStyle.SummaryBold),
                    new GoatExcelCell("", GoatCellStyle.SummaryBold),
                    new GoatExcelCell(totalArea.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.SummaryBold, true),
                    new GoatExcelCell(totalPerimM.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.SummaryBold, true),
                    new GoatExcelCell("", GoatCellStyle.SummaryBold),
                    new GoatExcelCell("", GoatCellStyle.SummaryBold),
                    new GoatExcelCell("", GoatCellStyle.SummaryBold),
                    new GoatExcelCell("", GoatCellStyle.SummaryBold),
                    new GoatExcelCell(totalWallArea.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.SummaryBold, true)
                });

                GoatExcelEngine.WriteXlsx(sfd.FileName, new List<GoatExcelSheet> { sheet1 });
                UpdateStatus($"✔ Exported {selected.Count} rooms QTO schedule to {System.IO.Path.GetFileName(sfd.FileName)}", false);

                try
                {
                    Process.Start(new ProcessStartInfo { FileName = sfd.FileName, UseShellExecute = true });
                }
                catch { }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Excel Export Error:\n{ex.Message}", "GOAT FINISHES", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        // --- LIVE INTERACTIVE PLAN & SECTION PREVIEW RENDERING ---

        private void RenderPlanPreview()
        {
            if (CanvasPlanPreview == null) return;
            CanvasPlanPreview.Children.Clear();

            double w = CanvasPlanPreview.ActualWidth;
            double h = CanvasPlanPreview.ActualHeight;
            if (w < 40 || h < 40) return;

            var selRoom = DgRooms?.SelectedItem as RoomFinishItem ?? RoomList.FirstOrDefault();
            if (TxtPlanPreviewHeader != null)
            {
                TxtPlanPreviewHeader.Text = selRoom != null
                    ? $"PLAN PREVIEW: {selRoom.DisplayName} ({selRoom.AreaSqm:0.0} m²)"
                    : "PLAN PREVIEW: Room Boundary & Walls";
            }

            bool showFinishWalls = ChkCreateWalls?.IsChecked == true;
            bool breakDoors = ChkOptBreakAtDoors?.IsChecked == true;

            // Outer Host Wall Core Polygon
            double padX = w * 0.14;
            double padY = h * 0.15;
            double rectW = w - padX * 2;
            double rectH = h - padY * 2;

            if (selRoom != null && selRoom.Segments2D != null && selRoom.Segments2D.Count >= 3)
            {
                // Render actual room boundary polygon scaled to fit Canvas!
                double minX = selRoom.Segments2D.Min(s => Math.Min(s.X1, s.X2));
                double maxX = selRoom.Segments2D.Max(s => Math.Max(s.X1, s.X2));
                double minY = selRoom.Segments2D.Min(s => Math.Min(s.Y1, s.Y2));
                double maxY = selRoom.Segments2D.Max(s => Math.Max(s.Y1, s.Y2));

                double spanX = Math.Max(0.1, maxX - minX);
                double spanY = Math.Max(0.1, maxY - minY);
                double scale = Math.Min(rectW / spanX, rectH / spanY);
                double offsetX = (w - spanX * scale) * 0.5;
                double offsetY = (h - spanY * scale) * 0.5;

                foreach (var seg in selRoom.Segments2D)
                {
                    double x1 = offsetX + (seg.X1 - minX) * scale;
                    double y1 = h - (offsetY + (seg.Y1 - minY) * scale);
                    double x2 = offsetX + (seg.X2 - minX) * scale;
                    double y2 = h - (offsetY + (seg.Y2 - minY) * scale);

                    // Core wall line
                    var coreLine = new System.Windows.Shapes.Line
                    {
                        X1 = x1, Y1 = y1, X2 = x2, Y2 = y2,
                        Stroke = seg.IsColumnFace
                            ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(100, 116, 139))
                            : new SolidColorBrush(System.Windows.Media.Color.FromRgb(148, 163, 184)),
                        StrokeThickness = 6,
                        StrokeStartLineCap = PenLineCap.Square,
                        StrokeEndLineCap = PenLineCap.Square
                    };
                    CanvasPlanPreview.Children.Add(coreLine);

                    if (showFinishWalls && !(seg.IsColumnFace && RbColIgnore?.IsChecked == true))
                    {
                        double dx = x2 - x1;
                        double dy = y2 - y1;
                        double len = Math.Sqrt(dx * dx + dy * dy);
                        if (len > 4)
                        {
                            double nx = -dy / len * 5.0;
                            double ny = dx / len * 5.0;
                            var finLine = new System.Windows.Shapes.Line
                            {
                                X1 = x1 + nx, Y1 = y1 + ny,
                                X2 = x2 + nx, Y2 = y2 + ny,
                                Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(56, 189, 248)),
                                StrokeThickness = 3
                            };
                            CanvasPlanPreview.Children.Add(finLine);
                        }
                    }
                }
            }
            else
            {
                // Clean schematic rectangular preview matching mockup SVG
                var coreRect = new System.Windows.Shapes.Rectangle
                {
                    Width = rectW,
                    Height = rectH,
                    Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(148, 163, 184)),
                    StrokeThickness = 7,
                    Fill = Brushes.Transparent
                };
                Canvas.SetLeft(coreRect, padX);
                Canvas.SetTop(coreRect, padY);
                CanvasPlanPreview.Children.Add(coreRect);

                if (showFinishWalls)
                {
                    var finRect = new System.Windows.Shapes.Rectangle
                    {
                        Width = Math.Max(10, rectW - 14),
                        Height = Math.Max(10, rectH - 14),
                        Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(56, 189, 248)),
                        StrokeThickness = 3.5,
                        Fill = Brushes.Transparent
                    };
                    Canvas.SetLeft(finRect, padX + 7);
                    Canvas.SetTop(finRect, padY + 7);
                    CanvasPlanPreview.Children.Add(finRect);
                }
            }

            // Door break indicator on right edge
            if (breakDoors)
            {
                double doorX = w - padX - 7;
                double doorY1 = h * 0.38;
                double doorY2 = h * 0.58;
                var breakGap = new System.Windows.Shapes.Line
                {
                    X1 = doorX, Y1 = doorY1, X2 = doorX, Y2 = doorY2,
                    Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(248, 250, 252)),
                    StrokeThickness = 8
                };
                CanvasPlanPreview.Children.Add(breakGap);

                TextBlock doorLbl = new TextBlock
                {
                    Text = "Door Break",
                    Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(245, 158, 11)),
                    FontSize = 10,
                    FontWeight = FontWeights.Bold
                };
                Canvas.SetLeft(doorLbl, doorX - 58);
                Canvas.SetTop(doorLbl, (doorY1 + doorY2) * 0.5 - 7);
                CanvasPlanPreview.Children.Add(doorLbl);
            }

            // Center label
            TextBlock centerTxt = new TextBlock
            {
                Text = selRoom != null ? $"{selRoom.DisplayName}\n{selRoom.AreaSqm:0.00} m²" : "Room Area",
                Foreground = new SolidColorBrush(System.Windows.Media.Color.FromRgb(100, 116, 139)),
                FontSize = 11.5,
                FontWeight = FontWeights.SemiBold,
                TextAlignment = TextAlignment.Center
            };
            centerTxt.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
            Canvas.SetLeft(centerTxt, (w - centerTxt.DesiredSize.Width) * 0.5);
            Canvas.SetTop(centerTxt, (h - centerTxt.DesiredSize.Height) * 0.5);
            CanvasPlanPreview.Children.Add(centerTxt);
        }

        private void RenderSectionPreview()
        {
            if (CanvasSectionPreview == null) return;
            CanvasSectionPreview.Children.Clear();

            double w = CanvasSectionPreview.ActualWidth;
            double h = CanvasSectionPreview.ActualHeight;
            if (w < 60 || h < 60) return;

            double.TryParse(TxtCeilingHeight?.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double ceilHmm);
            if (ceilHmm <= 0) ceilHmm = 2700;
            double.TryParse(TxtCeilingVoidOffset?.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double voidMm);
            double.TryParse(TxtFloorOffset?.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double floorOffMm);

            bool createWalls = ChkCreateWalls?.IsChecked == true;
            bool createFloors = ChkCreateFloors?.IsChecked == true;
            bool createCeilings = ChkCreateCeilings?.IsChecked == true;
            bool createSkirting = ChkCreateSkirting?.IsChecked == true;
            bool baseOnSlab = RbWallBaseSlab?.IsChecked == true;
            bool topAtCeiling = RbWallTopCeiling?.IsChecked == true;
            bool skirtInFront = RbSkirtInFront?.IsChecked == true;

            double leftMargin = 28;
            double coreWallW = 34;
            double slabH = 22;
            double topSlabY = 12;
            double botSlabY = h - slabH - 12;
            double coreWallH = botSlabY - (topSlabY + slabH);
            double spanW = w - leftMargin - 20;

            // 1. Slab Above (+3000)
            AddSectionRect(leftMargin, topSlabY, spanW, slabH, Color.FromRgb(203, 213, 225));
            AddSectionText("Slab Above (+3000)", leftMargin + spanW * 0.5, topSlabY + 4, Color.FromRgb(51, 65, 85), true);

            // 2. Structural Wall Core (Left vertical)
            AddSectionRect(leftMargin, topSlabY + slabH, coreWallW, coreWallH, Color.FromRgb(226, 232, 240));

            // 3. Slab Below (0.00)
            AddSectionRect(leftMargin, botSlabY, spanW, slabH, Color.FromRgb(203, 213, 225));
            AddSectionText("Slab Below (0.00)", leftMargin + spanW * 0.5, botSlabY + 4, Color.FromRgb(51, 65, 85), true);

            // Calculate positions for Finish Floor & Ceiling
            double finishFloorH = 13;
            double finishFloorY = botSlabY - finishFloorH;
            double ceilingY = topSlabY + slabH + coreWallH * 0.22;
            double ceilingH = 12;

            // 4. Ceiling Layer (#818CF8)
            if (createCeilings)
            {
                AddSectionRect(leftMargin + coreWallW, ceilingY, spanW - coreWallW, ceilingH, Color.FromRgb(129, 140, 248));
                AddSectionText($"Ceiling (+{ceilHmm:0})", leftMargin + coreWallW + (spanW - coreWallW) * 0.52, ceilingY - 1, Colors.White, true);
            }

            // 5. Finish Floor Layer (#FDE047)
            if (createFloors)
            {
                AddSectionRect(leftMargin + coreWallW, finishFloorY, spanW - coreWallW, finishFloorH, Color.FromRgb(253, 224, 71));
                AddSectionText($"Fin. Floor (+{floorOffMm + 100:0})", leftMargin + coreWallW + (spanW - coreWallW) * 0.52, finishFloorY - 1, Color.FromRgb(15, 23, 42), true);
            }

            // 6. Finish Wall Layer (#38BDF8)
            double wallX = leftMargin + coreWallW;
            double wallW = 12;
            double wallTopY = topAtCeiling ? (ceilingY - 12) : (topSlabY + slabH);
            double wallBotY = (baseOnSlab || !createFloors) ? botSlabY : finishFloorY;
            if (createSkirting && !skirtInFront)
            {
                wallBotY -= 14; // Flush skirting sits below finish wall
            }

            if (createWalls && wallBotY > wallTopY + 10)
            {
                AddSectionRect(wallX, wallTopY, wallW, wallBotY - wallTopY, Color.FromRgb(56, 189, 248));
                AddSectionText("Wall Finish", wallX + wallW + 6, (wallTopY + wallBotY) * 0.5 - 7, Color.FromRgb(51, 65, 85), false);

                if (topAtCeiling)
                {
                    var dashLine = new System.Windows.Shapes.Line
                    {
                        X1 = leftMargin, Y1 = wallTopY, X2 = wallX + wallW, Y2 = wallTopY,
                        Stroke = new SolidColorBrush(Color.FromRgb(100, 116, 139)),
                        StrokeThickness = 1,
                        StrokeDashArray = new DoubleCollection { 2, 2 }
                    };
                    CanvasSectionPreview.Children.Add(dashLine);
                    AddSectionText($"+{voidMm:0} Void", leftMargin + 2, wallTopY - 14, Color.FromRgb(100, 116, 139), false, 9.5);
                }
            }

            // 7. Skirting Layer (#F59E0B)
            if (createSkirting)
            {
                double skW = 8;
                double skH = 14;
                double skX = skirtInFront ? (wallX + (createWalls ? wallW : 0)) : wallX;
                double skY = (createFloors ? finishFloorY : botSlabY) - skH;
                AddSectionRect(skX, skY, skW, skH, Color.FromRgb(245, 158, 11));
            }
        }

        private void AddSectionRect(double x, double y, double w, double h, System.Windows.Media.Color fill)
        {
            var r = new System.Windows.Shapes.Rectangle
            {
                Width = Math.Max(2, w),
                Height = Math.Max(2, h),
                Fill = new SolidColorBrush(fill)
            };
            Canvas.SetLeft(r, x);
            Canvas.SetTop(r, y);
            CanvasSectionPreview.Children.Add(r);
        }

        private void AddSectionText(string text, double x, double y, System.Windows.Media.Color color, bool centerHoriz, double fontSize = 10.5)
        {
            TextBlock tb = new TextBlock
            {
                Text = text,
                Foreground = new SolidColorBrush(color),
                FontFamily = new FontFamily("Consolas"),
                FontSize = fontSize,
                FontWeight = FontWeights.Bold
            };
            tb.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
            Canvas.SetLeft(tb, centerHoriz ? (x - tb.DesiredSize.Width * 0.5) : x);
            Canvas.SetTop(tb, y);
            CanvasSectionPreview.Children.Add(tb);
        }
    }
}

using System;
using System.Diagnostics;
using System.Windows.Interop;
using Autodesk.Revit.Attributes;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using ORTools.UI;

namespace ORTools.Commands
{
    [Transaction(TransactionMode.Manual)]
    [Regeneration(RegenerationOption.Manual)]
    public class GoatArchCommand : IExternalCommand
    {
        private static GoatArchWindow _activeWindow;

        public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
        {
            try
            {
                if (_activeWindow != null && _activeWindow.IsLoaded)
                {
                    _activeWindow.Activate();
                    return Result.Succeeded;
                }

                var handler = new GoatArchExternalEventHandler();
                ExternalEvent extEvent = ExternalEvent.Create(handler);

                _activeWindow = new GoatArchWindow(handler, extEvent);
                IntPtr revitHandle = Process.GetCurrentProcess().MainWindowHandle;
                if (revitHandle != IntPtr.Zero)
                {
                    new WindowInteropHelper(_activeWindow).Owner = revitHandle;
                }

                _activeWindow.Closed += (s, e) => { _activeWindow = null; };
                _activeWindow.Show();

                return Result.Succeeded;
            }
            catch (Exception ex)
            {
                message = ex.Message;
                return Result.Failed;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using Autodesk.Revit.UI.Selection;
using ORTools.UI;

namespace ORTools.Commands
{
    public enum GoatArchAction
    {
        None,
        CreateArchInWall,
        CreateParametricWardrobe
    }

    public class GoatArchExternalEventHandler : IExternalEventHandler
    {
        public GoatArchWindow Window { get; set; }
        public GoatArchAction CurrentAction { get; set; } = GoatArchAction.None;

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc == null || uidoc.Document == null) return;
            Document doc = uidoc.Document;

            try
            {
                switch (CurrentAction)
                {
                    case GoatArchAction.CreateArchInWall:
                        ExecuteCreateArch(uidoc, doc);
                        break;

                    case GoatArchAction.CreateParametricWardrobe:
                        ExecuteCreateWardrobe(uidoc, doc);
                        break;
                }
            }
            catch (Autodesk.Revit.Exceptions.OperationCanceledException)
            {
                Window.UpdateStatus("Placement cancelled by user.", false);
            }
            catch (Exception ex)
            {
                Window.UpdateStatus($"Error: {ex.Message}", true);
            }
            finally
            {
                CurrentAction = GoatArchAction.None;
            }
        }

        public string GetName() => "GOAT ARCH & JOINERY External Event Handler";

        private void ExecuteCreateArch(UIDocument uidoc, Document doc)
        {
            var cfg = Window.CollectArchParameters();
            Wall targetWall = null;
            XYZ centerPt = XYZ.Zero;
            XYZ wallDir = XYZ.BasisX;
            XYZ wallNormal = XYZ.BasisY;
            double wallThicknessFeet = UnitUtils.ConvertToInternalUnits(cfg.DepthMm, UnitTypeId.Millimeters);

            // Check if a wall is already selected, otherwise prompt user to pick a wall or point
            var selIds = uidoc.Selection.GetElementIds();
            foreach (ElementId id in selIds)
            {
                if (doc.GetElement(id) is Wall w)
                {
                    targetWall = w;
                    break;
                }
            }

            if (targetWall == null)
            {
                Window.UpdateStatus("Select a host wall or pick a point in the active view...", false);
                try
                {
                    Reference pickedRef = uidoc.Selection.PickObject(ObjectType.Element, "Select Host Wall for GOAT ARCH (or ESC to place at origin)");
                    targetWall = doc.GetElement(pickedRef.ElementId) as Wall;
                    centerPt = pickedRef.GlobalPoint ?? XYZ.Zero;
                }
                catch
                {
                    // Fallback: pick point
                    centerPt = uidoc.Selection.PickPoint("Pick insertion point for GOAT ARCH");
                }
            }

            if (targetWall != null && targetWall.Location is LocationCurve lc && lc.Curve is Line wallLine)
            {
                wallDir = (wallLine.GetEndPoint(1) - wallLine.GetEndPoint(0)).Normalize();
                wallNormal = new XYZ(-wallDir.Y, wallDir.X, 0).Normalize();
                wallThicknessFeet = targetWall.Width;

                if (centerPt.IsAlmostEqualTo(XYZ.Zero))
                {
                    centerPt = (wallLine.GetEndPoint(0) + wallLine.GetEndPoint(1)) * 0.5;
                }
                else
                {
                    // Project picked point onto wall centerline at base elevation
                    XYZ start = wallLine.GetEndPoint(0);
                    double proj = (centerPt - start).DotProduct(wallDir);
                    centerPt = new XYZ(start.X + wallDir.X * proj, start.Y + wallDir.Y * proj, start.Z);
                }
            }

            double spanFeet = UnitUtils.ConvertToInternalUnits(cfg.SpanMm, UnitTypeId.Millimeters);
            double springHeightFeet = UnitUtils.ConvertToInternalUnits(cfg.SpringingHeightMm, UnitTypeId.Millimeters);
            double riseFeet = UnitUtils.ConvertToInternalUnits(cfg.RiseMm, UnitTypeId.Millimeters);
            double ringThkFeet = UnitUtils.ConvertToInternalUnits(cfg.RingThicknessMm, UnitTypeId.Millimeters);

            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ARCH — Generate Architectural Arch"))
            {
                tg.Start();
                using (Transaction trans = new Transaction(doc, "Create Arch Solid & Cut Opening"))
                {
                    trans.Start();

                    // 1. Cut opening in host wall if requested
                    if (cfg.CutHostWall && targetWall != null)
                    {
                        try
                        {
                            XYZ p1 = centerPt - wallDir * (spanFeet * 0.5);
                            XYZ p2 = centerPt + wallDir * (spanFeet * 0.5) + XYZ.BasisZ * (springHeightFeet + riseFeet);
                            doc.Create.NewOpening(targetWall, p1, p2);
                        }
                        catch { }
                    }

                    // 2. Build 3D Extrusion for the Arch Ring + Spandrel infill
                    List<XYZ> innerPts2D = GoatArchWindow.SampleArchCurvePoints(cfg.ArchTypeIndex, spanFeet, springHeightFeet, riseFeet, 24);
                    List<XYZ> outerPts2D = GoatArchWindow.SampleArchCurvePoints(cfg.ArchTypeIndex, spanFeet + ringThkFeet * 2.0, springHeightFeet, riseFeet + ringThkFeet, 24);

                    var loopPts = new List<XYZ>();
                    foreach (var p in innerPts2D)
                    {
                        loopPts.Add(centerPt - wallNormal * (wallThicknessFeet * 0.5) + wallDir * p.X + XYZ.BasisZ * p.Y);
                    }
                    for (int i = outerPts2D.Count - 1; i >= 0; i--)
                    {
                        var p = outerPts2D[i];
                        loopPts.Add(centerPt - wallNormal * (wallThicknessFeet * 0.5) + wallDir * p.X + XYZ.BasisZ * p.Y);
                    }

                    CurveLoop archLoop = new CurveLoop();
                    for (int i = 0; i < loopPts.Count; i++)
                    {
                        XYZ a = loopPts[i];
                        XYZ b = loopPts[(i + 1) % loopPts.Count];
                        if (a.DistanceTo(b) > 0.005)
                        {
                            archLoop.Append(Line.CreateBound(a, b));
                        }
                    }

                    Solid archSolid = GeometryCreationUtilities.CreateExtrusionGeometry(
                        new List<CurveLoop> { archLoop },
                        wallNormal,
                        wallThicknessFeet);

                    DirectShape ds = DirectShape.CreateElement(doc, new ElementId(BuiltInCategory.OST_GenericModel));
                    ds.ApplicationId = "GOATBIM_ArchGenerator";
                    ds.ApplicationDataId = Guid.NewGuid().ToString();
                    ds.SetShape(new List<GeometryObject> { archSolid });
                    ds.Name = $"GOAT Arch ({cfg.ArchTypeName} {cfg.SpanMm:0}x{cfg.SpringingHeightMm + cfg.RiseMm:0})";

                    Parameter cmt = ds.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
                    if (cmt != null && !cmt.IsReadOnly)
                    {
                        cmt.Set($"GOAT_ARCH | {cfg.ArchTypeName} | Span={cfg.SpanMm:0}mm");
                    }

                    trans.Commit();
                }
                tg.Assimilate();
            }

            Window.UpdateStatus($"✔ Created {cfg.ArchTypeName} Arch ({cfg.SpanMm:0}mm span). (1x Ctrl+Z to Undo)", false);
        }

        private void ExecuteCreateWardrobe(UIDocument uidoc, Document doc)
        {
            var cfg = Window.CollectWardrobeParameters();

            XYZ basePt = XYZ.Zero;
            try
            {
                basePt = uidoc.Selection.PickPoint("Pick insertion point (bottom-left front corner) for GOAT Wardrobe / Joinery");
            }
            catch
            {
                basePt = XYZ.Zero;
            }

            double wFeet = UnitUtils.ConvertToInternalUnits(cfg.WidthMm, UnitTypeId.Millimeters);
            double hFeet = UnitUtils.ConvertToInternalUnits(cfg.HeightMm, UnitTypeId.Millimeters);
            double dFeet = UnitUtils.ConvertToInternalUnits(cfg.DepthMm, UnitTypeId.Millimeters);
            double plinthFeet = UnitUtils.ConvertToInternalUnits(cfg.PlinthMm, UnitTypeId.Millimeters);
            double panelFeet = UnitUtils.ConvertToInternalUnits(cfg.PanelThicknessMm, UnitTypeId.Millimeters);

            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ARCH — Generate Parametric Wardrobe"))
            {
                tg.Start();
                using (Transaction trans = new Transaction(doc, "Create Parametric Wardrobe Joinery"))
                {
                    trans.Start();

                    var solids = new List<GeometryObject>();

                    // Helper to create a box solid from local min (x0, y0, z0) to max (x1, y1, z1)
                    void AddBox(double x0, double y0, double z0, double x1, double y1, double z1)
                    {
                        if (x1 - x0 <= 0.005 || y1 - y0 <= 0.005 || z1 - z0 <= 0.005) return;
                        XYZ p0 = basePt + new XYZ(x0, y0, z0);
                        XYZ p1 = basePt + new XYZ(x1, y0, z0);
                        XYZ p2 = basePt + new XYZ(x1, y1, z0);
                        XYZ p3 = basePt + new XYZ(x0, y1, z0);

                        CurveLoop loop = new CurveLoop();
                        loop.Append(Line.CreateBound(p0, p1));
                        loop.Append(Line.CreateBound(p1, p2));
                        loop.Append(Line.CreateBound(p2, p3));
                        loop.Append(Line.CreateBound(p3, p0));

                        Solid box = GeometryCreationUtilities.CreateExtrusionGeometry(new List<CurveLoop> { loop }, XYZ.BasisZ, z1 - z0);
                        if (box != null) solids.Add(box);
                    }

                    // 1. Plinth Base
                    if (plinthFeet > 0.01)
                    {
                        AddBox(0, 0.08, 0, wFeet, dFeet, plinthFeet);
                    }

                    // 2. Bottom, Top, Left, Right, Back panels
                    AddBox(0, 0, plinthFeet, wFeet, dFeet, plinthFeet + panelFeet); // Bottom
                    AddBox(0, 0, hFeet - panelFeet, wFeet, dFeet, hFeet);           // Top
                    AddBox(0, 0, plinthFeet + panelFeet, panelFeet, dFeet, hFeet - panelFeet); // Left
                    AddBox(wFeet - panelFeet, 0, plinthFeet + panelFeet, wFeet, dFeet, hFeet - panelFeet); // Right
                    AddBox(panelFeet, dFeet - panelFeet, plinthFeet + panelFeet, wFeet - panelFeet, dFeet, hFeet - panelFeet); // Back

                    // 3. Vertical Bay Dividers & Shelves
                    int bays = Math.Max(1, cfg.BayCount);
                    double innerW = wFeet - 2 * panelFeet;
                    double bayW = innerW / bays;
                    double innerStartZ = plinthFeet + panelFeet;
                    double innerEndZ = hFeet - panelFeet;
                    double innerH = innerEndZ - innerStartZ;

                    for (int b = 1; b < bays; b++)
                    {
                        double divX = panelFeet + b * bayW - panelFeet * 0.5;
                        AddBox(divX, 0, innerStartZ, divX + panelFeet, dFeet - panelFeet, innerEndZ);
                    }

                    // 4. Shelves per Bay
                    int shelves = Math.Max(0, cfg.ShelvesPerBay);
                    for (int s = 1; s <= shelves; s++)
                    {
                        double shelfZ = innerStartZ + (innerH / (shelves + 1)) * s;
                        AddBox(panelFeet, 0.05, shelfZ, wFeet - panelFeet, dFeet - panelFeet, shelfZ + panelFeet);
                    }

                    // 5. Optional Doors (Closed / Semi-open front panels)
                    if (cfg.DoorStyleIndex == 0 || cfg.DoorStyleIndex == 1)
                    {
                        int doorPanels = Math.Max(2, bays * 2);
                        double doorW = wFeet / doorPanels;
                        double gap = UnitUtils.ConvertToInternalUnits(3.0, UnitTypeId.Millimeters);
                        for (int d = 0; d < doorPanels; d++)
                        {
                            double dx0 = d * doorW + gap;
                            double dx1 = (d + 1) * doorW - gap;
                            AddBox(dx0, -panelFeet, plinthFeet, dx1, 0, hFeet);
                        }
                    }

                    DirectShape ds = DirectShape.CreateElement(doc, new ElementId(BuiltInCategory.OST_Casework));
                    ds.ApplicationId = "GOATBIM_WardrobeBuilder";
                    ds.ApplicationDataId = Guid.NewGuid().ToString();
                    ds.SetShape(solids);
                    ds.Name = $"GOAT Wardrobe ({cfg.WidthMm:0}x{cfg.HeightMm:0}x{cfg.DepthMm:0}mm - {bays} Bays)";

                    Parameter cmt = ds.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
                    if (cmt != null && !cmt.IsReadOnly)
                    {
                        cmt.Set($"GOAT_JOINERY | {cfg.WidthMm:0}x{cfg.HeightMm:0}x{cfg.DepthMm:0}mm | {bays} Bays");
                    }

                    trans.Commit();
                }
                tg.Assimilate();
            }

            Window.UpdateStatus($"✔ Created Parametric Wardrobe ({cfg.WidthMm:0}×{cfg.HeightMm:0}×{cfg.DepthMm:0}mm, {cfg.BayCount} Bays). (1x Ctrl+Z to Undo)", false);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using ORTools.Commands;

namespace ORTools.UI
{
    public class ArchConfigData
    {
        public int ArchTypeIndex { get; set; }
        public string ArchTypeName { get; set; } = "Semicircular";
        public double SpanMm { get; set; } = 1800;
        public double SpringingHeightMm { get; set; } = 1500;
        public double RiseMm { get; set; } = 900;
        public double DepthMm { get; set; } = 250;
        public double RingThicknessMm { get; set; } = 150;
        public bool CutHostWall { get; set; } = true;
    }

    public class WardrobeConfigData
    {
        public double WidthMm { get; set; } = 2400;
        public double HeightMm { get; set; } = 2400;
        public double DepthMm { get; set; } = 600;
        public double PlinthMm { get; set; } = 80;
        public double PanelThicknessMm { get; set; } = 18;
        public int BayCount { get; set; } = 3;
        public int ShelvesPerBay { get; set; } = 4;
        public int DoorStyleIndex { get; set; } = 2;
    }

    public partial class GoatArchWindow : Window
    {
        private readonly GoatArchExternalEventHandler _handler;
        private readonly ExternalEvent _extEvent;
        private int _activeTabIndex = 0;
        private bool _isLoaded = false;

        public GoatArchWindow(GoatArchExternalEventHandler handler, ExternalEvent extEvent)
        {
            InitializeComponent();
            _handler = handler;
            _extEvent = extEvent;
            _handler.Window = this;

            Loaded += (s, e) =>
            {
                _isLoaded = true;
                RenderPreview();
            };
        }

        public ArchConfigData CollectArchParameters()
        {
            double.TryParse(TxtArchSpan.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double span);
            double.TryParse(TxtArchSpringing.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double spring);
            double.TryParse(TxtArchRise.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double rise);
            double.TryParse(TxtArchDepth.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double depth);
            double.TryParse(TxtArchRing.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double ring);

            int idx = CbArchType.SelectedIndex >= 0 ? CbArchType.SelectedIndex : 0;
            string name = (CbArchType.SelectedItem as ComboBoxItem)?.Content?.ToString() ?? "Semicircular";

            return new ArchConfigData
            {
                ArchTypeIndex = idx,
                ArchTypeName = name.Split('(')[0].Trim(),
                SpanMm = Math.Max(400, span),
                SpringingHeightMm = Math.Max(200, spring),
                RiseMm = Math.Max(150, rise),
                DepthMm = Math.Max(50, depth),
                RingThicknessMm = Math.Max(40, ring),
                CutHostWall = ChkArchCutWall.IsChecked == true
            };
        }

        public WardrobeConfigData CollectWardrobeParameters()
        {
            double.TryParse(TxtWardWidth.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double w);
            double.TryParse(TxtWardHeight.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double h);
            double.TryParse(TxtWardDepth.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double d);
            double.TryParse(TxtWardPlinth.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double p);
            double.TryParse(TxtWardPanelThk.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double thk);
            int.TryParse(TxtWardBays.Text, out int bays);
            int.TryParse(TxtWardShelves.Text, out int shelves);

            return new WardrobeConfigData
            {
                WidthMm = Math.Max(400, w),
                HeightMm = Math.Max(600, h),
                DepthMm = Math.Max(250, d),
                PlinthMm = Math.Max(0, p),
                PanelThicknessMm = Math.Clamp(thk, 10, 50),
                BayCount = Math.Clamp(bays, 1, 12),
                ShelvesPerBay = Math.Clamp(shelves, 0, 15),
                DoorStyleIndex = CbWardDoorStyle.SelectedIndex >= 0 ? CbWardDoorStyle.SelectedIndex : 2
            };
        }

        public void UpdateStatus(string text, bool isError)
        {
            TxtStatus.Text = text;
            TxtStatus.Foreground = isError
                ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(220, 38, 38))
                : new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42));
        }

        private void TabBtn_Click(object sender, RoutedEventArgs e)
        {
            if (!(sender is Button btn)) return;
            _activeTabIndex = btn.Tag?.ToString() == "1" ? 1 : 0;

            bool isArch = _activeTabIndex == 0;
            BtnTabArch.Background = isArch ? Brushes.White : new SolidColorBrush(System.Windows.Media.Color.FromRgb(241, 245, 249));
            BtnTabArch.Foreground = isArch ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)) : new SolidColorBrush(System.Windows.Media.Color.FromRgb(100, 116, 139));
            BtnTabArch.BorderBrush = isArch ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)) : Brushes.Transparent;

            BtnTabWardrobe.Background = !isArch ? Brushes.White : new SolidColorBrush(System.Windows.Media.Color.FromRgb(241, 245, 249));
            BtnTabWardrobe.Foreground = !isArch ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)) : new SolidColorBrush(System.Windows.Media.Color.FromRgb(100, 116, 139));
            BtnTabWardrobe.BorderBrush = !isArch ? new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)) : Brushes.Transparent;

            PanelArch.Visibility = isArch ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;
            PanelWardrobe.Visibility = !isArch ? System.Windows.Visibility.Visible : System.Windows.Visibility.Collapsed;

            TxtPreviewTitle.Text = isArch
                ? "ELEVATION PREVIEW: Parametric Arch Geometry"
                : "ELEVATION PREVIEW: Parametric Wardrobe & Joinery";
            BtnGeneratePrimary.Content = isArch
                ? "🚀 Create Arch in Model"
                : "🚀 Create Wardrobe in Model";

            RenderPreview();
        }

        private void ArchInput_Changed(object sender, SelectionChangedEventArgs e)
        {
            if (!_isLoaded) return;
            if (CbArchType.SelectedIndex == 0 && double.TryParse(TxtArchSpan.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double sp))
            {
                TxtArchRise.Text = (sp * 0.5).ToString("0", CultureInfo.InvariantCulture);
            }
            RenderPreview();
        }

        private void ArchText_Changed(object sender, TextChangedEventArgs e)
        {
            if (!_isLoaded) return;
            RenderPreview();
        }

        private void WardrobeText_Changed(object sender, TextChangedEventArgs e)
        {
            if (!_isLoaded) return;
            RenderPreview();
        }

        private void CanvasArchPreview_SizeChanged(object sender, SizeChangedEventArgs e)
        {
            if (!_isLoaded) return;
            RenderPreview();
        }

        private void BtnGeneratePrimary_Click(object sender, RoutedEventArgs e)
        {
            _handler.CurrentAction = _activeTabIndex == 0
                ? GoatArchAction.CreateArchInWall
                : GoatArchAction.CreateParametricWardrobe;
            _extEvent.Raise();
        }

        private void BtnClose_Click(object sender, RoutedEventArgs e)
        {
            Close();
        }

        private void RenderPreview()
        {
            if (CanvasArchPreview == null) return;
            CanvasArchPreview.Children.Clear();

            double cw = CanvasArchPreview.ActualWidth;
            double ch = CanvasArchPreview.ActualHeight;
            if (cw < 50 || ch < 50) return;

            if (_activeTabIndex == 0)
            {
                var cfg = CollectArchParameters();
                double totalW = cfg.SpanMm + cfg.RingThicknessMm * 2.0;
                double totalH = cfg.SpringingHeightMm + cfg.RiseMm + cfg.RingThicknessMm;

                double scale = Math.Min((cw - 60) / totalW, (ch - 60) / totalH);
                double centerX = cw * 0.5;
                double baseY = ch - 30;

                var innerPts = SampleArchCurvePoints(cfg.ArchTypeIndex, cfg.SpanMm, cfg.SpringingHeightMm, cfg.RiseMm, 32);
                var outerPts = SampleArchCurvePoints(cfg.ArchTypeIndex, cfg.SpanMm + cfg.RingThicknessMm * 2.0, cfg.SpringingHeightMm, cfg.RiseMm + cfg.RingThicknessMm, 32);

                Polygon poly = new Polygon
                {
                    Fill = new SolidColorBrush(System.Windows.Media.Color.FromArgb(190, 56, 189, 248)),
                    Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)),
                    StrokeThickness = 2
                };

                foreach (var p in innerPts)
                {
                    poly.Points.Add(new System.Windows.Point(centerX + p.X * scale, baseY - p.Y * scale));
                }
                for (int i = outerPts.Count - 1; i >= 0; i--)
                {
                    var p = outerPts[i];
                    poly.Points.Add(new System.Windows.Point(centerX + p.X * scale, baseY - p.Y * scale));
                }

                CanvasArchPreview.Children.Add(poly);

                // Floor datum line
                var floorLine = new System.Windows.Shapes.Line
                {
                    X1 = 20, Y1 = baseY, X2 = cw - 20, Y2 = baseY,
                    Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(100, 116, 139)),
                    StrokeThickness = 1.5
                };
                CanvasArchPreview.Children.Add(floorLine);
            }
            else
            {
                var cfg = CollectWardrobeParameters();
                double scale = Math.Min((cw - 60) / cfg.WidthMm, (ch - 60) / cfg.HeightMm);
                double drawW = cfg.WidthMm * scale;
                double drawH = cfg.HeightMm * scale;
                double startX = (cw - drawW) * 0.5;
                double startY = (ch - drawH) * 0.5;
                double plinthH = cfg.PlinthMm * scale;

                // Outer frame
                var frame = new System.Windows.Shapes.Rectangle
                {
                    Width = drawW,
                    Height = drawH,
                    Fill = new SolidColorBrush(System.Windows.Media.Color.FromRgb(241, 245, 249)),
                    Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)),
                    StrokeThickness = 2.5
                };
                Canvas.SetLeft(frame, startX);
                Canvas.SetTop(frame, startY);
                CanvasArchPreview.Children.Add(frame);

                // Plinth
                var plinth = new System.Windows.Shapes.Rectangle
                {
                    Width = drawW,
                    Height = Math.Max(4, plinthH),
                    Fill = new SolidColorBrush(System.Windows.Media.Color.FromRgb(203, 213, 225)),
                    Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)),
                    StrokeThickness = 1.5
                };
                Canvas.SetLeft(plinth, startX);
                Canvas.SetTop(plinth, startY + drawH - plinthH);
                CanvasArchPreview.Children.Add(plinth);

                // Bays & Shelves
                double bodyH = drawH - plinthH;
                double bayW = drawW / cfg.BayCount;
                for (int b = 1; b < cfg.BayCount; b++)
                {
                    double bx = startX + b * bayW;
                    CanvasArchPreview.Children.Add(new System.Windows.Shapes.Line
                    {
                        X1 = bx, Y1 = startY, X2 = bx, Y2 = startY + bodyH,
                        Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(15, 23, 42)),
                        StrokeThickness = 2
                    });
                }

                for (int s = 1; s <= cfg.ShelvesPerBay; s++)
                {
                    double sy = startY + (bodyH / (cfg.ShelvesPerBay + 1)) * s;
                    CanvasArchPreview.Children.Add(new System.Windows.Shapes.Line
                    {
                        X1 = startX, Y1 = sy, X2 = startX + drawW, Y2 = sy,
                        Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(56, 189, 248)),
                        StrokeThickness = 2
                    });
                }
            }
        }

        public static List<XYZ> SampleArchCurvePoints(int archTypeIndex, double span, double springH, double rise, int segments)
        {
            var pts = new List<XYZ>();
            double halfSpan = span * 0.5;

            // Left jamb bottom -> springing
            pts.Add(new XYZ(-halfSpan, 0, 0));
            pts.Add(new XYZ(-halfSpan, springH, 0));

            for (int i = 1; i < segments; i++)
            {
                double t = (double)i / segments; // 0..1 from left (-halfSpan) to right (+halfSpan)
                double angle = Math.PI * (1.0 - t); // pi..0
                double x = -halfSpan + span * t;
                double y = springH;

                switch (archTypeIndex)
                {
                    case 0: // Semicircular
                    case 1: // Segmental
                    case 4: // Three-centered (elliptical approximation)
                        x = halfSpan * Math.Cos(angle);
                        y = springH + rise * Math.Sin(angle);
                        break;

                    case 2: // Pointed / Gothic
                    {
                        double normX = Math.Abs(2.0 * t - 1.0); // 1 at edges, 0 at apex
                        y = springH + rise * Math.Sqrt(Math.Max(0, 1.0 - normX * normX * 0.85)) * (1.0 - 0.15 * normX);
                        break;
                    }

                    case 3: // Horseshoe / Moorish
                    {
                        double extAngle = -0.22 * Math.PI + (1.44 * Math.PI) * (1.0 - t);
                        x = halfSpan * 1.06 * Math.Cos(extAngle);
                        y = springH + rise * 0.35 + rise * 0.65 * Math.Sin(extAngle);
                        break;
                    }

                    case 5: // Four-centered / Tudor
                    {
                        double normX = Math.Abs(2.0 * t - 1.0);
                        y = springH + rise * (1.0 - Math.Pow(normX, 1.65));
                        break;
                    }

                    case 6: // Ogee (S-curve reverse inflection)
                    {
                        double normX = Math.Abs(2.0 * t - 1.0); // 0 at apex, 1 at springing
                        double sCurve = 0.5 * (1.0 + Math.Cos(Math.PI * normX));
                        y = springH + rise * sCurve;
                        break;
                    }
                }

                pts.Add(new XYZ(x, y, 0));
            }

            // Right springing -> bottom
            pts.Add(new XYZ(halfSpan, springH, 0));
            pts.Add(new XYZ(halfSpan, 0, 0));

            return pts;
        }
    }
}

