        private void RenderRcpPreview()
        {
            if (CanvasRcpPreview == null) return;
            CanvasRcpPreview.Children.Clear();

            double w = CanvasRcpPreview.ActualWidth;
            double h = CanvasRcpPreview.ActualHeight;
            if (w < 50 || h < 50) return;

            var cfg = CollectSettings();
            double pad = 22;
            double roomW = w - pad * 2;
            double roomH = h - pad * 2;

            // Room Wall Core
            var wallRect = new Rectangle
            {
                Width = roomW,
                Height = roomH,
                Stroke = new SolidColorBrush(Color.FromRgb(15, 23, 42)),
                StrokeThickness = 4,
                Fill = Brushes.White
            };
            Canvas.SetLeft(wallRect, pad);
            Canvas.SetTop(wallRect, pad);
            CanvasRcpPreview.Children.Add(wallRect);

            // Clearance Margin Dashed Box
            double marginRatio = Math.Clamp(cfg.WallClearanceMarginMm / 6000.0, 0.05, 0.22);
            double mx = roomW * marginRatio;
            double my = roomH * marginRatio;
            var marginRect = new Rectangle
            {
                Width = Math.Max(10, roomW - mx * 2),
                Height = Math.Max(10, roomH - my * 2),
                Stroke = new SolidColorBrush(Color.FromRgb(203, 213, 225)),
                StrokeThickness = 1,
                StrokeDashArray = new DoubleCollection { 3, 3 }
            };
            Canvas.SetLeft(marginRect, pad + mx);
            Canvas.SetTop(marginRect, pad + my);
            CanvasRcpPreview.Children.Add(marginRect);

            // 600x600 Grid Lines
            int cols = 8;
            int rows = 8;
            double innerW = roomW - mx * 2;
            double innerH = roomH - my * 2;
            double stepPxX = innerW / cols;
            double stepPxY = innerH / rows;

            for (int ix = 0; ix <= cols; ix++)
            {
                double x = pad + mx + ix * stepPxX;
                CanvasRcpPreview.Children.Add(new Line
                {
                    X1 = x, Y1 = pad, X2 = x, Y2 = pad + roomH,
                    Stroke = new SolidColorBrush(Color.FromRgb(226, 232, 240)),
                    StrokeThickness = 1
                });
            }
            for (int iy = 0; iy <= rows; iy++)
            {
                double y = pad + my + iy * stepPxY;
                CanvasRcpPreview.Children.Add(new Line
                {
                    X1 = pad, Y1 = y, X2 = pad + roomW, Y2 = y,
                    Stroke = new SolidColorBrush(Color.FromRgb(226, 232, 240)),
                    StrokeThickness = 1
                });
            }

            // Place Fixtures on Grid Nodes
            for (int ix = 0; ix < cols; ix++)
            {
                for (int iy = 0; iy < rows; iy++)
                {
                    double cx = pad + mx + (ix + 0.5) * stepPxX;
                    double cy = pad + my + (iy + 0.5) * stepPxY;

                    if (cfg.PlaceLighting && (ix % cfg.LightingStepX == 0) && (iy % cfg.LightingStepY == 0))
                    {
                        var el = new Ellipse { Width = 10, Height = 10, Fill = new SolidColorBrush(Color.FromRgb(245, 158, 11)) };
                        Canvas.SetLeft(el, cx - 5);
                        Canvas.SetTop(el, cy - 5);
                        CanvasRcpPreview.Children.Add(el);
                    }
                    else if (cfg.PlaceDiffusers && ((ix + 1) % cfg.DiffuserStepX == 0) && ((iy + 1) % cfg.DiffuserStepY == 0))
                    {
                        var el = new Ellipse { Width = 10, Height = 10, Fill = new SolidColorBrush(Color.FromRgb(2, 132, 199)) };
                        Canvas.SetLeft(el, cx - 5);
                        Canvas.SetTop(el, cy - 5);
                        CanvasRcpPreview.Children.Add(el);
                    }
                    else if (cfg.PlaceSprinklers && ((ix + 2) % cfg.SprinklerStepX == 0) && ((iy + 2) % cfg.SprinklerStepY == 0))
                    {
                        var el = new Ellipse { Width = 8, Height = 8, Fill = new SolidColorBrush(Color.FromRgb(16, 185, 129)) };
                        Canvas.SetLeft(el, cx - 4);
                        Canvas.SetTop(el, cy - 4);
                        CanvasRcpPreview.Children.Add(el);
                    }
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Architecture;

namespace ORTools.Models
{
    /// <summary>
    /// Shared backend engines for GOAT DIM, GOAT ANNOTATE, GOAT ROOM (Glyph Bundle), and GOAT ALIGNER.
    /// Allows standalone tools and one-click room bundles to share identical high-precision logic.
    /// </summary>
    public static class GoatDocEngines
    {
        // =========================================================================
        // 1. GOAT DIM ENGINE (Interior Rooms, Exterior Building & Elevations)
        // =========================================================================

        public static int DimensionRoomInPlan(
            Document doc,
            View view,
            Room room,
            DimensionType dimType,
            bool dimClearCross,
            bool dimOpeningsChain,
            double stackOffsetMm)
        {
            if (doc == null || view == null || room == null || room.Area <= 0.001)
                return 0;

            var boundaryOpts = new SpatialElementBoundaryOptions
            {
                SpatialElementBoundaryLocation = SpatialElementBoundaryLocation.Finish
            };

            IList<IList<BoundarySegment>> loops = room.GetBoundarySegments(boundaryOpts);
            if (loops == null || loops.Count == 0 || loops[0].Count < 3)
                return 0;

            BoundingBoxXYZ bb = room.get_BoundingBox(null);
            if (bb == null) return 0;
            XYZ center = (bb.Min + bb.Max) * 0.5;
            double z = view.GenLevel != null ? view.GenLevel.Elevation : bb.Min.Z;
            center = new XYZ(center.X, center.Y, z);

            var vertWallRefs = new ReferenceArray(); // Walls running North-South (measured along X)
            var horizWallRefs = new ReferenceArray(); // Walls running East-West (measured along Y)
            var vertWithOpeningsRefs = new ReferenceArray();
            var horizWithOpeningsRefs = new ReferenceArray();

            var seenHostIds = new HashSet<long>();

            foreach (BoundarySegment seg in loops[0])
            {
                if (seg.ElementId == ElementId.InvalidElementId || seenHostIds.Contains(seg.ElementId.Value))
                    continue;

                if (!(doc.GetElement(seg.ElementId) is Wall wall))
                    continue;

                Curve c = seg.GetCurve();
                if (c == null) continue;
                XYZ dir = (c.GetEndPoint(1) - c.GetEndPoint(0)).Normalize();

                Reference extFaceRef = GetWallFaceReference(wall, true) ?? GetWallFaceReference(wall, false);
                if (extFaceRef == null) continue;

                seenHostIds.Add(wall.Id.Value);

                // Vertical wall (runs along Y, so its normal is along X -> measured by horizontal X dimension line)
                if (Math.Abs(dir.Y) >= Math.Abs(dir.X))
                {
                    vertWallRefs.Append(extFaceRef);
                    vertWithOpeningsRefs.Append(extFaceRef);
                }
                else
                {
                    horizWallRefs.Append(extFaceRef);
                    horizWithOpeningsRefs.Append(extFaceRef);
                }
            }

            int createdDims = 0;
            double offsetFeet = UnitUtils.ConvertToInternalUnits(Math.Max(150, stackOffsetMm), UnitTypeId.Millimeters);

            if (dimClearCross)
            {
                if (vertWallRefs.Size >= 2)
                {
                    try
                    {
                        Line xLine = Line.CreateBound(center - XYZ.BasisX * 50.0, center + XYZ.BasisX * 50.0);
                        Dimension d = doc.Create.NewDimension(view, xLine, vertWallRefs, dimType);
                        if (d != null) createdDims++;
                    }
                    catch { }
                }

                if (horizWallRefs.Size >= 2)
                {
                    try
                    {
                        Line yLine = Line.CreateBound(center - XYZ.BasisY * 50.0, center + XYZ.BasisY * 50.0);
                        Dimension d = doc.Create.NewDimension(view, yLine, horizWallRefs, dimType);
                        if (d != null) createdDims++;
                    }
                    catch { }
                }
            }

            if (dimOpeningsChain)
            {
                // Append door & window center/side references hosted on room bounding walls
                var inserts = new FilteredElementCollector(doc, view.Id)
                    .WhereElementIsNotElementType()
                    .OfType<FamilyInstance>()
                    .Where(fi => fi.Host != null && seenHostIds.Contains(fi.Host.Id.Value))
                    .ToList();

                foreach (FamilyInstance fi in inserts)
                {
                    if (!(fi.Host is Wall hostWall) || !(hostWall.Location is LocationCurve lc) || lc.Curve == null)
                        continue;

                    XYZ wDir = (lc.Curve.GetEndPoint(1) - lc.Curve.GetEndPoint(0)).Normalize();
                    IList<Reference> leftRight = fi.GetReferences(FamilyInstanceReferenceType.Left);
                    IList<Reference> rightRefs = fi.GetReferences(FamilyInstanceReferenceType.Right);
                    IList<Reference> centerRefs = fi.GetReferences(FamilyInstanceReferenceType.CenterLeftRight);

                    var refsToAdd = new List<Reference>();
                    if (leftRight != null && leftRight.Count > 0 && rightRefs != null && rightRefs.Count > 0)
                    {
                        refsToAdd.Add(leftRight[0]);
                        refsToAdd.Add(rightRefs[0]);
                    }
                    else if (centerRefs != null && centerRefs.Count > 0)
                    {
                        refsToAdd.Add(centerRefs[0]);
                    }

                    foreach (var r in refsToAdd)
                    {
                        if (Math.Abs(wDir.Y) >= Math.Abs(wDir.X))
                            horizWithOpeningsRefs.Append(r);
                        else
                            vertWithOpeningsRefs.Append(r);
                    }
                }

                if (vertWithOpeningsRefs.Size > vertWallRefs.Size && vertWithOpeningsRefs.Size >= 2)
                {
                    try
                    {
                        XYZ shiftCenter = center + XYZ.BasisY * offsetFeet;
                        Line xLine = Line.CreateBound(shiftCenter - XYZ.BasisX * 50.0, shiftCenter + XYZ.BasisX * 50.0);
                        Dimension d = doc.Create.NewDimension(view, xLine, vertWithOpeningsRefs, dimType);
                        if (d != null) createdDims++;
                    }
                    catch { }
                }

                if (horizWithOpeningsRefs.Size > horizWallRefs.Size && horizWithOpeningsRefs.Size >= 2)
                {
                    try
                    {
                        XYZ shiftCenter = center + XYZ.BasisX * offsetFeet;
                        Line yLine = Line.CreateBound(shiftCenter - XYZ.BasisY * 50.0, shiftCenter + XYZ.BasisY * 50.0);
                        Dimension d = doc.Create.NewDimension(view, yLine, horizWithOpeningsRefs, dimType);
                        if (d != null) createdDims++;
                    }
                    catch { }
                }
            }

            return createdDims;
        }

        public static int DimensionExteriorInPlan(
            Document doc,
            View view,
            DimensionType dimType,
            bool chainGrids,
            bool chainWalls,
            double baseOffsetMm,
            double stackStepMm)
        {
            if (doc == null || view == null) return 0;

            var walls = new FilteredElementCollector(doc, view.Id)
                .OfClass(typeof(Wall))
                .Cast<Wall>()
                .ToList();

            var grids = new FilteredElementCollector(doc, view.Id)
                .OfClass(typeof(Grid))
                .Cast<Grid>()
                .ToList();

            if (walls.Count == 0 && grids.Count == 0) return 0;

            double minX = double.MaxValue, maxX = double.MinValue;
            double minY = double.MaxValue, maxY = double.MinValue;
            double z = view.GenLevel != null ? view.GenLevel.Elevation : 0.0;

            foreach (Wall w in walls)
            {
                BoundingBoxXYZ bb = w.get_BoundingBox(view);
                if (bb == null) continue;
                minX = Math.Min(minX, bb.Min.X);
                maxX = Math.Max(maxX, bb.Max.X);
                minY = Math.Min(minY, bb.Min.Y);
                maxY = Math.Max(maxY, bb.Max.Y);
            }

            if (minX == double.MaxValue) return 0;

            double baseOffFeet = UnitUtils.ConvertToInternalUnits(Math.Max(600, baseOffsetMm), UnitTypeId.Millimeters);
            double stepFeet = UnitUtils.ConvertToInternalUnits(Math.Max(400, stackStepMm), UnitTypeId.Millimeters);
            int created = 0;

            // 1. Grids Chain (Horizontal X and Vertical Y)
            if (chainGrids && grids.Count >= 2)
            {
                var xGridRefs = new ReferenceArray();
                var yGridRefs = new ReferenceArray();

                foreach (Grid g in grids)
                {
                    if (!(g.Curve is Line gl)) continue;
                    XYZ dir = (gl.GetEndPoint(1) - gl.GetEndPoint(0)).Normalize();
                    Reference gRef = new Reference(g);
                    if (Math.Abs(dir.Y) >= 0.85) xGridRefs.Append(gRef);
                    else if (Math.Abs(dir.X) >= 0.85) yGridRefs.Append(gRef);
                }

                if (xGridRefs.Size >= 2)
                {
                    try
                    {
                        double yPos = maxY + baseOffFeet;
                        Line dimLine = Line.CreateBound(new XYZ(minX - 10, yPos, z), new XYZ(maxX + 10, yPos, z));
                        if (doc.Create.NewDimension(view, dimLine, xGridRefs, dimType) != null) created++;
                    }
                    catch { }
                }

                if (yGridRefs.Size >= 2)
                {
                    try
                    {
                        double xPos = minX - baseOffFeet;
                        Line dimLine = Line.CreateBound(new XYZ(xPos, minY - 10, z), new XYZ(xPos, maxY + 10, z));
                        if (doc.Create.NewDimension(view, dimLine, yGridRefs, dimType) != null) created++;
                    }
                    catch { }
                }
            }

            // 2. Exterior Wall Segments Chain
            if (chainWalls && walls.Count >= 2)
            {
                var xWallRefs = new ReferenceArray();
                var yWallRefs = new ReferenceArray();

                foreach (Wall w in walls)
                {
                    if (!(w.Location is LocationCurve lc) || !(lc.Curve is Line wl)) continue;
                    XYZ dir = (wl.GetEndPoint(1) - wl.GetEndPoint(0)).Normalize();
                    Reference faceRef = GetWallFaceReference(w, true);
                    if (faceRef == null) continue;

                    if (Math.Abs(dir.Y) >= 0.9) xWallRefs.Append(faceRef);
                    else if (Math.Abs(dir.X) >= 0.9) yWallRefs.Append(faceRef);
                }

                if (xWallRefs.Size >= 2)
                {
                    try
                    {
                        double yPos = maxY + baseOffFeet + stepFeet;
                        Line dimLine = Line.CreateBound(new XYZ(minX - 10, yPos, z), new XYZ(maxX + 10, yPos, z));
                        if (doc.Create.NewDimension(view, dimLine, xWallRefs, dimType) != null) created++;
                    }
                    catch { }
                }

                if (yWallRefs.Size >= 2)
                {
                    try
                    {
                        double xPos = minX - (baseOffFeet + stepFeet);
                        Line dimLine = Line.CreateBound(new XYZ(xPos, minY - 10, z), new XYZ(xPos, maxY + 10, z));
                        if (doc.Create.NewDimension(view, dimLine, yWallRefs, dimType) != null) created++;
                    }
                    catch { }
                }
            }

            return created;
        }

        public static int DimensionElevationOrSection(Document doc, View view, DimensionType dimType)
        {
            if (doc == null || view == null) return 0;

            var levels = new FilteredElementCollector(doc, view.Id)
                .OfClass(typeof(Level))
                .Cast<Level>()
                .OrderBy(l => l.Elevation)
                .ToList();

            if (levels.Count < 2) return 0;

            var refArray = new ReferenceArray();
            foreach (Level lvl in levels)
            {
                Reference r = lvl.GetPlaneReference();
                if (r != null) refArray.Append(r);
            }

            if (refArray.Size < 2) return 0;

            BoundingBoxXYZ bb = view.CropBox;
            XYZ origin = bb != null ? bb.Transform.Origin : XYZ.Zero;
            Line vertLine = Line.CreateBound(origin - XYZ.BasisZ * 50.0, origin + XYZ.BasisZ * 50.0);

            try
            {
                Dimension d = doc.Create.NewDimension(view, vertLine, refArray, dimType);
                return d != null ? 1 : 0;
            }
            catch
            {
                return 0;
            }
        }

        private static Reference GetWallFaceReference(Wall wall, bool exterior)
        {
            try
            {
                IList<Reference> refs = HostObjectUtils.GetSideFaces(wall, exterior ? ShellLayerType.Exterior : ShellLayerType.Interior);
                if (refs != null && refs.Count > 0) return refs[0];
            }
            catch { }

            try
            {
                Options opt = new Options { ComputeReferences = true, IncludeNonVisibleObjects = true };
                GeometryElement geo = wall.get_Geometry(opt);
                if (geo != null)
                {
                    foreach (GeometryObject obj in geo)
                    {
                        if (obj is Solid s)
                        {
                            foreach (Face f in s.Faces)
                            {
                                if (f is PlanarFace pf && Math.Abs(pf.FaceNormal.Z) < 0.1 && pf.Reference != null)
                                    return pf.Reference;
                            }
                        }
                    }
                }
            }
            catch { }
            return null;
        }

        // =========================================================================
        // 2. GOAT ANNOTATE ENGINE (Smart Multi-Category Tagging + Anti-Collision)
        // =========================================================================

        public static int TagElementsInView(
            Document doc,
            View view,
            IList<BuiltInCategory> categories,
            bool addLeader,
            bool preventCollisions,
            bool tagRooms)
        {
            if (doc == null || view == null) return 0;
            int createdTags = 0;
            var placedTagCenters = new List<XYZ>();
            double minTagDistFeet = UnitUtils.ConvertToInternalUnits(550.0, UnitTypeId.Millimeters);

            // 1. Tag Rooms if requested
            if (tagRooms && (view.ViewType == ViewType.FloorPlan || view.ViewType == ViewType.CeilingPlan || view.ViewType == ViewType.Section || view.ViewType == ViewType.Elevation))
            {
                var existingTaggedRoomIds = new FilteredElementCollector(doc, view.Id)
                    .OfClass(typeof(SpatialElementTag))
                    .OfType<RoomTag>()
                    .Where(rt => rt.Room != null)
                    .Select(rt => rt.Room.Id.Value)
                    .ToHashSet();

                var rooms = new FilteredElementCollector(doc, view.Id)
                    .OfCategory(BuiltInCategory.OST_Rooms)
                    .WhereElementIsNotElementType()
                    .OfType<Room>()
                    .Where(r => r.Area > 0.001 && r.Location is LocationPoint);

                foreach (Room r in rooms)
                {
                    if (existingTaggedRoomIds.Contains(r.Id.Value)) continue;
                    if (!(r.Location is LocationPoint lp)) continue;
                    try
                    {
                        RoomTag rt = doc.Create.NewRoomTag(new LinkElementId(r.Id), new UV(lp.Point.X, lp.Point.Y), view.Id);
                        if (rt != null)
                        {
                            placedTagCenters.Add(lp.Point);
                            createdTags++;
                        }
                    }
                    catch { }
                }
            }

            // 2. Tag Selected Model Categories with Anti-Collision Engine
            if (categories != null && categories.Count > 0)
            {
                // Collect already tagged elements in this view so we never create duplicate tags
                var alreadyTaggedIds = new HashSet<long>();
                var existingTags = new FilteredElementCollector(doc, view.Id)
                    .OfClass(typeof(IndependentTag))
                    .Cast<IndependentTag>();

                foreach (IndependentTag t in existingTags)
                {
                    try
                    {
                        foreach (LinkElementId lid in t.GetTaggedElementIds())
                        {
                            if (lid.HostElementId != ElementId.InvalidElementId)
                                alreadyTaggedIds.Add(lid.HostElementId.Value);
                        }
                        placedTagCenters.Add(t.TagHeadPosition);
                    }
                    catch { }
                }

                foreach (BuiltInCategory bic in categories)
                {
                    if (bic == BuiltInCategory.OST_Rooms) continue;

                    var elements = new FilteredElementCollector(doc, view.Id)
                        .OfCategory(bic)
                        .WhereElementIsNotElementType()
                        .ToList();

                    foreach (Element el in elements)
                    {
                        if (alreadyTaggedIds.Contains(el.Id.Value)) continue;

                        XYZ rawPos = GetElementCenterInView(el, view);
                        if (rawPos == null) continue;

                        XYZ finalTagPos = preventCollisions
                            ? FindNonCollidingTagPoint(rawPos, placedTagCenters, minTagDistFeet, view)
                            : rawPos;

                        bool needsLeader = addLeader || finalTagPos.DistanceTo(rawPos) > 0.15;

                        try
                        {
                            Reference elRef = new Reference(el);
                            IndependentTag tag = IndependentTag.Create(
                                doc,
                                view.Id,
                                elRef,
                                needsLeader,
                                TagMode.TM_ADDBY_CATEGORY,
                                TagOrientation.Horizontal,
                                finalTagPos);

                            if (tag != null)
                            {
                                placedTagCenters.Add(finalTagPos);
                                alreadyTaggedIds.Add(el.Id.Value);
                                createdTags++;
                            }
                        }
                        catch { }
                    }
                }
            }

            return createdTags;
        }

        private static XYZ GetElementCenterInView(Element el, View view)
        {
            if (el.Location is LocationPoint lp)
                return lp.Point;
            if (el.Location is LocationCurve lc && lc.Curve != null)
                return lc.Curve.Evaluate(0.5, true);

            BoundingBoxXYZ bb = el.get_BoundingBox(view) ?? el.get_BoundingBox(null);
            if (bb != null)
                return (bb.Min + bb.Max) * 0.5;

            return null;
        }

        private static XYZ FindNonCollidingTagPoint(XYZ origin, List<XYZ> occupied, double minDistFeet, View view)
        {
            bool Overlaps(XYZ pt)
            {
                foreach (XYZ occ in occupied)
                {
                    double dx = pt.X - occ.X;
                    double dy = pt.Y - occ.Y;
                    if (Math.Sqrt(dx * dx + dy * dy) < minDistFeet)
                        return true;
                }
                return false;
            }

            if (!Overlaps(origin)) return origin;

            XYZ right = view.RightDirection;
            XYZ up = view.UpDirection;

            // Spiral / radial search in view plane
            double[] radii = { minDistFeet, minDistFeet * 1.6, minDistFeet * 2.3, minDistFeet * 3.0 };
            double[] anglesDeg = { 45, -45, 135, -135, 0, 90, 180, -90 };

            foreach (double r in radii)
            {
                foreach (double deg in anglesDeg)
                {
                    double rad = deg * Math.PI / 180.0;
                    XYZ candidate = origin + right * (r * Math.Cos(rad)) + up * (r * Math.Sin(rad));
                    if (!Overlaps(candidate))
                        return candidate;
                }
            }

            return origin + up * minDistFeet;
        }

        // =========================================================================
        // 3. GOAT SHEET PACKER ENGINE (Glyph Auto-Pack Views on Sheet)
        // =========================================================================

        public static int PackViewsOntoSheet(
            Document doc,
            ViewSheet sheet,
            IList<ElementId> viewIdsToPlaceAndPack,
            bool packExistingViewportsOnly = false)
        {
            if (doc == null || sheet == null) return 0;

            var viewports = new List<Viewport>();

            if (!packExistingViewportsOnly && viewIdsToPlaceAndPack != null)
            {
                foreach (ElementId vid in viewIdsToPlaceAndPack)
                {
                    if (vid == null || vid == ElementId.InvalidElementId) continue;
                    if (Viewport.CanAddViewToSheet(doc, sheet.Id, vid))
                    {
                        try
                        {
                            Viewport vp = Viewport.Create(doc, sheet.Id, vid, XYZ.Zero);
                            if (vp != null) viewports.Add(vp);
                        }
                        catch { }
                    }
                }
            }

            if (packExistingViewportsOnly || viewports.Count == 0)
            {
                foreach (ElementId vpId in sheet.GetAllViewports())
                {
                    if (doc.GetElement(vpId) is Viewport vp)
                        viewports.Add(vp);
                }
            }

            if (viewports.Count == 0) return 0;

            // Determine Titleblock usable drawing area
            double minX = 0.12, minY = 0.12;
            double maxX = 2.40, maxY = 1.80; // Default A1 usable space in feet

            var titleBlocks = new FilteredElementCollector(doc, sheet.Id)
                .OfCategory(BuiltInCategory.OST_TitleBlocks)
                .WhereElementIsNotElementType()
                .ToList();

            if (titleBlocks.Count > 0)
            {
                BoundingBoxXYZ tbb = titleBlocks[0].get_BoundingBox(sheet);
                if (tbb != null)
                {
                    double w = tbb.Max.X - tbb.Min.X;
                    double h = tbb.Max.Y - tbb.Min.Y;
                    minX = tbb.Min.X + w * 0.05;
                    maxX = tbb.Max.X - w * 0.16; // Reserve right titleblock strip
                    minY = tbb.Min.Y + h * 0.06;
                    maxY = tbb.Max.Y - h * 0.05;
                }
            }

            int count = viewports.Count;
            int cols = count <= 2 ? count : (count <= 4 ? 2 : (count <= 6 ? 3 : 4));
            int rows = (int)Math.Ceiling((double)count / cols);

            double cellW = (maxX - minX) / cols;
            double cellH = (maxY - minY) / rows;

            for (int i = 0; i < count; i++)
            {
                int r = i / cols;
                int c = i % cols;

                double cx = minX + (c + 0.5) * cellW;
                // Top row first (rows - 1 - r)
                double cy = minY + (rows - 1 - r + 0.5) * cellH;

                try
                {
                    viewports[i].SetBoxCenter(new XYZ(cx, cy, 0));
                }
                catch { }
            }

            return viewports.Count;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Windows;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Architecture;
using Autodesk.Revit.UI;
using ORTools.Models;

namespace ORTools.UI
{
    public class GoatDimEventHandler : IExternalEventHandler
    {
        public GoatDimWindow Window { get; set; }
        public bool IsScanOnly { get; set; }

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc?.Document == null) return;
            Document doc = uidoc.Document;

            try
            {
                if (IsScanOnly)
                {
                    var dimTypes = new FilteredElementCollector(doc)
                        .OfClass(typeof(DimensionType))
                        .Cast<DimensionType>()
                        .Where(d => d.StyleType == DimensionStyleType.Linear)
                        .OrderBy(d => d.Name)
                        .Select(d => new ElementTypeOption { Id = d.Id, Name = d.Name })
                        .ToList();
                    Window.LoadDimTypes(dimTypes);
                    return;
                }

                View view = doc.ActiveView;
                if (view == null) return;

                DimensionType dimType = null;
                ElementId selId = Window.SelectedDimTypeId;
                if (selId != ElementId.InvalidElementId)
                    dimType = doc.GetElement(selId) as DimensionType;

                double.TryParse(Window.TxtStackOffset.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double stackMm);
                double.TryParse(Window.TxtExteriorOffset.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double extMm);

                int created = 0;
                using (TransactionGroup tg = new TransactionGroup(doc, "GOAT DIM — Auto Dimensioning"))
                {
                    tg.Start();
                    using (Transaction trans = new Transaction(doc, "Create Dimensions"))
                    {
                        trans.Start();

                        if (Window.RbModeInteriorRooms.IsChecked == true)
                        {
                            var rooms = new FilteredElementCollector(doc, view.Id)
                                .OfCategory(BuiltInCategory.OST_Rooms)
                                .WhereElementIsNotElementType()
                                .OfType<Room>()
                                .Where(r => r.Area > 0.001)
                                .ToList();

                            foreach (Room r in rooms)
                            {
                                created += GoatDocEngines.DimensionRoomInPlan(
                                    doc,
                                    view,
                                    r,
                                    dimType,
                                    Window.ChkRoomClearCross.IsChecked == true,
                                    Window.ChkRoomOpenings.IsChecked == true,
                                    stackMm > 50 ? stackMm : 450);
                            }
                        }
                        else if (Window.RbModeExteriorBuilding.IsChecked == true)
                        {
                            created += GoatDocEngines.DimensionExteriorInPlan(
                                doc,
                                view,
                                dimType,
                                Window.ChkExtGrids.IsChecked == true,
                                true,
                                extMm > 100 ? extMm : 1200,
                                stackMm > 50 ? stackMm : 450);
                        }
                        else
                        {
                            created += GoatDocEngines.DimensionElevationOrSection(doc, view, dimType);
                        }

                        trans.Commit();
                    }
                    tg.Assimilate();
                }

                Window.TxtStatus.Text = $"✔ Created {created} dimension chains in '{view.Name}'. (1x Ctrl+Z to Undo)";
            }
            catch (Exception ex)
            {
                Window.TxtStatus.Text = $"Error: {ex.Message}";
            }
        }

        public string GetName() => "GOAT DIM External Event Handler";
    }

    public partial class GoatDimWindow : Window
    {
        private readonly GoatDimEventHandler _handler;
        private readonly ExternalEvent _extEvent;

        public ElementId SelectedDimTypeId => (CbDimTypes.SelectedItem as ElementTypeOption)?.Id ?? ElementId.InvalidElementId;

        public GoatDimWindow(GoatDimEventHandler handler, ExternalEvent extEvent)
        {
            InitializeComponent();
            _handler = handler;
            _extEvent = extEvent;
            _handler.Window = this;

            Loaded += (s, e) =>
            {
                _handler.IsScanOnly = true;
                _extEvent.Raise();
            };
        }

        public void LoadDimTypes(List<ElementTypeOption> types)
        {
            CbDimTypes.ItemsSource = types;
            if (types.Count > 0) CbDimTypes.SelectedIndex = 0;
        }

        private void BtnGenerate_Click(object sender, RoutedEventArgs e)
        {
            _handler.IsScanOnly = false;
            _extEvent.Raise();
        }

        private void BtnClose_Click(object sender, RoutedEventArgs e) => Close();
    }
}

using System;
using System.Collections.Generic;
using System.Windows;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using ORTools.Models;

namespace ORTools.UI
{
    public class GoatAnnotateEventHandler : IExternalEventHandler
    {
        public GoatAnnotateWindow Window { get; set; }

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc?.Document == null || uidoc.Document.ActiveView == null) return;
            Document doc = uidoc.Document;
            View view = doc.ActiveView;

            try
            {
                var cats = Window.GetSelectedCategories();
                bool tagRooms = Window.ChkCatRooms.IsChecked == true;
                bool preventCollisions = Window.ChkPreventCollisions.IsChecked == true;
                bool addLeaders = Window.ChkAddLeaders.IsChecked == true;

                int count = 0;
                using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ANNOTATE — Smart Batch Tagging"))
                {
                    tg.Start();
                    using (Transaction trans = new Transaction(doc, "Place Smart Tags"))
                    {
                        trans.Start();
                        count = GoatDocEngines.TagElementsInView(doc, view, cats, addLeaders, preventCollisions, tagRooms);
                        trans.Commit();
                    }
                    tg.Assimilate();
                }

                Window.TxtStatus.Text = $"✔ Placed {count} smart tags in '{view.Name}' with collision avoidance. (1x Ctrl+Z to Undo)";
            }
            catch (Exception ex)
            {
                Window.TxtStatus.Text = $"Error: {ex.Message}";
            }
        }

        public string GetName() => "GOAT ANNOTATE External Event Handler";
    }

    public partial class GoatAnnotateWindow : Window
    {
        private readonly GoatAnnotateEventHandler _handler;
        private readonly ExternalEvent _extEvent;

        public GoatAnnotateWindow(GoatAnnotateEventHandler handler, ExternalEvent extEvent)
        {
            InitializeComponent();
            _handler = handler;
            _extEvent = extEvent;
            _handler.Window = this;
        }

        public List<BuiltInCategory> GetSelectedCategories()
        {
            var list = new List<BuiltInCategory>();
            if (ChkCatDoors.IsChecked == true) list.Add(BuiltInCategory.OST_Doors);
            if (ChkCatWindows.IsChecked == true) list.Add(BuiltInCategory.OST_Windows);
            if (ChkCatWalls.IsChecked == true) list.Add(BuiltInCategory.OST_Walls);
            if (ChkCatFloors.IsChecked == true) list.Add(BuiltInCategory.OST_Floors);
            if (ChkCatCeilings.IsChecked == true) list.Add(BuiltInCategory.OST_Ceilings);
            if (ChkCatFurniture.IsChecked == true) list.Add(BuiltInCategory.OST_Furniture);
            if (ChkCatPlumbing.IsChecked == true) list.Add(BuiltInCategory.OST_PlumbingFixtures);
            if (ChkCatCasework.IsChecked == true) list.Add(BuiltInCategory.OST_Casework);
            if (ChkCatLighting.IsChecked == true) list.Add(BuiltInCategory.OST_LightingFixtures);
            return list;
        }

        private void BtnTag_Click(object sender, RoutedEventArgs e)
        {
            _extEvent.Raise();
        }

        private void BtnClose_Click(object sender, RoutedEventArgs e) => Close();
    }
}

using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Architecture;
using Autodesk.Revit.UI;
using ORTools.Commands;
using ORTools.Models;

namespace ORTools.UI
{
    public class GoatRoomEventHandler : IExternalEventHandler
    {
        public GoatRoomWindow Window { get; set; }
        public bool IsScanOnly { get; set; }

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc?.Document == null) return;
            Document doc = uidoc.Document;

            try
            {
                if (IsScanOnly)
                {
                    ExecuteScan(doc);
                    return;
                }

                ExecuteGenerateBundle(doc);
            }
            catch (Exception ex)
            {
                Window.TxtStatus.Text = $"Error: {ex.Message}";
            }
        }

        public string GetName() => "GOAT ROOM Bundle External Event Handler";

        private void ExecuteScan(Document doc)
        {
            var titleBlocks = new FilteredElementCollector(doc)
                .OfCategory(BuiltInCategory.OST_TitleBlocks)
                .WhereElementIsElementType()
                .OfType<FamilySymbol>()
                .OrderBy(t => t.FamilyName)
                .ThenBy(t => t.Name)
                .Select(t => new ElementTypeOption { Id = t.Id, Name = $"{t.FamilyName} : {t.Name}" })
                .ToList();

            bool activeOnly = Window.RbActiveView.IsChecked == true;
            FilteredElementCollector rc = (activeOnly && doc.ActiveView != null)
                ? new FilteredElementCollector(doc, doc.ActiveView.Id)
                : new FilteredElementCollector(doc);

            var rooms = rc.OfCategory(BuiltInCategory.OST_Rooms)
                .WhereElementIsNotElementType()
                .OfType<Room>()
                .Where(r => r.Area > 0.001 && r.Location != null)
                .OrderBy(r => r.Number)
                .Select(r => new CeilingRoomItem
                {
                    IsSelected = true,
                    RoomId = r.Id,
                    LevelId = r.LevelId,
                    RoomNumber = r.Number ?? "",
                    RoomName = r.get_Parameter(BuiltInParameter.ROOM_NAME)?.AsString() ?? r.Name ?? "Room",
                    AreaSqm = Math.Round(UnitUtils.ConvertFromInternalUnits(r.Area, UnitTypeId.SquareMeters), 2)
                })
                .ToList();

            Window.LoadScannedData(titleBlocks, rooms);
        }

        private void ExecuteGenerateBundle(Document doc)
        {
            var selectedRooms = Window.RoomList.Where(r => r.IsSelected).ToList();
            if (selectedRooms.Count == 0)
            {
                Window.TxtStatus.Text = "Please select at least one room.";
                return;
            }

            var vfts = new FilteredElementCollector(doc).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>().ToList();
            ViewFamilyType planVft = vfts.FirstOrDefault(v => v.ViewFamily == ViewFamily.FloorPlan);
            ViewFamilyType rcpVft = vfts.FirstOrDefault(v => v.ViewFamily == ViewFamily.CeilingPlan);
            ViewFamilyType elevVft = vfts.FirstOrDefault(v => v.ViewFamily == ViewFamily.Elevation);
            ViewFamilyType secVft = vfts.FirstOrDefault(v => v.ViewFamily == ViewFamily.Section);
            ViewFamilyType isoVft = vfts.FirstOrDefault(v => v.ViewFamily == ViewFamily.ThreeDimensional);

            DimensionType dimType = new FilteredElementCollector(doc)
                .OfClass(typeof(DimensionType))
                .Cast<DimensionType>()
                .FirstOrDefault(d => d.StyleType == DimensionStyleType.Linear);

            double.TryParse(Window.TxtCropOffset.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out double cropMm);
            double cropFeet = UnitUtils.ConvertToInternalUnits(Math.Max(50, cropMm), UnitTypeId.Millimeters);
            int.TryParse(Window.TxtViewScale.Text, out int scale);
            if (scale < 1) scale = 50;

            string formula = string.IsNullOrWhiteSpace(Window.TxtNamingFormula.Text)
                ? "RM-{Number} - {Name} - {Type}"
                : Window.TxtNamingFormula.Text;

            bool genPlan = Window.ChkGenPlan.IsChecked == true;
            bool genRcp = Window.ChkGenRcp.IsChecked == true;
            bool genElev = Window.ChkGenElevations.IsChecked == true;
            bool elevParallelAll = Window.RbElevAllWalls.IsChecked == true;
            bool gen3D = Window.ChkGen3DIso.IsChecked == true;

            bool autoDim = Window.ChkBundleAutoDim.IsChecked == true;
            bool autoTag = Window.ChkBundleAutoTag.IsChecked == true;
            bool packSheet = Window.ChkBundlePackSheet.IsChecked == true;
            ElementId tbId = (Window.CbTitleBlocks.SelectedItem as ElementTypeOption)?.Id ?? ElementId.InvalidElementId;
            string sheetPrefix = Window.TxtSheetPrefix.Text?.Trim() ?? "ID-";

            var tagCategories = new List<BuiltInCategory>
            {
                BuiltInCategory.OST_Doors,
                BuiltInCategory.OST_Windows,
                BuiltInCategory.OST_PlumbingFixtures,
                BuiltInCategory.OST_Casework
            };

            var boundaryOpts = new SpatialElementBoundaryOptions
            {
                SpatialElementBoundaryLocation = SpatialElementBoundaryLocation.Finish
            };

            int totalViews = 0;
            int totalDims = 0;
            int totalTags = 0;
            int totalSheets = 0;

            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ROOM — Generate Room Documentation Bundle"))
            {
                tg.Start();
                using (Transaction trans = new Transaction(doc, "Create Room Views, Dims, Tags & Sheets"))
                {
                    trans.Start();

                    foreach (var item in selectedRooms)
                    {
                        Room room = doc.GetElement(item.RoomId) as Room;
                        if (room == null) continue;
                        BoundingBoxXYZ rbb = room.get_BoundingBox(null);
                        if (rbb == null) continue;

                        BoundingBoxXYZ paddedBox = new BoundingBoxXYZ
                        {
                            Min = new XYZ(rbb.Min.X - cropFeet, rbb.Min.Y - cropFeet, rbb.Min.Z - cropFeet),
                            Max = new XYZ(rbb.Max.X + cropFeet, rbb.Max.Y + cropFeet, rbb.Max.Z + cropFeet)
                        };

                        var roomGeneratedViewIds = new List<ElementId>();

                        // 1. Enlarged Floor Plan
                        if (genPlan && planVft != null)
                        {
                            try
                            {
                                ViewPlan vp = ViewPlan.Create(doc, planVft.Id, room.LevelId);
                                if (vp != null)
                                {
                                    vp.Scale = scale;
                                    vp.CropBoxActive = true;
                                    vp.CropBoxVisible = false;
                                    vp.CropBox = paddedBox;
                                    SetUniqueViewName(doc, vp, FormatRoomViewName(formula, item.RoomNumber, item.RoomName, "Enlarged Plan"));

                                    if (autoDim)
                                        totalDims += GoatDocEngines.DimensionRoomInPlan(doc, vp, room, dimType, true, true, 400);
                                    if (autoTag)
                                        totalTags += GoatDocEngines.TagElementsInView(doc, vp, tagCategories, false, true, true);

                                    roomGeneratedViewIds.Add(vp.Id);
                                    totalViews++;
                                }
                            }
                            catch { }
                        }

                        // 2. Reflected Ceiling Plan (RCP)
                        if (genRcp && rcpVft != null)
                        {
                            try
                            {
                                ViewPlan rcp = ViewPlan.Create(doc, rcpVft.Id, room.LevelId);
                                if (rcp != null)
                                {
                                    rcp.Scale = scale;
                                    rcp.CropBoxActive = true;
                                    rcp.CropBoxVisible = false;
                                    rcp.CropBox = paddedBox;
                                    SetUniqueViewName(doc, rcp, FormatRoomViewName(formula, item.RoomNumber, item.RoomName, "RCP"));
                                    roomGeneratedViewIds.Add(rcp.Id);
                                    totalViews++;
                                }
                            }
                            catch { }
                        }

                        // 3. Interior Elevations (Standard 4-Way N/S/E/W OR Parallel to All Room Walls)
                        if (genElev)
                        {
                            if (!elevParallelAll && elevVft != null)
                            {
                                try
                                {
                                    XYZ center = (rbb.Min + rbb.Max) * 0.5;
                                    ElevationMarker marker = ElevationMarker.CreateElevationMarker(doc, elevVft.Id, center, scale);
                                    string[] dirs = { "West", "North", "East", "South" };
                                    for (int i = 0; i < 4; i++)
                                    {
                                        try
                                        {
                                            ViewSection elevView = marker.CreateElevation(doc, doc.ActiveView.Id, i);
                                            if (elevView != null)
                                            {
                                                elevView.Scale = scale;
                                                SetUniqueViewName(doc, elevView, FormatRoomViewName(formula, item.RoomNumber, item.RoomName, $"Elev - {dirs[i]}"));
                                                if (autoDim)
                                                    totalDims += GoatDocEngines.DimensionElevationOrSection(doc, elevView, dimType);
                                                if (autoTag)
                                                    totalTags += GoatDocEngines.TagElementsInView(doc, elevView, tagCategories, false, true, false);
                                                roomGeneratedViewIds.Add(elevView.Id);
                                                totalViews++;
                                            }
                                        }
                                        catch { }
                                    }
                                }
                                catch { }
                            }
                            else if (secVft != null)
                            {
                                // Parallel to Every Room Wall Segment (supports angled & L-shaped rooms!)
                                IList<IList<BoundarySegment>> loops = room.GetBoundarySegments(boundaryOpts);
                                if (loops != null && loops.Count > 0)
                                {
                                    int wallIdx = 1;
                                    foreach (BoundarySegment seg in loops[0])
                                    {
                                        Curve c = seg.GetCurve();
                                        if (c == null || c.Length < UnitUtils.ConvertToInternalUnits(600.0, UnitTypeId.Millimeters))
                                            continue;

                                        try
                                        {
                                            XYZ p0 = c.GetEndPoint(0);
                                            XYZ p1 = c.GetEndPoint(1);
                                            XYZ wallDir = (p1 - p0).Normalize();
                                            XYZ viewDir = new XYZ(wallDir.Y, -wallDir.X, 0).Normalize();
                                            XYZ mid = (p0 + p1) * 0.5 - viewDir * UnitUtils.ConvertToInternalUnits(1000.0, UnitTypeId.Millimeters);

                                            Transform t = Transform.Identity;
                                            t.Origin = new XYZ(mid.X, mid.Y, rbb.Min.Z);
                                            t.BasisX = wallDir;
                                            t.BasisY = XYZ.BasisZ;
                                            t.BasisZ = wallDir.CrossProduct(XYZ.BasisZ).Normalize();

                                            double halfLen = c.Length * 0.5 + cropFeet;
                                            double height = Math.Max(UnitUtils.ConvertToInternalUnits(2800.0, UnitTypeId.Millimeters), rbb.Max.Z - rbb.Min.Z);
                                            BoundingBoxXYZ secBox = new BoundingBoxXYZ
                                            {
                                                Transform = t,
                                                Min = new XYZ(-halfLen, -cropFeet, 0),
                                                Max = new XYZ(halfLen, height + cropFeet, UnitUtils.ConvertToInternalUnits(1500.0, UnitTypeId.Millimeters))
                                            };

                                            ViewSection wallElev = ViewSection.CreateSection(doc, secVft.Id, secBox);
                                            if (wallElev != null)
                                            {
                                                wallElev.Scale = scale;
                                                SetUniqueViewName(doc, wallElev, FormatRoomViewName(formula, item.RoomNumber, item.RoomName, $"Wall Elev {wallIdx}"));
                                                roomGeneratedViewIds.Add(wallElev.Id);
                                                totalViews++;
                                                wallIdx++;
                                            }
                                        }
                                        catch { }
                                    }
                                }
                            }
                        }

                        // 4. 3D Room Isometric (Section Box)
                        if (gen3D && isoVft != null)
                        {
                            try
                            {
                                View3D iso = View3D.CreateIsometric(doc, isoVft.Id);
                                if (iso != null)
                                {
                                    iso.Scale = scale;
                                    iso.SetSectionBox(paddedBox);
                                    SetUniqueViewName(doc, iso, FormatRoomViewName(formula, item.RoomNumber, item.RoomName, "3D Iso"));
                                    roomGeneratedViewIds.Add(iso.Id);
                                    totalViews++;
                                }
                            }
                            catch { }
                        }

                        // 5. Create Dedicated Sheet & Auto-Pack Views
                        if (packSheet && roomGeneratedViewIds.Count > 0)
                        {
                            try
                            {
                                ViewSheet sheet = ViewSheet.Create(doc, tbId);
                                if (sheet != null)
                                {
                                    sheet.Name = $"{item.RoomName} — Interior Documentation";
                                    SetUniqueSheetNumber(doc, sheet, $"{sheetPrefix}{item.RoomNumber}");
                                    GoatDocEngines.PackViewsOntoSheet(doc, sheet, roomGeneratedViewIds, false);
                                    totalSheets++;
                                }
                            }
                            catch { }
                        }
                    }

                    trans.Commit();
                }
                tg.Assimilate();
            }

            Window.TxtStatus.Text = $"✔ Generated {totalViews} Views · {totalDims} Dim Chains · {totalTags} Smart Tags · {totalSheets} Packed Sheets! (1x Ctrl+Z to Undo)";
        }

        private static string FormatRoomViewName(string formula, string num, string name, string type)
        {
            return formula
                .Replace("{Number}", string.IsNullOrWhiteSpace(num) ? "00" : num)
                .Replace("{Name}", string.IsNullOrWhiteSpace(name) ? "Room" : name)
                .Replace("{Type}", type);
        }

        private static void SetUniqueViewName(Document doc, View v, string baseName)
        {
            string clean = SanitizeRevitName(baseName);
            for (int i = 0; i < 50; i++)
            {
                string candidate = i == 0 ? clean : $"{clean} ({i + 1})";
                try
                {
                    v.Name = candidate;
                    return;
                }
                catch { }
            }
        }

        private static void SetUniqueSheetNumber(Document doc, ViewSheet s, string baseNum)
        {
            string clean = SanitizeRevitName(baseNum);
            for (int i = 0; i < 100; i++)
            {
                string candidate = i == 0 ? clean : $"{clean}.{i}";
                try
                {
                    s.SheetNumber = candidate;
                    return;
                }
                catch { }
            }
        }

        private static string SanitizeRevitName(string s)
        {
            if (string.IsNullOrWhiteSpace(s)) return "GOAT_View";
            char[] forbidden = { '\\', ':', '{', '}', '[', ']', '|', ';', '<', '>', '?', '`', '~' };
            foreach (char c in forbidden) s = s.Replace(c, '-');
            return s.Trim();
        }
    }

