namespace ORTools.UI
{
    public class RenumberRowItem : INotifyPropertyChanged
    {
        private bool _isSelected = true;
        private string _proposedNumber = string.Empty;

        public ElementId ElementId { get; set; } = ElementId.InvalidElementId;
        public long IdValue => ElementId.Value;
        public string ElementTitle { get; set; } = string.Empty;
        public string HostRoomNumber { get; set; } = string.Empty;
        public string CurrentNumber { get; set; } = string.Empty;
        public double X { get; set; }
        public double Y { get; set; }

        public bool IsSelected
        {
            get => _isSelected;
            set { _isSelected = value; OnPropertyChanged(); }
        }

        public string ProposedNumber
        {
            get => _proposedNumber;
            set { _proposedNumber = value; OnPropertyChanged(); }
        }

        public event PropertyChangedEventHandler PropertyChanged;
        protected void OnPropertyChanged([CallerMemberName] string name = null)
            => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
    }

    public class GoatRenumberEventHandler : IExternalEventHandler
    {
        public GoatRenumberWindow Window { get; set; }
        public bool IsScanOnly { get; set; }

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc?.Document == null) return;
            Document doc = uidoc.Document;

            try
            {
                if (IsScanOnly)
                {
                    ExecuteScan(doc);
                    return;
                }

                if (Window.RbModeInteractivePick.IsChecked == true)
                {
                    ExecuteInteractivePick(uidoc, doc);
                }
                else
                {
                    ExecuteBatchApply(doc);
                }
            }
            catch (Exception ex)
            {
                Window.TxtStatus.Text = $"Error: {ex.Message}";
            }
        }

        public string GetName() => "GOAT RENUMBER External Event Handler";

        private void ExecuteScan(Document doc)
        {
            int catIdx = Window.CbCategory.SelectedIndex >= 0 ? Window.CbCategory.SelectedIndex : 0;
            bool activeOnly = Window.RbScopeActiveView.IsChecked == true;

            FilteredElementCollector col = (activeOnly && doc.ActiveView != null && catIdx != 4)
                ? new FilteredElementCollector(doc, doc.ActiveView.Id)
                : new FilteredElementCollector(doc);

            var elements = new List<Element>();
            switch (catIdx)
            {
                case 0: // Rooms
                    elements = col.OfCategory(BuiltInCategory.OST_Rooms).WhereElementIsNotElementType().ToList();
                    break;
                case 1: // Doors
                    elements = col.OfCategory(BuiltInCategory.OST_Doors).WhereElementIsNotElementType().ToList();
                    break;
                case 2: // Windows
                    elements = col.OfCategory(BuiltInCategory.OST_Windows).WhereElementIsNotElementType().ToList();
                    break;
                case 3: // Grids
                    elements = col.OfClass(typeof(Autodesk.Revit.DB.Grid)).ToList();
                    break;
                case 4: // Sheets
                    elements = new FilteredElementCollector(doc).OfClass(typeof(ViewSheet)).Cast<ViewSheet>().Where(s => !s.IsPlaceholder).Cast<Element>().ToList();
                    break;
                case 5: // Viewports on Active Sheet
                    if (doc.ActiveView is ViewSheet activeSheet)
                    {
                        elements = activeSheet.GetAllViewports().Select(id => doc.GetElement(id)).Where(e => e != null).ToList();
                    }
                    break;
                case 6: // Furniture & Casework
                    elements = col.WhereElementIsNotElementType()
                        .WherePasses(new LogicalOrFilter(
                            new ElementCategoryFilter(BuiltInCategory.OST_Furniture),
                            new ElementCategoryFilter(BuiltInCategory.OST_Casework)))
                        .ToList();
                    break;
                case 7: // Parking
                    elements = col.OfCategory(BuiltInCategory.OST_Parking).WhereElementIsNotElementType().ToList();
                    break;
            }

            // Collect Rooms for spatial lookup if non-door/window
            var allRooms = new FilteredElementCollector(doc)
                .OfCategory(BuiltInCategory.OST_Rooms)
                .WhereElementIsNotElementType()
                .OfType<Room>()
                .Where(r => r.Area > 0.001)
                .ToList();

            var rows = new List<RenumberRowItem>();
            foreach (Element el in elements)
            {
                XYZ pt = GetElementPosition(doc, el);
                string currentVal = GetElementNumberValue(el, catIdx);
                string hostRoomNum = GetElementHostRoomNumber(el, pt, allRooms);
                string title = GetElementDisplayTitle(doc, el);

                rows.Add(new RenumberRowItem
                {
                    ElementId = el.Id,
                    ElementTitle = title,
                    HostRoomNumber = hostRoomNum,
                    CurrentNumber = currentVal,
                    X = Math.Round(pt.X, 2),
                    Y = Math.Round(pt.Y, 2),
                    IsSelected = true
                });
            }

            Window.LoadScannedRows(rows);
        }

        private void ExecuteBatchApply(Document doc)
        {
            int catIdx = Window.CbCategory.SelectedIndex >= 0 ? Window.CbCategory.SelectedIndex : 0;
            var selectedRows = Window.Rows.Where(r => r.IsSelected && !string.IsNullOrWhiteSpace(r.ProposedNumber)).ToList();
            if (selectedRows.Count == 0) return;

            int updated = 0;
            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT RENUMBER — Batch Renumber"))
            {
                tg.Start();

                // PASS 1: Temporary unique prefix to eliminate any Revit duplicate Mark/Number/Name conflicts
                using (Transaction t1 = new Transaction(doc, "Pass 1 Temp Swap"))
                {
                    t1.Start();
                    int tmpIdx = 1;
                    foreach (var row in selectedRows)
                    {
                        Element el = doc.GetElement(row.ElementId);
                        if (el != null)
                        {
                            SetElementNumberValue(el, catIdx, $"__GOAT_TMP_{tmpIdx++}_{row.IdValue}");
                        }
                    }
                    t1.Commit();
                }

                // PASS 2: Assign final proposed numbers
                using (Transaction t2 = new Transaction(doc, "Pass 2 Final Numbers"))
                {
                    t2.Start();
                    foreach (var row in selectedRows)
                    {
                        Element el = doc.GetElement(row.ElementId);
                        if (el != null && SetElementNumberValue(el, catIdx, row.ProposedNumber))
                        {
                            row.CurrentNumber = row.ProposedNumber;
                            updated++;
                        }
                    }
                    t2.Commit();
                }

                tg.Assimilate();
            }

            Window.DgPreview.Items.Refresh();
            Window.TxtStatus.Text = $"✔ Successfully renumbered {updated} elements with zero duplicate conflicts! (1x Ctrl+Z to Undo)";
        }

        private void ExecuteInteractivePick(UIDocument uidoc, Document doc)
        {
            int catIdx = Window.CbCategory.SelectedIndex >= 0 ? Window.CbCategory.SelectedIndex : 0;
            string prefix = Window.TxtPrefix.Text ?? "";
            string suffix = Window.TxtSuffix.Text ?? "";
            int.TryParse(Window.TxtStartNum.Text, out int currentNum);
            if (currentNum <= 0) currentNum = 1;
            int.TryParse(Window.TxtStep.Text, out int step);
            if (step == 0) step = 1;
            int.TryParse(Window.TxtPadding.Text, out int pad);
            pad = Math.Clamp(pad, 1, 8);

            int pickedCount = 0;
            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT RENUMBER — Interactive Pick"))
            {
                tg.Start();
                while (true)
                {
                    Reference pickedRef = null;
                    string nextVal = $"{prefix}{currentNum.ToString().PadLeft(pad, '0')}{suffix}";
                    try
                    {
                        pickedRef = uidoc.Selection.PickObject(ObjectType.Element, $"Click element to assign '{nextVal}' (Press ESC to finish)");
                    }
                    catch
                    {
                        break;
                    }

                    if (pickedRef == null) break;
                    Element el = doc.GetElement(pickedRef.ElementId);
                    if (el == null) continue;

                    using (Transaction t = new Transaction(doc, $"Assign {nextVal}"))
                    {
                        t.Start();
                        if (SetElementNumberValue(el, catIdx, nextVal))
                        {
                            currentNum += step;
                            pickedCount++;
                        }
                        t.Commit();
                    }
                }
                tg.Assimilate();
            }

            ExecuteScan(doc);
            Window.TxtStatus.Text = $"✔ Interactive Pick finished: renumbered {pickedCount} elements. (1x Ctrl+Z to Undo)";
        }

        private static XYZ GetElementPosition(Document doc, Element el)
        {
            if (el is Viewport vp) return vp.GetBoxCenter();
            if (el.Location is LocationPoint lp) return lp.Point;
            if (el.Location is LocationCurve lc && lc.Curve != null) return lc.Curve.Evaluate(0.5, true);
            BoundingBoxXYZ bb = el.get_BoundingBox(null);
            if (bb != null) return (bb.Min + bb.Max) * 0.5;
            return XYZ.Zero;
        }

        private static string GetElementDisplayTitle(Document doc, Element el)
        {
            if (el is Room r)
                return r.get_Parameter(BuiltInParameter.ROOM_NAME)?.AsString() ?? r.Name ?? "Room";
            if (el is ViewSheet vs)
                return vs.Name;
            if (el is Viewport vp)
                return doc.GetElement(vp.ViewId)?.Name ?? "Viewport";
            if (el is FamilyInstance fi)
                return $"{fi.Symbol?.FamilyName} : {fi.Name}";
            return el.Name ?? el.Category?.Name ?? "Element";
        }

        private static string GetElementHostRoomNumber(Element el, XYZ pt, List<Room> allRooms)
        {
            if (el is Room rm) return rm.Number ?? "";
            if (el is FamilyInstance fi)
            {
                try
                {
                    if (fi.ToRoom != null && !string.IsNullOrWhiteSpace(fi.ToRoom.Number))
                        return fi.ToRoom.Number;
                    if (fi.FromRoom != null && !string.IsNullOrWhiteSpace(fi.FromRoom.Number))
                        return fi.FromRoom.Number;
                    if (fi.Room != null && !string.IsNullOrWhiteSpace(fi.Room.Number))
                        return fi.Room.Number;
                }
                catch { }
            }

            foreach (Room r in allRooms)
            {
                try
                {
                    if (r.IsPointInRoom(pt)) return r.Number ?? "";
                }
                catch { }
            }
            return "";
        }

        private static string GetElementNumberValue(Element el, int catIdx)
        {
            if (el is Room r) return r.Number ?? "";
            if (el is Autodesk.Revit.DB.Grid g) return g.Name ?? "";
            if (el is ViewSheet vs) return vs.SheetNumber ?? "";
            if (el is Viewport vp)
                return vp.get_Parameter(BuiltInParameter.VIEWPORT_DETAIL_NUMBER)?.AsString() ?? "";
            return el.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString() ?? "";
        }

        private static bool SetElementNumberValue(Element el, int catIdx, string val)
        {
            try
            {
                if (el is Room r) { r.Number = val; return true; }
                if (el is Autodesk.Revit.DB.Grid g) { g.Name = val; return true; }
                if (el is ViewSheet vs) { vs.SheetNumber = val; return true; }
                if (el is Viewport vp)
                {
                    Parameter p = vp.get_Parameter(BuiltInParameter.VIEWPORT_DETAIL_NUMBER);
                    if (p != null && !p.IsReadOnly) { p.Set(val); return true; }
                    return false;
                }
                Parameter markParam = el.get_Parameter(BuiltInParameter.ALL_MODEL_MARK);
                if (markParam != null && !markParam.IsReadOnly)
                {
                    markParam.Set(val);
                    return true;
                }
            }
            catch { }
            return false;
        }
    }

    public partial class GoatRenumberWindow : Window
    {
        private readonly GoatRenumberEventHandler _handler;
        private readonly ExternalEvent _extEvent;
        private bool _isLoaded = false;

        public ObservableCollection<RenumberRowItem> Rows { get; } = new ObservableCollection<RenumberRowItem>();

        public GoatRenumberWindow(GoatRenumberEventHandler handler, ExternalEvent extEvent)
        {
            InitializeComponent();
            _handler = handler;
            _extEvent = extEvent;
            _handler.Window = this;

            DgPreview.ItemsSource = Rows;

            Loaded += (s, e) =>
            {
                _isLoaded = true;
                TriggerScan();
            };
        }

        public void LoadScannedRows(List<RenumberRowItem> scanned)
        {
            Rows.Clear();
            foreach (var r in scanned) Rows.Add(r);
            RecalculateProposedNumbers();
        }

        private void TriggerScan()
        {
            if (!_isLoaded) return;
            _handler.IsScanOnly = true;
            _extEvent.Raise();
        }

        private void RecalculateProposedNumbers()
        {
            if (Rows.Count == 0) return;

            string prefix = TxtPrefix.Text ?? "";
            string suffix = TxtSuffix.Text ?? "";
            int.TryParse(TxtStartNum.Text, out int startNum);
            if (startNum <= 0) startNum = 1;
            int.TryParse(TxtStep.Text, out int step);
            if (step == 0) step = 1;
            int.TryParse(TxtPadding.Text, out int pad);
            pad = Math.Clamp(pad, 1, 8);

            bool byRoom = RbModeByHostRoom.IsChecked == true;
            bool alphaRoomSuffix = CbRoomSuffixStyle.SelectedIndex == 0;

            // Sort rows according to chosen spatial scan
            List<RenumberRowItem> sorted;
            if (RbModeSpatialYX.IsChecked == true)
            {
                sorted = Rows.OrderByDescending(r => Math.Round(r.Y / 2.0)).ThenBy(r => r.X).ToList();
            }
            else
            {
                sorted = Rows.OrderBy(r => Math.Round(r.Y / 2.0)).ThenBy(r => r.X).ToList();
            }

            Rows.Clear();
            foreach (var item in sorted) Rows.Add(item);

            if (byRoom)
            {
                var groups = Rows.Where(r => r.IsSelected).GroupBy(r => string.IsNullOrWhiteSpace(r.HostRoomNumber) ? "UNASSIGNED" : r.HostRoomNumber);
                foreach (var grp in groups)
                {
                    var items = grp.ToList();
                    for (int i = 0; i < items.Count; i++)
                    {
                        string roomNum = grp.Key;
                        if (items.Count == 1)
                        {
                            items[i].ProposedNumber = $"{prefix}{roomNum}{suffix}";
                        }
                        else
                        {
                            string multiTag = alphaRoomSuffix
                                ? ((char)('A' + (i % 26))).ToString()
                                : $"-{i + 1}";
                            items[i].ProposedNumber = $"{prefix}{roomNum}{multiTag}{suffix}";
                        }
                    }
                }
            }
            else
            {
                int current = startNum;
                foreach (var item in Rows)
                {
                    if (!item.IsSelected)
                    {
                        item.ProposedNumber = "";
                        continue;
                    }
                    item.ProposedNumber = $"{prefix}{current.ToString().PadLeft(pad, '0')}{suffix}";
                    current += step;
                }
            }

            if (BtnApply != null)
            {
                BtnApply.Content = RbModeInteractivePick.IsChecked == true
                    ? "🎯 Start Interactive Pick in Revit"
                    : "🚀 Apply Renumbering";
            }
        }

        private void Config_Changed(object sender, SelectionChangedEventArgs e) => TriggerScan();
        private void Scope_Changed(object sender, RoutedEventArgs e) => TriggerScan();
        private void Rule_Changed(object sender, RoutedEventArgs e)
        {
            if (!_isLoaded) return;
            RecalculateProposedNumbers();
        }
        private void Format_Changed(object sender, TextChangedEventArgs e)
        {
            if (!_isLoaded) return;
            RecalculateProposedNumbers();
        }
        private void BtnRescan_Click(object sender, RoutedEventArgs e) => TriggerScan();

        private void BtnApply_Click(object sender, RoutedEventArgs e)
        {
            _handler.IsScanOnly = false;
            _extEvent.Raise();
        }

        private void BtnClose_Click(object sender, RoutedEventArgs e) => Close();
    }
}

using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Diagnostics;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using Microsoft.Win32;
using ORTools.Models;

namespace ORTools.UI
{
    public class BoqRowItem
    {
        public bool IsSelected { get; set; } = true;
        public string ItemCode { get; set; } = string.Empty;
        public string CategoryName { get; set; } = string.Empty;
        public string TypeDescription { get; set; } = string.Empty;
        public string LevelName { get; set; } = "All Levels";
        public int Count { get; set; }
        public double TotalLengthM { get; set; }
        public double TotalAreaSqm { get; set; }
        public double TotalVolumeCum { get; set; }
        public string PrimaryUnit { get; set; } = "m²";
        public double PrimaryQuantity { get; set; }
    }

    public class GoatBoqEventHandler : IExternalEventHandler
    {
        public GoatBoqWindow Window { get; set; }

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc?.Document == null) return;
            Document doc = uidoc.Document;

            try
            {
                bool activeOnly = Window.RbActiveView.IsChecked == true;
                bool byLevel = Window.ChkGroupByLevel.IsChecked == true;

                var targetCategories = new List<BuiltInCategory>
                {
                    BuiltInCategory.OST_Walls,
                    BuiltInCategory.OST_Floors,
                    BuiltInCategory.OST_Ceilings,
                    BuiltInCategory.OST_Roofs,
                    BuiltInCategory.OST_Doors,
                    BuiltInCategory.OST_Windows,
                    BuiltInCategory.OST_StructuralColumns,
                    BuiltInCategory.OST_StructuralFraming,
                    BuiltInCategory.OST_Columns,
                    BuiltInCategory.OST_Furniture,
                    BuiltInCategory.OST_Casework,
                    BuiltInCategory.OST_PlumbingFixtures,
                    BuiltInCategory.OST_LightingFixtures
                };

                FilteredElementCollector col = (activeOnly && doc.ActiveView != null)
                    ? new FilteredElementCollector(doc, doc.ActiveView.Id)
                    : new FilteredElementCollector(doc);

                var multiFilter = new LogicalOrFilter(targetCategories.Select(c => (ElementFilter)new ElementCategoryFilter(c)).ToList());
                var elements = col.WhereElementIsNotElementType().WherePasses(multiFilter).ToList();

                var rawItems = new List<(string Cat, string TypeName, string Lvl, double LenM, double AreaSqm, double VolCum)>();

                foreach (Element el in elements)
                {
                    if (el.Category == null) continue;
                    string cat = el.Category.Name;
                    string typeName = GetFamilyAndTypeName(doc, el);
                    string lvlName = byLevel ? GetLevelName(doc, el) : "All Levels";

                    double lenM = GetMetricParam(el, BuiltInParameter.CURVE_ELEM_LENGTH, UnitTypeId.Meters);
                    double areaSqm = GetMetricParam(el, BuiltInParameter.HOST_AREA_COMPUTED, UnitTypeId.SquareMeters);
                    double volCum = GetMetricParam(el, BuiltInParameter.HOST_VOLUME_COMPUTED, UnitTypeId.CubicMeters);

                    rawItems.Add((cat, typeName, lvlName, lenM, areaSqm, volCum));
                }

                var grouped = rawItems
                    .GroupBy(x => (x.Cat, x.TypeName, x.Lvl))
                    .OrderBy(g => g.Key.Cat)
                    .ThenBy(g => g.Key.TypeName)
                    .ThenBy(g => g.Key.Lvl)
                    .ToList();

                var rows = new List<BoqRowItem>();
                int index = 1;
                foreach (var g in grouped)
                {
                    int cnt = g.Count();
                    double sumLen = Math.Round(g.Sum(x => x.LenM), 2);
                    double sumArea = Math.Round(g.Sum(x => x.AreaSqm), 2);
                    double sumVol = Math.Round(g.Sum(x => x.VolCum), 2);

                    string unit = "No.";
                    double primaryQty = cnt;
                    if (sumArea > 0.01) { unit = "m²"; primaryQty = sumArea; }
                    else if (sumVol > 0.01) { unit = "m³"; primaryQty = sumVol; }
                    else if (sumLen > 0.01) { unit = "m.l"; primaryQty = sumLen; }

                    rows.Add(new BoqRowItem
                    {
                        IsSelected = true,
                        ItemCode = $"BOQ-{index:000}",
                        CategoryName = g.Key.Cat,
                        TypeDescription = g.Key.TypeName,
                        LevelName = g.Key.Lvl,
                        Count = cnt,
                        TotalLengthM = sumLen,
                        TotalAreaSqm = sumArea,
                        TotalVolumeCum = sumVol,
                        PrimaryUnit = unit,
                        PrimaryQuantity = primaryQty
                    });
                    index++;
                }

                Window.ApplyScannedBoq(rows, elements.Count);
            }
            catch (Exception ex)
            {
                Window.TxtStatus.Text = $"Error: {ex.Message}";
            }
        }

        public string GetName() => "GOAT BOQ External Event Handler";

        private static string GetFamilyAndTypeName(Document doc, Element el)
        {
            ElementId tid = el.GetTypeId();
            if (tid != ElementId.InvalidElementId && doc.GetElement(tid) is ElementType et)
            {
                return !string.IsNullOrWhiteSpace(et.FamilyName)
                    ? $"{et.FamilyName} : {et.Name}"
                    : et.Name;
            }
            return el.Name ?? "Unnamed";
        }

        private static string GetLevelName(Document doc, Element el)
        {
            if (el.LevelId != ElementId.InvalidElementId && doc.GetElement(el.LevelId) is Level l)
                return l.Name;
            Parameter p = el.get_Parameter(BuiltInParameter.FAMILY_LEVEL_PARAM)
                       ?? el.get_Parameter(BuiltInParameter.WALL_BASE_CONSTRAINT)
                       ?? el.get_Parameter(BuiltInParameter.INSTANCE_REFERENCE_LEVEL_PARAM);
            if (p != null && p.AsElementId() != ElementId.InvalidElementId && doc.GetElement(p.AsElementId()) is Level l2)
                return l2.Name;
            return "Unassigned";
        }

        private static double GetMetricParam(Element el, BuiltInParameter bip, ForgeTypeId unitId)
        {
            try
            {
                Parameter p = el.get_Parameter(bip);
                if (p != null && p.StorageType == StorageType.Double && p.AsDouble() > 0)
                {
                    return UnitUtils.ConvertFromInternalUnits(p.AsDouble(), unitId);
                }
            }
            catch { }
            return 0.0;
        }
    }

    public partial class GoatBoqWindow : Window
    {
        private readonly GoatBoqEventHandler _handler;
        private readonly ExternalEvent _extEvent;
        private List<BoqRowItem> _allRows = new List<BoqRowItem>();
        public ObservableCollection<BoqRowItem> DisplayedRows { get; } = new ObservableCollection<BoqRowItem>();
        private bool _isLoaded = false;

        public GoatBoqWindow(GoatBoqEventHandler handler, ExternalEvent extEvent)
        {
            InitializeComponent();
            _handler = handler;
            _extEvent = extEvent;
            _handler.Window = this;

            DgBoq.ItemsSource = DisplayedRows;

            Loaded += (s, e) =>
            {
                _isLoaded = true;
                _extEvent.Raise();
            };
        }

        public void ApplyScannedBoq(List<BoqRowItem> rows, int totalElements)
        {
            _allRows = rows ?? new List<BoqRowItem>();
            ApplyFilter();
            TxtStatus.Text = $"✔ Computed QTO for {totalElements} model elements grouped into {_allRows.Count} BOQ line items.";
        }

        private void ApplyFilter()
        {
            string q = TxtFilter?.Text?.Trim() ?? "";
            DisplayedRows.Clear();
            foreach (var r in _allRows)
            {
                if (string.IsNullOrEmpty(q) ||
                    r.CategoryName.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                    r.TypeDescription.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                    r.LevelName.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                    r.ItemCode.Contains(q, StringComparison.OrdinalIgnoreCase))
                {
                    DisplayedRows.Add(r);
                }
            }
        }

        private void Scope_Changed(object sender, RoutedEventArgs e)
        {
            if (!_isLoaded) return;
            _extEvent.Raise();
        }

        private void BtnRescan_Click(object sender, RoutedEventArgs e) => _extEvent.Raise();
        private void TxtFilter_TextChanged(object sender, TextChangedEventArgs e) => ApplyFilter();
        private void BtnClose_Click(object sender, RoutedEventArgs e) => Close();

        private void BtnExportXlsx_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var selected = DisplayedRows.Where(r => r.IsSelected).ToList();
                if (selected.Count == 0)
                {
                    MessageBox.Show("No BOQ items selected for export.", "GOAT BOQ", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                SaveFileDialog sfd = new SaveFileDialog
                {
                    Title = "Export GOAT BOQ Bill of Quantities (.xlsx)",
                    Filter = "Excel Workbook (*.xlsx)|*.xlsx",
                    FileName = $"GOAT_Model_BOQ_{DateTime.Now:yyyyMMdd_HHmm}.xlsx"
                };

                if (sfd.ShowDialog() != true) return;

                var sheet = new GoatExcelSheet
                {
                    Name = "Model BOQ Schedule",
                    ColumnWidths = new List<double> { 14, 18, 36, 16, 12, 14, 15, 14, 12, 16 }
                };

                sheet.Rows.Add(new List<GoatExcelCell>
                {
                    new GoatExcelCell("BOQ Code", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Category", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Family & Type Description", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Level", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Count (pcs)", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Length (m)", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Net Area (m²)", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Volume (m³)", GoatCellStyle.HeaderNavy),
                    new GoatExcelCell("Primary Unit", GoatCellStyle.HeaderTeal),
                    new GoatExcelCell("Primary Quantity", GoatCellStyle.HeaderTeal)
                });

                foreach (var r in selected)
                {
                    sheet.Rows.Add(new List<GoatExcelCell>
                    {
                        new GoatExcelCell(r.ItemCode, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(r.CategoryName, GoatCellStyle.ReadOnlyGrey),
                        new GoatExcelCell(r.TypeDescription, GoatCellStyle.NormalEditable),
                        new GoatExcelCell(r.LevelName, GoatCellStyle.ReadOnlyGrey),
                        new GoatExcelCell(r.Count.ToString(CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(r.TotalLengthM.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(r.TotalAreaSqm.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(r.TotalVolumeCum.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.ReadOnlyGrey, true),
                        new GoatExcelCell(r.PrimaryUnit, GoatCellStyle.SummaryBold),
                        new GoatExcelCell(r.PrimaryQuantity.ToString("0.00", CultureInfo.InvariantCulture), GoatCellStyle.SummaryBold, true)
                    });
                }

                GoatExcelEngine.WriteXlsx(sfd.FileName, new List<GoatExcelSheet> { sheet });
                TxtStatus.Text = $"✔ Exported {selected.Count} BOQ items to {System.IO.Path.GetFileName(sfd.FileName)}";

                try
                {
                    Process.Start(new ProcessStartInfo { FileName = sfd.FileName, UseShellExecute = true });
                }
                catch { }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"BOQ Export Error:\n{ex.Message}", "GOAT BOQ", MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Windows;
using Autodesk.Revit.DB;
using Autodesk.Revit.UI;
using ORTools.Models;

namespace ORTools.UI
{
    public enum GoatAlignerMode
    {
        Scan,
        AutoPackSheets,
        MatchPositionAcrossSheets,
        DuplicateSheetsWithViews
    }

    public class AlignSheetItem
    {
        public bool IsSelected { get; set; }
        public ElementId SheetId { get; set; } = ElementId.InvalidElementId;
        public string SheetNumber { get; set; } = string.Empty;
        public string SheetName { get; set; } = string.Empty;
    }

    public class ReferencePlacedItem
    {
        public ElementId PlacedElementId { get; set; } = ElementId.InvalidElementId;
        public ElementId UnderlyingViewOrSchedId { get; set; } = ElementId.InvalidElementId;
        public string DisplayTitle { get; set; } = string.Empty;
        public XYZ CenterPoint { get; set; } = XYZ.Zero;
        public bool IsScheduleInstance { get; set; }
        public bool IsLegendViewport { get; set; }
        public override string ToString() => DisplayTitle;
    }

    public class GoatAlignerEventHandler : IExternalEventHandler
    {
        public GoatAlignerWindow Window { get; set; }
        public GoatAlignerMode Mode { get; set; } = GoatAlignerMode.Scan;

        public void Execute(UIApplication uiapp)
        {
            if (Window == null) return;
            UIDocument uidoc = uiapp.ActiveUIDocument;
            if (uidoc?.Document == null) return;
            Document doc = uidoc.Document;

            try
            {
                switch (Mode)
                {
                    case GoatAlignerMode.Scan:
                        ExecuteScan(doc);
                        break;
                    case GoatAlignerMode.AutoPackSheets:
                        ExecuteAutoPack(doc);
                        break;
                    case GoatAlignerMode.MatchPositionAcrossSheets:
                        ExecuteMatchPosition(doc);
                        break;
                    case GoatAlignerMode.DuplicateSheetsWithViews:
                        ExecuteDuplicateSheets(doc);
                        break;
                }
            }
            catch (Exception ex)
            {
                Window.TxtStatus.Text = $"Error: {ex.Message}";
            }
        }

        public string GetName() => "GOAT ALIGNER External Event Handler";

        private void ExecuteScan(Document doc)
        {
            ElementId activeSheetId = (doc.ActiveView is ViewSheet avs) ? avs.Id : ElementId.InvalidElementId;

            var sheets = new FilteredElementCollector(doc)
                .OfClass(typeof(ViewSheet))
                .Cast<ViewSheet>()
                .Where(s => !s.IsPlaceholder)
                .OrderBy(s => s.SheetNumber)
                .Select(s => new AlignSheetItem
                {
                    IsSelected = s.Id == activeSheetId,
                    SheetId = s.Id,
                    SheetNumber = s.SheetNumber,
                    SheetName = s.Name
                })
                .ToList();

            if (sheets.Count > 0 && !sheets.Any(s => s.IsSelected))
                sheets[0].IsSelected = true;

            var refItems = new List<ReferencePlacedItem>();
            foreach (ViewSheet s in new FilteredElementCollector(doc).OfClass(typeof(ViewSheet)).Cast<ViewSheet>().Where(x => !x.IsPlaceholder).OrderBy(x => x.SheetNumber))
            {
                foreach (ElementId vpId in s.GetAllViewports())
                {
                    if (doc.GetElement(vpId) is Viewport vp && doc.GetElement(vp.ViewId) is View v)
                    {
                        refItems.Add(new ReferencePlacedItem
                        {
                            PlacedElementId = vp.Id,
                            UnderlyingViewOrSchedId = v.Id,
                            DisplayTitle = $"[{s.SheetNumber}] Viewport: {v.Name}",
                            CenterPoint = vp.GetBoxCenter(),
                            IsLegendViewport = v.ViewType == ViewType.Legend
                        });
                    }
                }

                var schedulesOnSheet = new FilteredElementCollector(doc, s.Id)
                    .OfClass(typeof(ScheduleSheetInstance))
                    .Cast<ScheduleSheetInstance>()
                    .Where(si => !si.IsTitleblockRevisionSchedule);

                foreach (ScheduleSheetInstance ssi in schedulesOnSheet)
                {
                    refItems.Add(new ReferencePlacedItem
                    {
                        PlacedElementId = ssi.Id,
                        UnderlyingViewOrSchedId = ssi.ScheduleId,
                        DisplayTitle = $"[{s.SheetNumber}] Schedule: {ssi.Name}",
                        CenterPoint = ssi.Point,
                        IsScheduleInstance = true
                    });
                }
            }

            Window.ApplyScannedData(sheets, refItems);
        }

        private void ExecuteAutoPack(Document doc)
        {
            var selectedSheets = Window.SheetList.Where(s => s.IsSelected).ToList();
            if (selectedSheets.Count == 0 && doc.ActiveView is ViewSheet activeSheet)
            {
                selectedSheets.Add(new AlignSheetItem { SheetId = activeSheet.Id });
            }

            if (selectedSheets.Count == 0)
            {
                Window.TxtStatus.Text = "Please select at least one sheet on the left.";
                return;
            }

            int packedViewports = 0;
            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ALIGNER — Auto-Pack Sheets"))
            {
                tg.Start();
                using (Transaction trans = new Transaction(doc, "Auto-Pack Sheet Viewports"))
                {
                    trans.Start();
                    foreach (var item in selectedSheets)
                    {
                        if (doc.GetElement(item.SheetId) is ViewSheet vs)
                        {
                            packedViewports += GoatDocEngines.PackViewsOntoSheet(doc, vs, null, packExistingViewportsOnly: true);
                        }
                    }
                    trans.Commit();
                }
                tg.Assimilate();
            }

            Window.TxtStatus.Text = $"✔ Auto-packed {packedViewports} viewports across {selectedSheets.Count} sheet(s). (1x Ctrl+Z to Undo)";
        }

        private void ExecuteMatchPosition(Document doc)
        {
            var refItem = Window.CbReferenceViewports.SelectedItem as ReferencePlacedItem;
            if (refItem == null)
            {
                Window.TxtStatus.Text = "Please select a Reference Viewport or Schedule first.";
                return;
            }

            var targetSheets = Window.SheetList.Where(s => s.IsSelected).ToList();
            int alignedCount = 0;

            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ALIGNER — Match Position Across Sheets"))
            {
                tg.Start();
                using (Transaction trans = new Transaction(doc, "Match Viewport & Schedule Coordinates"))
                {
                    trans.Start();

                    foreach (var item in targetSheets)
                    {
                        if (!(doc.GetElement(item.SheetId) is ViewSheet sheet)) continue;

                        if (refItem.IsScheduleInstance)
                        {
                            // Place or move ScheduleSheetInstance on target sheet
                            var existing = new FilteredElementCollector(doc, sheet.Id)
                                .OfClass(typeof(ScheduleSheetInstance))
                                .Cast<ScheduleSheetInstance>()
                                .FirstOrDefault(x => x.ScheduleId == refItem.UnderlyingViewOrSchedId);

                            if (existing != null)
                            {
                                existing.Point = refItem.CenterPoint;
                                alignedCount++;
                            }
                            else
                            {
                                try
                                {
                                    ScheduleSheetInstance.Create(doc, sheet.Id, refItem.UnderlyingViewOrSchedId, refItem.CenterPoint);
                                    alignedCount++;
                                }
                                catch { }
                            }
                        }
                        else if (refItem.IsLegendViewport)
                        {
                            // Place or move Legend Viewport on target sheet
                            Viewport existingLegendVp = sheet.GetAllViewports()
                                .Select(id => doc.GetElement(id) as Viewport)
                                .FirstOrDefault(vp => vp != null && vp.ViewId == refItem.UnderlyingViewOrSchedId);

                            if (existingLegendVp != null)
                            {
                                existingLegendVp.SetBoxCenter(refItem.CenterPoint);
                                alignedCount++;
                            }
                            else if (Viewport.CanAddViewToSheet(doc, sheet.Id, refItem.UnderlyingViewOrSchedId))
                            {
                                try
                                {
                                    Viewport.Create(doc, sheet.Id, refItem.UnderlyingViewOrSchedId, refItem.CenterPoint);
                                    alignedCount++;
                                }
                                catch { }
                            }
                        }
                        else
                        {
                            // Align the primary model viewport on target sheet to the exact Reference CenterPoint
                            Viewport primaryVp = sheet.GetAllViewports()
                                .Select(id => doc.GetElement(id) as Viewport)
                                .FirstOrDefault(vp => vp != null && vp.Id != refItem.PlacedElementId);

                            if (primaryVp != null)
                            {
                                primaryVp.SetBoxCenter(refItem.CenterPoint);
                                alignedCount++;
                            }
                        }
                    }

                    trans.Commit();
                }
                tg.Assimilate();
            }

            Window.TxtStatus.Text = $"✔ Matched exact coordinates across {alignedCount} target sheet(s). (1x Ctrl+Z to Undo)";
        }

        private void ExecuteDuplicateSheets(Document doc)
        {
            var selectedSheets = Window.SheetList.Where(s => s.IsSelected).ToList();
            if (selectedSheets.Count == 0)
            {
                Window.TxtStatus.Text = "Please select at least one sheet to duplicate.";
                return;
            }

            ViewDuplicateOption dupOpt = Window.RbDupWithDetailing.IsChecked == true
                ? ViewDuplicateOption.WithDetailing
                : (Window.RbDupAsDependent.IsChecked == true ? ViewDuplicateOption.AsDependent : ViewDuplicateOption.Duplicate);

            string suffix = string.IsNullOrWhiteSpace(Window.TxtDupSuffix.Text) ? "-COPY" : Window.TxtDupSuffix.Text.Trim();
            int clonedSheets = 0;

            using (TransactionGroup tg = new TransactionGroup(doc, "GOAT ALIGNER — Duplicate Sheets with Views"))
            {
                tg.Start();
                using (Transaction trans = new Transaction(doc, "Clone Sheets, Viewports & Schedules"))
                {
                    trans.Start();

                    foreach (var sItem in selectedSheets)
                    {
                        if (!(doc.GetElement(sItem.SheetId) is ViewSheet srcSheet)) continue;

                        // Find TitleBlock type on source sheet
                        ElementId tbTypeId = ElementId.InvalidElementId;
                        var tbInst = new FilteredElementCollector(doc, srcSheet.Id)
                            .OfCategory(BuiltInCategory.OST_TitleBlocks)
                            .WhereElementIsNotElementType()
                            .FirstOrDefault();
                        if (tbInst != null) tbTypeId = tbInst.GetTypeId();

                        ViewSheet newSheet = ViewSheet.Create(doc, tbTypeId);
                        if (newSheet == null) continue;

                        newSheet.Name = srcSheet.Name;
                        for (int i = 1; i < 100; i++)
                        {
                            string candidate = i == 1 ? $"{srcSheet.SheetNumber}{suffix}" : $"{srcSheet.SheetNumber}{suffix}{i}";
                            try { newSheet.SheetNumber = candidate; break; } catch { }
                        }

                        // Copy Viewports
                        foreach (ElementId vpId in srcSheet.GetAllViewports())
                        {
                            if (!(doc.GetElement(vpId) is Viewport srcVp)) continue;
                            if (!(doc.GetElement(srcVp.ViewId) is View srcView)) continue;

                            XYZ center = srcVp.GetBoxCenter();
                            ElementId targetViewId = srcView.Id;

                            if (srcView.ViewType != ViewType.Legend && srcView.CanViewBeDuplicated(dupOpt))
                            {
                                try
                                {
                                    targetViewId = srcView.Duplicate(dupOpt);
                                }
                                catch { continue; }
                            }

                            if (Viewport.CanAddViewToSheet(doc, newSheet.Id, targetViewId))
                            {
                                try
                                {
                                    Viewport newVp = Viewport.Create(doc, newSheet.Id, targetViewId, center);
                                    if (newVp != null && srcVp.GetTypeId() != ElementId.InvalidElementId)
                                        newVp.ChangeTypeId(srcVp.GetTypeId());
                                }
                                catch { }
                            }
                        }

                        // Copy Schedules
                        var schedules = new FilteredElementCollector(doc, srcSheet.Id)
                            .OfClass(typeof(ScheduleSheetInstance))
                            .Cast<ScheduleSheetInstance>()
                            .Where(si => !si.IsTitleblockRevisionSchedule)
                            .ToList();

                        foreach (ScheduleSheetInstance ssi in schedules)
                        {
                            try
                            {
                                ScheduleSheetInstance.Create(doc, newSheet.Id, ssi.ScheduleId, ssi.Point);
                            }
                            catch { }
                        }

                        clonedSheets++;
                    }

                    trans.Commit();
                }
                tg.Assimilate();
            }

            ExecuteScan(doc);
            Window.TxtStatus.Text = $"✔ Successfully duplicated {clonedSheets} sheet(s) with all views, legends & schedules! (1x Ctrl+Z to Undo)";
        }
    }

    public partial class GoatAlignerWindow : Window
    {
        private readonly GoatAlignerEventHandler _handler;
        private readonly ExternalEvent _extEvent;

        public ObservableCollection<AlignSheetItem> SheetList { get; } = new ObservableCollection<AlignSheetItem>();

        public GoatAlignerWindow(GoatAlignerEventHandler handler, ExternalEvent extEvent)
        {
            InitializeComponent();
            _handler = handler;
            _extEvent = extEvent;
            _handler.Window = this;

            DgSheets.ItemsSource = SheetList;

            Loaded += (s, e) =>
            {
                _handler.Mode = GoatAlignerMode.Scan;
                _extEvent.Raise();
            };
        }

        public void ApplyScannedData(List<AlignSheetItem> sheets, List<ReferencePlacedItem> refs)
        {
            SheetList.Clear();
            foreach (var s in sheets) SheetList.Add(s);

            CbReferenceViewports.ItemsSource = refs;
            if (refs.Count > 0) CbReferenceViewports.SelectedIndex = 0;
        }

        private void BtnRefresh_Click(object sender, RoutedEventArgs e)
        {
            _handler.Mode = GoatAlignerMode.Scan;
            _extEvent.Raise();
        }

        private void BtnSelectAll_Click(object sender, RoutedEventArgs e)
        {
            foreach (var s in SheetList) s.IsSelected = true;
            DgSheets.Items.Refresh();
        }

        private void BtnSelectNone_Click(object sender, RoutedEventArgs e)
        {
            foreach (var s in SheetList) s.IsSelected = false;
            DgSheets.Items.Refresh();
        }

        private void BtnAutoPack_Click(object sender, RoutedEventArgs e)
        {
            _handler.Mode = GoatAlignerMode.AutoPackSheets;
