        private void BtnDuplicateSheets_Click(object sender, RoutedEventArgs e)
        {
            _handler.Mode = GoatAlignerMode.DuplicateSheetsWithViews;
            _extEvent.Raise();
        }

        private void BtnClose_Click(object sender, RoutedEventArgs e) => Close();
    }
