74:         private void ExecuteHarvest(Document doc)
75:         {
76:             ViewModel.ProgressValue = 0;
77:             ViewModel.StatusMessage = "Scanning model elements and harvesting parameters...";
78: 
79:             FilteredElementCollector collector = ViewModel.IsActiveViewScope && doc.ActiveView != null
80:                 ? new FilteredElementCollector(doc, doc.ActiveView.Id)
81:                 : new FilteredElementCollector(doc);
82: 
83:             var elements = collector
84:                 .WhereElementIsNotElementType()
85:                 .Where(e => e.Category != null && e.Parameters != null && e.Parameters.Size > 0)
86:                 .ToList();
87: 
88:             var paramDict = new Dictionary<string, OrParameterItemModel>(StringComparer.OrdinalIgnoreCase);
89:             var visitedTypesPerParam = new Dictionary<string, HashSet<ElementId>>(StringComparer.OrdinalIgnoreCase);
90: 
91:             int total = elements.Count;
92:             int processed = 0;
93: 
94:             foreach (Element el in elements)
95:             {
96:                 processed++;
97:                 // 1. Harvest Instance Parameters
98:                 foreach (Parameter p in el.Parameters)
99:                 {
100:                     if (p?.Definition == null || string.IsNullOrWhiteSpace(p.Definition.Name)) continue;
101:                     if (p.IsReadOnly) continue;
102:                     if (p.StorageType == StorageType.None) continue;
103: 
104:                     string pName = p.Definition.Name.Trim();
105:                     string key = $"{pName}|Instance";
106: 
107:                     if (!paramDict.TryGetValue(key, out var item))
108:                     {
109:                         item = new OrParameterItemModel
110:                         {
111:                             Name = pName,
112:                             IsInstance = true,
113:                             DataStorageType = p.StorageType,
114:                             IsReadOnly = p.IsReadOnly
115:                         };
116:                         paramDict[key] = item;
117:                     }
118:                     item.OwnerElementIds.Add(el.Id);
119:                 }
120: 
121:                 // 2. Harvest Type Parameters
122:                 ElementId typeId = el.GetTypeId();
123:                 if (typeId != null && typeId != ElementId.InvalidElementId)
124:                 {
125:                     Element typeEl = doc.GetElement(typeId);
126:                     if (typeEl != null && typeEl.Parameters != null)
127:                     {
128:                         foreach (Parameter tp in typeEl.Parameters)
129:                         {
130:                             if (tp?.Definition == null || string.IsNullOrWhiteSpace(tp.Definition.Name)) continue;
131:                             if (tp.IsReadOnly) continue;
132:                             if (tp.StorageType == StorageType.None) continue;
133: 
134:                             string tpName = tp.Definition.Name.Trim();
135:                             string tKey = $"{tpName}|Type";
136: 
137:                             if (!paramDict.TryGetValue(tKey, out var tItem))
138:                             {
139:                                 tItem = new OrParameterItemModel
140:                                 {
141:                                     Name = tpName,
142:                                     IsInstance = false,
143:                                     DataStorageType = tp.StorageType,
144:                                     IsReadOnly = tp.IsReadOnly
145:                                 };
146:                                 paramDict[tKey] = tItem;
147:                                 visitedTypesPerParam[tKey] = new HashSet<ElementId>();
148:                             }
149: 
150:                             if (!tItem.TypeToInstanceIdsMap.TryGetValue(typeId, out var instList))
151:                             {
152:                                 instList = new List<ElementId>();
153:                                 tItem.TypeToInstanceIdsMap[typeId] = instList;
154:                             }
155:                             instList.Add(el.Id);
156: 
157:                             if (visitedTypesPerParam[tKey].Add(typeId))
158:                             {
159:                                 tItem.OwnerElementIds.Add(typeId);
160:                             }
161:                         }
162:                     }
163:                 }
164:             }
165: 
166:             var sortedList = paramDict.Values
167:                 .Select(x => { x.ElementCount = x.OwnerElementIds.Count; return x; })
168:                 .OrderBy(x => x.Name)
169:                 .ThenBy(x => x.IsInstance ? 0 : 1)
170:                 .ToList();
171: 
172:             ViewModel.UpdateHarvestedParameters(sortedList);
173:             ViewModel.ProgressValue = 100;
174:             ViewModel.StatusMessage = $"Harvested {sortedList.Count} editable parameters from {total} elements.";
175:         }
