177:         private List<ElementId> GetTargetElements(Document doc, OrParameterItemModel paramItem, out List<ElementId> selectableInstanceIds)
178:         {
179:             selectableInstanceIds = new List<ElementId>();
180:             var matchedTargetIds = new List<ElementId>();
181:             if (paramItem == null) return matchedTargetIds;
182: 
183:             string filterVal = ViewModel.ValueFilterText ?? string.Empty;
184:             bool hasFilter = !string.IsNullOrEmpty(filterVal);
185:             StringComparison cmp = ViewModel.IsCaseSensitive ? StringComparison.Ordinal : StringComparison.OrdinalIgnoreCase;
186: 
187:             foreach (ElementId id in paramItem.OwnerElementIds)
188:             {
189:                 Element el = doc.GetElement(id);
190:                 if (el == null) continue;
191:                 Parameter p = el.LookupParameter(paramItem.Name);
192:                 if (p == null) continue;
193: 
194:                 if (hasFilter)
195:                 {
196:                     string currentStr = GetParameterDisplayString(doc, p);
197:                     if (currentStr == null || currentStr.IndexOf(filterVal, cmp) < 0)
198:                         continue;
199:                 }
200: 
201:                 matchedTargetIds.Add(id);
202: 
203:                 if (paramItem.IsInstance)
204:                 {
205:                     selectableInstanceIds.Add(id);
206:                 }
207:                 else if (paramItem.TypeToInstanceIdsMap.TryGetValue(id, out var instIds))
208:                 {
209:                     selectableInstanceIds.AddRange(instIds);
210:                 }
211:             }
212: 
213:             return matchedTargetIds;
214:         }
