216:         private string GetParameterDisplayString(Document doc, Parameter p)
217:         {
218:             if (p == null) return string.Empty;
219:             switch (p.StorageType)
220:             {
221:                 case StorageType.String:
222:                     return p.AsString() ?? string.Empty;
223:                 case StorageType.Integer:
224:                     return p.AsValueString() ?? p.AsInteger().ToString(CultureInfo.InvariantCulture);
225:                 case StorageType.Double:
226:                     return p.AsValueString() ?? p.AsDouble().ToString("0.###", CultureInfo.InvariantCulture);
227:                 case StorageType.ElementId:
228:                     ElementId eid = p.AsElementId();
229:                     if (eid == null || eid == ElementId.InvalidElementId) return string.Empty;
230:                     Element refEl = doc.GetElement(eid);
231:                     return refEl != null ? refEl.Name : eid.Value.ToString(CultureInfo.InvariantCulture);
232:                 default:
233:                     return string.Empty;
234:             }
235:         }
