237:         private void ExecuteFilterByValue(Document doc, bool selectInRevit, UIDocument uidoc)
238:         {
239:             var selectedParam = ViewModel.SelectedParameter;
240:             if (selectedParam == null)
241:             {
242:                 ViewModel.StatusMessage = "Please select a parameter from the left list first.";
243:                 return;
244:             }
