246:             var matchedTargets = GetTargetElements(doc, selectedParam, out var selectableInstances);
247:             selectedParam.ElementCount = matchedTargets.Count;
248:             ViewModel.TotalItemsCount = selectableInstances.Count > 0 ? selectableInstances.Count : matchedTargets.Count;
249:             ViewModel.ProgressValue = 100;
