254:                 ViewModel.StatusMessage = $"Selected {selectableInstances.Count} matching elements in Revit.";
255:             }
256:             else
257:             {
258:                 ViewModel.StatusMessage = $"Found {matchedTargets.Count} matching items (Instances: {selectableInstances.Count}).";
259:             }
