262:         private void ExecuteApplyPrefixSuffix(Document doc)
263:         {
264:             var selectedParam = ViewModel.SelectedParameter;
265:             if (selectedParam == null) return;
266: 
267:             if (!selectedParam.IsStringParameter)
268:             {
269:                 TaskDialog.Show("OR PARAMETER", "Prefix & Suffix can only be applied to String (Text) parameters.");
270:                 return;
271:             }
272: 
273:             string prefix = ViewModel.PrefixText ?? string.Empty;
274:             string suffix = ViewModel.SuffixText ?? string.Empty;
275:             if (string.IsNullOrEmpty(prefix) && string.IsNullOrEmpty(suffix))
276:             {
277:                 ViewModel.StatusMessage = "Please enter a Prefix or Suffix to add.";
278:                 return;
279:             }
280: 
281:             var targets = GetTargetElements(doc, selectedParam, out _);
282:             if (targets.Count == 0)
283:             {
284:                 ViewModel.StatusMessage = "No matching elements found to update.";
285:                 return;
286:             }
287: 
288:             int updated = 0;
289:             int total = targets.Count;
290:             ViewModel.ProgressValue = 0;
291: 
292:             using (Transaction tx = new Transaction(doc, $"OR Parameter: Prefix/Suffix on {selectedParam.Name}"))
293:             {
294:                 tx.Start();
295:                 for (int i = 0; i < total; i++)
296:                 {
297:                     Element el = doc.GetElement(targets[i]);
298:                     Parameter p = el?.LookupParameter(selectedParam.Name);
299:                     if (p != null && !p.IsReadOnly && p.StorageType == StorageType.String)
300:                     {
301:                         string currentVal = p.AsString() ?? string.Empty;
302:                         string newVal = prefix + currentVal + suffix;
303:                         p.Set(newVal);
304:                         updated++;
305:                     }
306:                     ViewModel.ProgressValue = (double)(i + 1) / total * 100.0;
307:                 }
308:                 tx.Commit();
309:             }
310: 
311:             ViewModel.TotalItemsCount = updated;
312:             ViewModel.StatusMessage = $"Added Prefix/Suffix to {updated} items in a single transaction.";
313:         }
