353:         private bool TrySetParameterFromString(Parameter p, string input)
354:         {
355:             try
356:             {
357:                 switch (p.StorageType)
358:                 {
359:                     case StorageType.String:
360:                         return p.Set(input ?? string.Empty);
361: 
362:                     case StorageType.Integer:
363:                         if (int.TryParse(input.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int iVal))
364:                             return p.Set(iVal);
365:                         if (input.Trim().Equals("Yes", StringComparison.OrdinalIgnoreCase) || input.Trim().Equals("True", StringComparison.OrdinalIgnoreCase))
366:                             return p.Set(1);
367:                         if (input.Trim().Equals("No", StringComparison.OrdinalIgnoreCase) || input.Trim().Equals("False", StringComparison.OrdinalIgnoreCase))
368:                             return p.Set(0);
369:                         return false;
370: 
371:                     case StorageType.Double:
372:                         if (p.SetValueString(input)) return true;
373:                         if (double.TryParse(input.Trim(), NumberStyles.Any, CultureInfo.InvariantCulture, out double dVal))
374:                             return p.Set(dVal);
375:                         return false;
376: 
377:                     case StorageType.ElementId:
378:                         if (long.TryParse(input.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out long idVal))
379:                             return p.Set(new ElementId(idVal));
380:                         return false;
381: 
382:                     default:
383:                         return false;
384:                 }
385:             }
386:             catch
387:             {
388:                 return false;
