392:         private void ExecuteClearValues(Document doc)
393:         {
394:             var selectedParam = ViewModel.SelectedParameter;
395:             if (selectedParam == null) return;
396: 
397:             var targets = GetTargetElements(doc, selectedParam, out _);
398:             if (targets.Count == 0)
399:             {
400:                 ViewModel.StatusMessage = "No matching elements found to clear.";
401:                 return;
402:             }
403: 
404:             int cleared = 0;
405:             int total = targets.Count;
406:             ViewModel.ProgressValue = 0;
407: 
408:             using (Transaction tx = new Transaction(doc, $"OR Parameter: Clear {selectedParam.Name}"))
409:             {
410:                 tx.Start();
411:                 for (int i = 0; i < total; i++)
412:                 {
413:                     Element el = doc.GetElement(targets[i]);
414:                     Parameter p = el?.LookupParameter(selectedParam.Name);
415:                     if (p != null && !p.IsReadOnly)
416:                     {
417:                         try
418:                         {
419:                             switch (p.StorageType)
420:                             {
421:                                 case StorageType.String:
422:                                     if (p.Set(string.Empty)) cleared++;
423:                                     break;
424:                                 case StorageType.ElementId:
425:                                     if (p.Set(ElementId.InvalidElementId)) cleared++;
426:                                     break;
427:                                 case StorageType.Integer:
428:                                     if (p.Set(0)) cleared++;
429:                                     break;
430:                                 case StorageType.Double:
431:                                     if (p.Set(0.0)) cleared++;
432:                                     break;
433:                             }
434:                         }
435:                         catch { }
436:                     }
437:                     ViewModel.ProgressValue = (double)(i + 1) / total * 100.0;
438:                 }
439:                 tx.Commit();
440:             }
441: 
442:             ViewModel.TotalItemsCount = cleared;
443:             ViewModel.StatusMessage = $"Cleared values on {cleared} items in a single transaction.";
444:         }
