708:         private static List<string> ParseCsvLine(string line)
709:         {
710:             var result = new List<string>();
711:             if (line == null) return result;
712:             var cur = new StringBuilder();
713:             bool inQuotes = false;
714: 
715:             for (int i = 0; i < line.Length; i++)
716:             {
717:                 char ch = line[i];
718:                 if (inQuotes)
719:                 {
720:                     if (ch == '"')
721:                     {
722:                         if (i + 1 < line.Length && line[i + 1] == '"') { cur.Append('"'); i++; }
723:                         else inQuotes = false;
724:                     }
725:                     else cur.Append(ch);
726:                 }
727:                 else
728:                 {
729:                     if (ch == '"') inQuotes = true;
730:                     else if (ch == ',') { result.Add(cur.ToString()); cur.Clear(); }
731:                     else cur.Append(ch);
732:                 }
733:             }
734:             result.Add(cur.ToString());
735:             return result;
736:         }
