370:         public static string GetColumnName(int zeroBasedColumnIndex)
371:         {
372:             int dividend = zeroBasedColumnIndex + 1;
373:             string columnName = string.Empty;
374:             while (dividend > 0)
375:             {
376:                 int modulo = (dividend - 1) % 26;
377:                 columnName = Convert.ToChar(65 + modulo) + columnName;
378:                 dividend = (dividend - modulo) / 26;
379:             }
380:             return columnName;
381:         }
382: 
383:         private static int GetColumnIndexFromCellReference(string cellRef)
384:         {
385:             if (string.IsNullOrEmpty(cellRef)) return 0;
386:             int colIndex = 0;
387:             foreach (char ch in cellRef)
388:             {
389:                 if (char.IsLetter(ch))
390:                 {
391:                     colIndex = colIndex * 26 + (char.ToUpperInvariant(ch) - 'A' + 1);
392:                 }
393:                 else
394:                 {
395:                     break;
396:                 }
397:             }
398:             return Math.Max(0, colIndex - 1);
399:         }
400: 
401:         private static string SanitizeSheetName(string name, int index)
402:         {
403:             if (string.IsNullOrWhiteSpace(name)) return $"Sheet{index}";
404:             char[] invalid = { '\\', '/', '?', '*', ':', '[', ']' };
405:             foreach (char c in invalid)
406:             {
407:                 name = name.Replace(c, '_');
408:             }
409:             return name.Length > 31 ? name.Substring(0, 31) : name;
410:         }
411: 
412:         private static string EscapeXml(string input)
413:         {
414:             if (string.IsNullOrEmpty(input)) return string.Empty;
415:             return input
416:                 .Replace("&", "&amp;")
417:                 .Replace("<", "&lt;")
418:                 .Replace(">", "&gt;")
419:                 .Replace("\"", "&quot;")
420:                 .Replace("'", "&apos;");
421:         }
422:     }
