488:             };
489:             Canvas.SetLeft(sheetRect, pad);
490:             Canvas.SetTop(sheetRect, pad);
491:             CanvasSheetPreview.Children.Add(sheetRect);
492: 
493:             // Right Titleblock Strip
494:             double stripW = sheetW * 0.16;
495:             var stripRect = new System.Windows.Shapes.Rectangle
496:             {
497:                 Width = stripW,
498:                 Height = sheetH,
499:                 Fill = new SolidColorBrush(System.Windows.Media.Color.FromRgb(241, 245, 249)),
500:                 Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(203, 213, 225)),
501:                 StrokeThickness = 1.5
502:             };
503:             Canvas.SetLeft(stripRect, pad + sheetW - stripW);
504:             Canvas.SetTop(stripRect, pad);
505:             CanvasSheetPreview.Children.Add(stripRect);
506: 
507:             // Collect enabled views
508:             var labels = new List<(string Title, System.Windows.Media.Color Fill)>();
509:             if (ChkGenPlan?.IsChecked == true) labels.Add(("Enlarged Plan\n+ Dims & Tags", System.Windows.Media.Color.FromRgb(224, 242, 254)));
510:             if (ChkGenRcp?.IsChecked == true) labels.Add(("Ceiling Plan\n(RCP)", System.Windows.Media.Color.FromRgb(237, 233, 254)));
511:             if (ChkGen3DIso?.IsChecked == true) labels.Add(("3D Room\nSection Box", System.Windows.Media.Color.FromRgb(209, 250, 229)));
512:             if (ChkGenElevations?.IsChecked == true)
