522:             double drawW = sheetW - stripW - 16;
523:             double drawH = sheetH - 16;
524:             int cols = labels.Count <= 3 ? labels.Count : 3;
525:             int rows = (int)Math.Ceiling((double)labels.Count / cols);
526:             double cellW = drawW / cols;
527:             double cellH = drawH / rows;
