541:                     Height = bh,
542:                     Fill = new SolidColorBrush(labels[i].Fill),
543:                     Stroke = new SolidColorBrush(System.Windows.Media.Color.FromRgb(56, 189, 248)),
544:                     StrokeThickness = 1.5,
545:                     RadiusX = 3,
546:                     RadiusY = 3
547:                 };
