19:         public static int DimensionRoomInPlan(
20:             Document doc,
21:             View view,
22:             Room room,
23:             DimensionType dimType,
24:             bool dimClearCross,
25:             bool dimOpeningsChain,
26:             double stackOffsetMm)
27:         {
28:             if (doc == null || view == null || room == null || room.Area <= 0.001)
29:                 return 0;
30: 
31:             var boundaryOpts = new SpatialElementBoundaryOptions
32:             {
33:                 SpatialElementBoundaryLocation = SpatialElementBoundaryLocation.Finish
34:             };
35: 
36:             IList<IList<BoundarySegment>> loops = room.GetBoundarySegments(boundaryOpts);
37:             if (loops == null || loops.Count == 0 || loops[0].Count < 3)
38:                 return 0;
39: 
40:             BoundingBoxXYZ bb = room.get_BoundingBox(null);
41:             if (bb == null) return 0;
42:             XYZ center = (bb.Min + bb.Max) * 0.5;
43:             double z = view.GenLevel != null ? view.GenLevel.Elevation : bb.Min.Z;
44:             center = new XYZ(center.X, center.Y, z);
45: 
46:             var vertWallRefs = new ReferenceArray(); // Walls running North-South (measured along X)
47:             var horizWallRefs = new ReferenceArray(); // Walls running East-West (measured along Y)
48:             var vertWithOpeningsRefs = new ReferenceArray();
49:             var horizWithOpeningsRefs = new ReferenceArray();
50: 
51:             var seenHostIds = new HashSet<long>();
52: 
53:             foreach (BoundarySegment seg in loops[0])
54:             {
55:                 if (seg.ElementId == ElementId.InvalidElementId || seenHostIds.Contains(seg.ElementId.Value))
56:                     continue;
57: 
58:                 if (!(doc.GetElement(seg.ElementId) is Wall wall))
59:                     continue;
60: 
61:                 Curve c = seg.GetCurve();
62:                 if (c == null) continue;
63:                 XYZ dir = (c.GetEndPoint(1) - c.GetEndPoint(0)).Normalize();
64: 
65:                 Reference extFaceRef = GetWallFaceReference(wall, true) ?? GetWallFaceReference(wall, false);
66:                 if (extFaceRef == null) continue;
67: 
68:                 seenHostIds.Add(wall.Id.Value);
69: 
70:                 // Vertical wall (runs along Y, so its normal is along X -> measured by horizontal X dimension line)
71:                 if (Math.Abs(dir.Y) >= Math.Abs(dir.X))
72:                 {
73:                     vertWallRefs.Append(extFaceRef);
74:                     vertWithOpeningsRefs.Append(extFaceRef);
75:                 }
76:                 else
77:                 {
78:                     horizWallRefs.Append(extFaceRef);
79:                     horizWithOpeningsRefs.Append(extFaceRef);
80:                 }
81:             }
82: 
83:             int createdDims = 0;
84:             double offsetFeet = UnitUtils.ConvertToInternalUnits(Math.Max(150, stackOffsetMm), UnitTypeId.Millimeters);
85: 
86:             if (dimClearCross)
87:             {
88:                 if (vertWallRefs.Size >= 2)
89:                 {
90:                     try
91:                     {
92:                         Line xLine = Line.CreateBound(center - XYZ.BasisX * 50.0, center + XYZ.BasisX * 50.0);
93:                         Dimension d = doc.Create.NewDimension(view, xLine, vertWallRefs, dimType);
94:                         if (d != null) createdDims++;
95:                     }
96:                     catch { }
97:                 }
98: 
99:                 if (horizWallRefs.Size >= 2)
100:                 {
101:                     try
102:                     {
103:                         Line yLine = Line.CreateBound(center - XYZ.BasisY * 50.0, center + XYZ.BasisY * 50.0);
104:                         Dimension d = doc.Create.NewDimension(view, yLine, horizWallRefs, dimType);
105:                         if (d != null) createdDims++;
106:                     }
107:                     catch { }
108:                 }
109:             }
110: 
111:             if (dimOpeningsChain)
112:             {
113:                 // Append door & window center/side references hosted on room bounding walls
114:                 var inserts = new FilteredElementCollector(doc, view.Id)
115:                     .WhereElementIsNotElementType()
116:                     .OfType<FamilyInstance>()
117:                     .Where(fi => fi.Host != null && seenHostIds.Contains(fi.Host.Id.Value))
118:                     .ToList();
119: 
120:                 foreach (FamilyInstance fi in inserts)
121:                 {
122:                     if (!(fi.Host is Wall hostWall) || !(hostWall.Location is LocationCurve lc) || lc.Curve == null)
123:                         continue;
124: 
125:                     XYZ wDir = (lc.Curve.GetEndPoint(1) - lc.Curve.GetEndPoint(0)).Normalize();
126:                     IList<Reference> leftRight = fi.GetReferences(FamilyInstanceReferenceType.Left);
127:                     IList<Reference> rightRefs = fi.GetReferences(FamilyInstanceReferenceType.Right);
128:                     IList<Reference> centerRefs = fi.GetReferences(FamilyInstanceReferenceType.CenterLeftRight);
129: 
130:                     var refsToAdd = new List<Reference>();
131:                     if (leftRight != null && leftRight.Count > 0 && rightRefs != null && rightRefs.Count > 0)
132:                     {
133:                         refsToAdd.Add(leftRight[0]);
134:                         refsToAdd.Add(rightRefs[0]);
135:                     }
136:                     else if (centerRefs != null && centerRefs.Count > 0)
137:                     {
138:                         refsToAdd.Add(centerRefs[0]);
139:                     }
140: 
141:                     foreach (var r in refsToAdd)
142:                     {
143:                         if (Math.Abs(wDir.Y) >= Math.Abs(wDir.X))
144:                             horizWithOpeningsRefs.Append(r);
145:                         else
146:                             vertWithOpeningsRefs.Append(r);
147:                     }
148:                 }
149: 
150:                 if (vertWithOpeningsRefs.Size > vertWallRefs.Size && vertWithOpeningsRefs.Size >= 2)
151:                 {
152:                     try
153:                     {
154:                         XYZ shiftCenter = center + XYZ.BasisY * offsetFeet;
155:                         Line xLine = Line.CreateBound(shiftCenter - XYZ.BasisX * 50.0, shiftCenter + XYZ.BasisX * 50.0);
156:                         Dimension d = doc.Create.NewDimension(view, xLine, vertWithOpeningsRefs, dimType);
157:                         if (d != null) createdDims++;
158:                     }
159:                     catch { }
160:                 }
161: 
162:                 if (horizWithOpeningsRefs.Size > horizWallRefs.Size && horizWithOpeningsRefs.Size >= 2)
163:                 {
164:                     try
165:                     {
166:                         XYZ shiftCenter = center + XYZ.BasisX * offsetFeet;
167:                         Line yLine = Line.CreateBound(shiftCenter - XYZ.BasisY * 50.0, shiftCenter + XYZ.BasisY * 50.0);
168:                         Dimension d = doc.Create.NewDimension(view, yLine, horizWithOpeningsRefs, dimType);
169:                         if (d != null) createdDims++;
170:                     }
171:                     catch { }
172:                 }
173:             }
174: 
175:             return createdDims;
176:         }
