178:         public static int DimensionExteriorInPlan(
179:             Document doc,
180:             View view,
181:             DimensionType dimType,
182:             bool chainGrids,
183:             bool chainWalls,
184:             double baseOffsetMm,
185:             double stackStepMm)
186:         {
187:             if (doc == null || view == null) return 0;
188: 
189:             var walls = new FilteredElementCollector(doc, view.Id)
190:                 .OfClass(typeof(Wall))
191:                 .Cast<Wall>()
192:                 .ToList();
193: 
194:             var grids = new FilteredElementCollector(doc, view.Id)
195:                 .OfClass(typeof(Grid))
196:                 .Cast<Grid>()
197:                 .ToList();
198: 
199:             if (walls.Count == 0 && grids.Count == 0) return 0;
200: 
201:             double minX = double.MaxValue, maxX = double.MinValue;
202:             double minY = double.MaxValue, maxY = double.MinValue;
203:             double z = view.GenLevel != null ? view.GenLevel.Elevation : 0.0;
204: 
205:             foreach (Wall w in walls)
206:             {
207:                 BoundingBoxXYZ bb = w.get_BoundingBox(view);
208:                 if (bb == null) continue;
209:                 minX = Math.Min(minX, bb.Min.X);
210:                 maxX = Math.Max(maxX, bb.Max.X);
211:                 minY = Math.Min(minY, bb.Min.Y);
212:                 maxY = Math.Max(maxY, bb.Max.Y);
213:             }
214: 
215:             if (minX == double.MaxValue) return 0;
216: 
217:             double baseOffFeet = UnitUtils.ConvertToInternalUnits(Math.Max(600, baseOffsetMm), UnitTypeId.Millimeters);
218:             double stepFeet = UnitUtils.ConvertToInternalUnits(Math.Max(400, stackStepMm), UnitTypeId.Millimeters);
219:             int created = 0;
220: 
221:             // 1. Grids Chain (Horizontal X and Vertical Y)
222:             if (chainGrids && grids.Count >= 2)
223:             {
224:                 var xGridRefs = new ReferenceArray();
225:                 var yGridRefs = new ReferenceArray();
226: 
227:                 foreach (Grid g in grids)
228:                 {
229:                     if (!(g.Curve is Line gl)) continue;
