231:                     Reference gRef = new Reference(g);
232:                     if (Math.Abs(dir.Y) >= 0.85) xGridRefs.Append(gRef);
233:                     else if (Math.Abs(dir.X) >= 0.85) yGridRefs.Append(gRef);
234:                 }
235: 
236:                 if (xGridRefs.Size >= 2)
237:                 {
238:                     try
239:                     {
240:                         double yPos = maxY + baseOffFeet;
241:                         Line dimLine = Line.CreateBound(new XYZ(minX - 10, yPos, z), new XYZ(maxX + 10, yPos, z));
242:                         if (doc.Create.NewDimension(view, dimLine, xGridRefs, dimType) != null) created++;
243:                     }
244:                     catch { }
245:                 }
246: 
247:                 if (yGridRefs.Size >= 2)
248:                 {
249:                     try
250:                     {
251:                         double xPos = minX - baseOffFeet;
252:                         Line dimLine = Line.CreateBound(new XYZ(xPos, minY - 10, z), new XYZ(xPos, maxY + 10, z));
253:                         if (doc.Create.NewDimension(view, dimLine, yGridRefs, dimType) != null) created++;
254:                     }
255:                     catch { }
256:                 }
257:             }
258: 
259:             // 2. Exterior Wall Segments Chain
260:             if (chainWalls && walls.Count >= 2)
261:             {
262:                 var xWallRefs = new ReferenceArray();
263:                 var yWallRefs = new ReferenceArray();
264: 
265:                 foreach (Wall w in walls)
266:                 {
267:                     if (!(w.Location is LocationCurve lc) || !(lc.Curve is Line wl)) continue;
268:                     XYZ dir = (wl.GetEndPoint(1) - wl.GetEndPoint(0)).Normalize();
269:                     Reference faceRef = GetWallFaceReference(w, true);
270:                     if (faceRef == null) continue;
271: 
272:                     if (Math.Abs(dir.Y) >= 0.9) xWallRefs.Append(faceRef);
273:                     else if (Math.Abs(dir.X) >= 0.9) yWallRefs.Append(faceRef);
274:                 }
275: 
276:                 if (xWallRefs.Size >= 2)
277:                 {
278:                     try
