371:         // 2. GOAT ANNOTATE ENGINE (Smart Multi-Category Tagging + Anti-Collision)
372:         // =========================================================================
373: 
374:         public static int TagElementsInView(
375:             Document doc,
376:             View view,
377:             IList<BuiltInCategory> categories,
378:             bool addLeader,
379:             bool preventCollisions,
380:             bool tagRooms)
381:         {
382:             if (doc == null || view == null) return 0;
383:             int createdTags = 0;
384:             var placedTagCenters = new List<XYZ>();
385:             double minTagDistFeet = UnitUtils.ConvertToInternalUnits(550.0, UnitTypeId.Millimeters);
386: 
387:             // 1. Tag Rooms if requested
388:             if (tagRooms && (view.ViewType == ViewType.FloorPlan || view.ViewType == ViewType.CeilingPlan || view.ViewType == ViewType.Section || view.ViewType == ViewType.Elevation))
389:             {
390:                 var existingTaggedRoomIds = new FilteredElementCollector(doc, view.Id)
391:                     .OfClass(typeof(SpatialElementTag))
392:                     .OfType<RoomTag>()
393:                     .Where(rt => rt.Room != null)
394:                     .Select(rt => rt.Room.Id.Value)
395:                     .ToHashSet();
396: 
397:                 var rooms = new FilteredElementCollector(doc, view.Id)
398:                     .OfCategory(BuiltInCategory.OST_Rooms)
399:                     .WhereElementIsNotElementType()
400:                     .OfType<Room>()
401:                     .Where(r => r.Area > 0.001 && r.Location is LocationPoint);
402: 
403:                 foreach (Room r in rooms)
404:                 {
405:                     if (existingTaggedRoomIds.Contains(r.Id.Value)) continue;
406:                     if (!(r.Location is LocationPoint lp)) continue;
407:                     try
408:                     {
409:                         RoomTag rt = doc.Create.NewRoomTag(new LinkElementId(r.Id), new UV(lp.Point.X, lp.Point.Y), view.Id);
410:                         if (rt != null)
411:                         {
412:                             placedTagCenters.Add(lp.Point);
413:                             createdTags++;
414:                         }
415:                     }
416:                     catch { }
417:                 }
418:             }
419: 
420:             // 2. Tag Selected Model Categories with Anti-Collision Engine
421:             if (categories != null && categories.Count > 0)
422:             {
423:                 // Collect already tagged elements in this view so we never create duplicate tags
424:                 var alreadyTaggedIds = new HashSet<long>();
425:                 var existingTags = new FilteredElementCollector(doc, view.Id)
426:                     .OfClass(typeof(IndependentTag))
427:                     .Cast<IndependentTag>();
428: 
429:                 foreach (IndependentTag t in existingTags)
430:                 {
431:                     try
432:                     {
433:                         foreach (LinkElementId lid in t.GetTaggedElementIds())
434:                         {
435:                             if (lid.HostElementId != ElementId.InvalidElementId)
436:                                 alreadyTaggedIds.Add(lid.HostElementId.Value);
437:                         }
438:                         placedTagCenters.Add(t.TagHeadPosition);
439:                     }
440:                     catch { }
441:                 }
442: 
443:                 foreach (BuiltInCategory bic in categories)
444:                 {
445:                     if (bic == BuiltInCategory.OST_Rooms) continue;
446: 
447:                     var elements = new FilteredElementCollector(doc, view.Id)
448:                         .OfCategory(bic)
449:                         .WhereElementIsNotElementType()
450:                         .ToList();
451: 
452:                     foreach (Element el in elements)
453:                     {
454:                         if (alreadyTaggedIds.Contains(el.Id.Value)) continue;
455: 
456:                         XYZ rawPos = GetElementCenterInView(el, view);
457:                         if (rawPos == null) continue;
458: 
459:                         XYZ finalTagPos = preventCollisions
460:                             ? FindNonCollidingTagPoint(rawPos, placedTagCenters, minTagDistFeet, view)
461:                             : rawPos;
462: 
463:                         bool needsLeader = addLeader || finalTagPos.DistanceTo(rawPos) > 0.15;
464: 
465:                         try
466:                         {
467:                             Reference elRef = new Reference(el);
468:                             IndependentTag tag = IndependentTag.Create(
469:                                 doc,
470:                                 view.Id,
471:                                 elRef,
472:                                 needsLeader,
473:                                 TagMode.TM_ADDBY_CATEGORY,
474:                                 TagOrientation.Horizontal,
475:                                 finalTagPos);
476: 
477:                             if (tag != null)
478:                             {
479:                                 placedTagCenters.Add(finalTagPos);
480:                                 alreadyTaggedIds.Add(el.Id.Value);
481:                                 createdTags++;
482:                             }
483:                         }
484:                         catch { }
485:                     }
486:                 }
487:             }
488: 
489:             return createdTags;
490:         }
