492:         private static XYZ GetElementCenterInView(Element el, View view)
493:         {
494:             if (el.Location is LocationPoint lp)
495:                 return lp.Point;
496:             if (el.Location is LocationCurve lc && lc.Curve != null)
497:                 return lc.Curve.Evaluate(0.5, true);
498: 
499:             BoundingBoxXYZ bb = el.get_BoundingBox(view) ?? el.get_BoundingBox(null);
500:             if (bb != null)
501:                 return (bb.Min + bb.Max) * 0.5;
502: 
503:             return null;
504:         }
