506:         private static XYZ FindNonCollidingTagPoint(XYZ origin, List<XYZ> occupied, double minDistFeet, View view)
507:         {
508:             bool Overlaps(XYZ pt)
509:             {
510:                 foreach (XYZ occ in occupied)
511:                 {
512:                     double dx = pt.X - occ.X;
513:                     double dy = pt.Y - occ.Y;
514:                     if (Math.Sqrt(dx * dx + dy * dy) < minDistFeet)
515:                         return true;
516:                 }
517:                 return false;
518:             }
519: 
520:             if (!Overlaps(origin)) return origin;
521: 
522:             XYZ right = view.RightDirection;
523:             XYZ up = view.UpDirection;
524: 
525:             // Spiral / radial search in view plane
526:             double[] radii = { minDistFeet, minDistFeet * 1.6, minDistFeet * 2.3, minDistFeet * 3.0 };
527:             double[] anglesDeg = { 45, -45, 135, -135, 0, 90, 180, -90 };
528: 
529:             foreach (double r in radii)
530:             {
531:                 foreach (double deg in anglesDeg)
532:                 {
533:                     double rad = deg * Math.PI / 180.0;
534:                     XYZ candidate = origin + right * (r * Math.Cos(rad)) + up * (r * Math.Sin(rad));
535:                     if (!Overlaps(candidate))
536:                         return candidate;
537:                 }
538:             }
539: 
540:             return origin + up * minDistFeet;
541:         }
