547:         public static int PackViewsOntoSheet(
548:             Document doc,
549:             ViewSheet sheet,
550:             IList<ElementId> viewIdsToPlaceAndPack,
551:             bool packExistingViewportsOnly = false)
552:         {
553:             if (doc == null || sheet == null) return 0;
554: 
555:             var viewports = new List<Viewport>();
556: 
557:             if (!packExistingViewportsOnly && viewIdsToPlaceAndPack != null)
558:             {
559:                 foreach (ElementId vid in viewIdsToPlaceAndPack)
560:                 {
561:                     if (vid == null || vid == ElementId.InvalidElementId) continue;
562:                     if (Viewport.CanAddViewToSheet(doc, sheet.Id, vid))
563:                     {
564:                         try
565:                         {
566:                             Viewport vp = Viewport.Create(doc, sheet.Id, vid, XYZ.Zero);
567:                             if (vp != null) viewports.Add(vp);
568:                         }
569:                         catch { }
570:                     }
571:                 }
572:             }
573: 
574:             if (packExistingViewportsOnly || viewports.Count == 0)
575:             {
576:                 foreach (ElementId vpId in sheet.GetAllViewports())
577:                 {
578:                     if (doc.GetElement(vpId) is Viewport vp)
579:                         viewports.Add(vp);
580:                 }
581:             }
582: 
583:             if (viewports.Count == 0) return 0;
584: 
585:             // Determine Titleblock usable drawing area
586:             double minX = 0.12, minY = 0.12;
587:             double maxX = 2.40, maxY = 1.80; // Default A1 usable space in feet
588: 
589:             var titleBlocks = new FilteredElementCollector(doc, sheet.Id)
590:                 .OfCategory(BuiltInCategory.OST_TitleBlocks)
591:                 .WhereElementIsNotElementType()
592:                 .ToList();
593: 
594:             if (titleBlocks.Count > 0)
595:             {
596:                 BoundingBoxXYZ tbb = titleBlocks[0].get_BoundingBox(sheet);
597:                 if (tbb != null)
598:                 {
599:                     double w = tbb.Max.X - tbb.Min.X;
600:                     double h = tbb.Max.Y - tbb.Min.Y;
601:                     minX = tbb.Min.X + w * 0.05;
602:                     maxX = tbb.Max.X - w * 0.16; // Reserve right titleblock strip
603:                     minY = tbb.Min.Y + h * 0.06;
604:                     maxY = tbb.Max.Y - h * 0.05;
605:                 }
606:             }
607: 
608:             int count = viewports.Count;
609:             int cols = count <= 2 ? count : (count <= 4 ? 2 : (count <= 6 ? 3 : 4));
610:             int rows = (int)Math.Ceiling((double)count / cols);
611: 
612:             double cellW = (maxX - minX) / cols;
613:             double cellH = (maxY - minY) / rows;
614: 
615:             for (int i = 0; i < count; i++)
616:             {
617:                 int r = i / cols;
618:                 int c = i % cols;
619: 
620:                 double cx = minX + (c + 0.5) * cellW;
621:                 // Top row first (rows - 1 - r)
622:                 double cy = minY + (rows - 1 - r + 0.5) * cellH;
623: 
624:                 try
625:                 {
626:                     viewports[i].SetBoxCenter(new XYZ(cx, cy, 0));
627:                 }
628:                 catch { }
629:             }
630: 
631:             return viewports.Count;
632:         }
633:     }
