210:         private void ExecuteInteractivePick(UIDocument uidoc, Document doc)
211:         {
212:             int catIdx = Window.CbCategory.SelectedIndex >= 0 ? Window.CbCategory.SelectedIndex : 0;
213:             string prefix = Window.TxtPrefix.Text ?? "";
214:             string suffix = Window.TxtSuffix.Text ?? "";
215:             int.TryParse(Window.TxtStartNum.Text, out int currentNum);
216:             if (currentNum <= 0) currentNum = 1;
217:             int.TryParse(Window.TxtStep.Text, out int step);
218:             if (step == 0) step = 1;
219:             int.TryParse(Window.TxtPadding.Text, out int pad);
220:             pad = Math.Clamp(pad, 1, 8);
221: 
222:             int pickedCount = 0;
223:             using (TransactionGroup tg = new TransactionGroup(doc, "GOAT RENUMBER — Interactive Pick"))
224:             {
225:                 tg.Start();
226:                 while (true)
227:                 {
228:                     Reference pickedRef = null;
229:                     string nextVal = $"{prefix}{currentNum.ToString().PadLeft(pad, '0')}{suffix}";
230:                     try
231:                     {
232:                         pickedRef = uidoc.Selection.PickObject(ObjectType.Element, $"Click element to assign '{nextVal}' (Press ESC to finish)");
233:                     }
234:                     catch
235:                     {
236:                         break;
237:                     }
238: 
239:                     if (pickedRef == null) break;
240:                     Element el = doc.GetElement(pickedRef.ElementId);
241:                     if (el == null) continue;
242: 
243:                     using (Transaction t = new Transaction(doc, $"Assign {nextVal}"))
244:                     {
245:                         t.Start();
246:                         if (SetElementNumberValue(el, catIdx, nextVal))
247:                         {
248:                             currentNum += step;
249:                             pickedCount++;
250:                         }
251:                         t.Commit();
252:                     }
253:                 }
254:                 tg.Assimilate();
255:             }
256: 
257:             ExecuteScan(doc);
258:             Window.TxtStatus.Text = $"✔ Interactive Pick finished: renumbered {pickedCount} elements. (1x Ctrl+Z to Undo)";
