385:         private void RecalculateProposedNumbers()
386:         {
387:             if (Rows.Count == 0) return;
388: 
389:             string prefix = TxtPrefix.Text ?? "";
390:             string suffix = TxtSuffix.Text ?? "";
391:             int.TryParse(TxtStartNum.Text, out int startNum);
392:             if (startNum <= 0) startNum = 1;
393:             int.TryParse(TxtStep.Text, out int step);
394:             if (step == 0) step = 1;
395:             int.TryParse(TxtPadding.Text, out int pad);
396:             pad = Math.Clamp(pad, 1, 8);
397: 
398:             bool byRoom = RbModeByHostRoom.IsChecked == true;
399:             bool alphaRoomSuffix = CbRoomSuffixStyle.SelectedIndex == 0;
400: 
401:             // Sort rows according to chosen spatial scan
402:             List<RenumberRowItem> sorted;
403:             if (RbModeSpatialYX.IsChecked == true)
404:             {
405:                 sorted = Rows.OrderByDescending(r => Math.Round(r.Y / 2.0)).ThenBy(r => r.X).ToList();
406:             }
407:             else
408:             {
409:                 sorted = Rows.OrderBy(r => Math.Round(r.Y / 2.0)).ThenBy(r => r.X).ToList();
410:             }
411: 
412:             Rows.Clear();
413:             foreach (var item in sorted) Rows.Add(item);
414: 
415:             if (byRoom)
416:             {
417:                 var groups = Rows.Where(r => r.IsSelected).GroupBy(r => string.IsNullOrWhiteSpace(r.HostRoomNumber) ? "UNASSIGNED" : r.HostRoomNumber);
418:                 foreach (var grp in groups)
419:                 {
420:                     var items = grp.ToList();
421:                     for (int i = 0; i < items.Count; i++)
422:                     {
423:                         string roomNum = grp.Key;
424:                         if (items.Count == 1)
425:                         {
426:                             items[i].ProposedNumber = $"{prefix}{roomNum}{suffix}";
427:                         }
428:                         else
429:                         {
430:                             string multiTag = alphaRoomSuffix
431:                                 ? ((char)('A' + (i % 26))).ToString()
432:                                 : $"-{i + 1}";
433:                             items[i].ProposedNumber = $"{prefix}{roomNum}{multiTag}{suffix}";
434:                         }
435:                     }
436:                 }
437:             }
438:             else
439:             {
440:                 int current = startNum;
441:                 foreach (var item in Rows)
442:                 {
443:                     if (!item.IsSelected)
444:                     {
445:                         item.ProposedNumber = "";
446:                         continue;
447:                     }
448:                     item.ProposedNumber = $"{prefix}{current.ToString().PadLeft(pad, '0')}{suffix}";
449:                     current += step;
450:                 }
451:             }
