109:         private void ExecuteScan(Document doc)
110:         {
111:             // 1. Ceiling Types
112:             var ceilingTypes = new FilteredElementCollector(doc)
113:                 .OfClass(typeof(CeilingType))
114:                 .Cast<CeilingType>()
115:                 .OrderBy(c => c.Name)
116:                 .Select(c => new ElementTypeOption { Id = c.Id, Name = c.Name })
117:                 .ToList();
118: 
119:             // 2. Lighting Fixture Symbols
120:             var lightingSymbols = CollectFamilySymbols(doc, BuiltInCategory.OST_LightingFixtures);
121: 
122:             // 3. Air Terminal (Diffuser) Symbols
123:             var diffuserSymbols = CollectFamilySymbols(doc, BuiltInCategory.OST_DuctTerminal);
124: 
125:             // 4. Sprinkler / Fire Alarm Symbols
126:             var sprinklerSymbols = CollectFamilySymbols(doc, BuiltInCategory.OST_Sprinklers);
127:             if (sprinklerSymbols.Count == 0)
128:             {
129:                 sprinklerSymbols = CollectFamilySymbols(doc, BuiltInCategory.OST_FireAlarmDevices);
130:             }
131: 
132:             // 5. Existing Ceilings in Model for spatial room matching
133:             var existingCeilings = new FilteredElementCollector(doc)
134:                 .OfClass(typeof(Ceiling))
135:                 .Cast<Ceiling>()
136:                 .ToList();
137: 
138:             // 6. Rooms
139:             bool activeOnly = Window.IsActiveViewScope;
140:             FilteredElementCollector roomCollector = (activeOnly && doc.ActiveView != null)
141:                 ? new FilteredElementCollector(doc, doc.ActiveView.Id)
142:                 : new FilteredElementCollector(doc);
143: 
144:             var rooms = roomCollector
145:                 .OfCategory(BuiltInCategory.OST_Rooms)
146:                 .WhereElementIsNotElementType()
147:                 .OfType<Room>()
148:                 .Where(r => r.Area > 0.001 && r.Location != null)
149:                 .OrderBy(r => r.Number)
150:                 .ToList();
151: 
152:             var roomItems = new List<CeilingRoomItem>();
153:             foreach (Room r in rooms)
154:             {
155:                 BoundingBoxXYZ bb = r.get_BoundingBox(null);
156:                 double minX = bb != null ? bb.Min.X : -10;
157:                 double maxX = bb != null ? bb.Max.X : 10;
158:                 double minY = bb != null ? bb.Min.Y : -8;
159:                 double maxY = bb != null ? bb.Max.Y : 8;
160: 
161:                 // Check if any ceiling's bbox center falls inside this room
162:                 Ceiling matchedCeiling = null;
163:                 double ceilHmm = 2700.0;
164:                 foreach (Ceiling c in existingCeilings)
165:                 {
166:                     if (c.LevelId != r.LevelId) continue;
167:                     BoundingBoxXYZ cbb = c.get_BoundingBox(null);
168:                     if (cbb == null) continue;
169:                     XYZ mid = (cbb.Min + cbb.Max) * 0.5;
170:                     XYZ testPt = new XYZ(mid.X, mid.Y, (bb != null ? bb.Min.Z : 0) + 1.0);
171:                     if (r.IsPointInRoom(testPt))
172:                     {
173:                         matchedCeiling = c;
174:                         Parameter hp = c.get_Parameter(BuiltInParameter.CEILING_HEIGHTABOVELEVEL_PARAM);
175:                         if (hp != null)
176:                             ceilHmm = Math.Round(UnitUtils.ConvertFromInternalUnits(hp.AsDouble(), UnitTypeId.Millimeters), 0);
177:                         break;
178:                     }
179:                 }
180: 
181:                 roomItems.Add(new CeilingRoomItem
182:                 {
183:                     IsSelected = true,
184:                     RoomId = r.Id,
185:                     LevelId = r.LevelId,
186:                     RoomNumber = r.Number ?? "",
187:                     RoomName = r.get_Parameter(BuiltInParameter.ROOM_NAME)?.AsString() ?? r.Name ?? "Room",
188:                     AreaSqm = Math.Round(UnitUtils.ConvertFromInternalUnits(r.Area, UnitTypeId.SquareMeters), 2),
189:                     HasExistingCeiling = matchedCeiling != null,
190:                     ExistingCeilingId = matchedCeiling != null ? matchedCeiling.Id : ElementId.InvalidElementId,
191:                     ExistingCeilingHeightMm = ceilHmm,
192:                     MinXFeet = minX,
193:                     MaxXFeet = maxX,
194:                     MinYFeet = minY,
195:                     MaxYFeet = maxY
196:                 });
197:             }
198: 
199:             Window.ApplyScannedData(ceilingTypes, lightingSymbols, diffuserSymbols, sprinklerSymbols, roomItems);
200:         }
