541:         private static bool ClashesWithColumn(double x, double y, double z, List<BoundingBoxXYZ> colBoxes)
542:         {
543:             double pad = 0.5; // ~150mm clearance around columns
544:             foreach (var bb in colBoxes)
545:             {
546:                 if (z >= bb.Min.Z - 2.0 && z <= bb.Max.Z + 2.0)
547:                 {
548:                     if (x >= bb.Min.X - pad && x <= bb.Max.X + pad &&
549:                         y >= bb.Min.Y - pad && y <= bb.Max.Y + pad)
550:                     {
551:                         return true;
552:                     }
553:                 }
554:             }
555:             return false;
556:         }
