558:         private static CurveLoop BuildClosedLoop(IList<BoundarySegment> segments, double z)
559:         {
560:             var pts = new List<XYZ>();
561:             foreach (var seg in segments)
562:             {
563:                 Curve c = seg.GetCurve();
564:                 if (c == null) continue;
565:                 XYZ p = new XYZ(c.GetEndPoint(0).X, c.GetEndPoint(0).Y, z);
566:                 if (pts.Count == 0 || pts[pts.Count - 1].DistanceTo(p) > 0.01)
567:                     pts.Add(p);
568:             }
569:             if (pts.Count > 3 && pts[0].DistanceTo(pts[pts.Count - 1]) <= 0.01)
570:                 pts.RemoveAt(pts.Count - 1);
571:             if (pts.Count < 3) return null;
572: 
573:             CurveLoop loop = new CurveLoop();
574:             for (int i = 0; i < pts.Count; i++)
575:             {
576:                 XYZ a = pts[i];
577:                 XYZ b = pts[(i + 1) % pts.Count];
578:                 if (a.DistanceTo(b) > 0.005)
579:                     loop.Append(Line.CreateBound(a, b));
580:             }
581:             return loop;
582:         }
